def test_fixed_global_camera_heading_projection_uses_physics_yaw():
    projection = _fixed_global_camera_heading_projection(
        {
            "robots": {
                "front": {"yaw_deg": -34.5},
                "back": {"yaw_deg": -36.0},
            }
        }
    )

    assert projection["current"]["screen_heading"] == "up-left"
    assert projection["clockwise"]["screen_heading"] == "up-left"
    assert projection["counterclockwise"]["screen_heading"] == "left"
    assert projection["clockwise"]["world_yaw_deg"] == pytest.approx(-65.25)
    assert projection["counterclockwise"]["world_yaw_deg"] == pytest.approx(-5.25)
    translations = projection["body_frame_translation_candidates"]
    assert translations["forward"]["screen_heading"] == "up-left"
    assert translations["backward"]["screen_heading"] == "down-right"
    assert translations["left"]["screen_heading"] == "down-left"
    assert translations["right"]["screen_heading"] == "up-right"


def test_turn_evidence_must_compare_both_physics_projected_candidates():
    projection = _fixed_global_camera_heading_projection(
        {
            "robots": {
                "front": {"yaw_deg": -34.5},
                "back": {"yaw_deg": -36.0},
            }
        }
    )
    with pytest.raises(ModelAgentError, match="host-projected candidates"):
        _validated_turn_direction_evidence(
            {
                "direction_evidence": (
                    "The passage appears on the image right, so clockwise turns toward it."
                ),
                "alternative_direction": "counterclockwise",
                "alternative_rejection_reason": (
                    "Counterclockwise would point away from the visible passage."
                ),
            },
            selected_direction="clockwise",
            heading_projection=projection,
        )

    evidence = _validated_turn_direction_evidence(
        {
            "direction_evidence": (
                "The host-projected candidates are clockwise -> up-left and "
                "counterclockwise -> left; the connected passage follows left, so the "
                "counterclockwise projection matches it while clockwise stays up-left."
            ),
            "alternative_direction": "clockwise",
            "alternative_rejection_reason": (
                "The clockwise up-left candidate points toward the visible wall."
            ),
        },
        selected_direction="counterclockwise",
        heading_projection=projection,
    )

    assert evidence["direction_evidence_source"] == "model_direction_evidence"


