def test_checkpoint_local_action_space_exhaustion_is_narrowly_classified():
    assert _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError(
            "no legal coordination primitive objective remains after physical budget exclusions"
        )
    )
    assert _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError(
            "all coordination modes for api.coordinated_pivot exhausted "
            "their physical budgets"
        )
    )
    assert _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError(
            "no model-selectable SDK methods remain after verifier exclusions"
        )
    )
    assert _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError(
            "model failed executable team-plan validation after 5 response(s): "
            "repaired policy repeats a verifier-rejected executable transaction "
            "at AST level"
        )
    )
    assert _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError(
            "code_repair failed structured validation after 5 response(s): "
            "generated policy repeats the exact verifier-rejected executable AST"
        )
    )
    assert _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError(
            "model failed executable team-plan validation after 5 response(s): "
            "the previous body-frame movement increased active-goal distance; "
            "do not repeat api.recover_payload_inward with different numerical parameters"
        )
    )
    assert not _is_checkpoint_local_action_space_exhaustion(
        ModelAgentError("model response is not valid JSON")
    )
    assert not _is_checkpoint_local_action_space_exhaustion(
        RuntimeError("transport failed")
    )


def test_persisted_checkpoint_loader_requires_a_valid_pair(tmp_path):
    checkpoint_id = "accepted_step_37"
    metadata = {
        "checkpoint_id": checkpoint_id,
        "state_spec": 16383,
        "state_size": 3,
    }
    (tmp_path / f"{checkpoint_id}.json").write_text(
        json.dumps(metadata), encoding="utf-8"
    )
    np.savez_compressed(
        tmp_path / f"{checkpoint_id}.npz",
        state=np.asarray([1.0, 2.0, 3.0]),
        state_spec=np.asarray([16383]),
    )
    (tmp_path / "orphan.json").write_text(
        json.dumps({"checkpoint_id": "orphan", "state_spec": 1, "state_size": 1}),
        encoding="utf-8",
    )
    (tmp_path / "mismatch.json").write_text(
        json.dumps({"checkpoint_id": "wrong", "state_spec": 1, "state_size": 1}),
        encoding="utf-8",
    )
    np.savez_compressed(
        tmp_path / "mismatch.npz",
        state=np.asarray([1.0]),
        state_spec=np.asarray([1]),
    )

    loaded, rejected = load_persisted_checkpoints(tmp_path)

    assert set(loaded) == {checkpoint_id}
    assert loaded[checkpoint_id].state.tolist() == [1.0, 2.0, 3.0]
    assert any("orphan: incomplete JSON/NPZ pair" in item for item in rejected)
    assert any("mismatch: metadata checkpoint_id" in item for item in rejected)


def test_checkpoint_resync_exactly_holds_free_joint_pose_and_velocity():
    data = SimpleNamespace(
        qpos=np.arange(18, dtype=np.float64),
        qvel=np.arange(16, dtype=np.float64),
        qacc=np.ones(16, dtype=np.float64),
        qacc_warmstart=np.ones(16, dtype=np.float64),
    )
    qpos_target = np.asarray([1.0, 2.0, 3.0, 1.0, 0.0, 0.0, 0.0])
    qvel_target = np.zeros(6, dtype=np.float64)

    enforce_free_joint_state(
        data,
        qpos_adr=4,
        dof_adr=3,
        qpos_target=qpos_target,
        qvel_target=qvel_target,
    )

    assert np.array_equal(data.qpos[4:11], qpos_target)
    assert np.array_equal(data.qvel[3:9], qvel_target)
    assert np.array_equal(data.qacc[3:9], np.zeros(6))
    assert np.array_equal(data.qacc_warmstart[3:9], np.zeros(6))


