def test_checkpoint_client_retries_same_event_until_term1_acknowledges(
    tmp_path,
    monkeypatch,
):
    heartbeat_file = tmp_path / "planner_heartbeat.json"
    runtime_state_file = tmp_path / "runtime_state.json"
    writes: list[dict] = []
    original_write = __import__(
        "praxis_coop.cap_policy.checkpoints",
        fromlist=["_atomic_write_json"],
    )._atomic_write_json

    def delayed_ack(path, payload):
        writes.append(dict(payload))
        original_write(path, payload)
        if len(writes) == 3:
            runtime_state_file.write_text(
                json.dumps(
                    {
                        "checkpoint": {
                            "event_id": payload["checkpoint_event_id"],
                            "checkpoint_id": payload["checkpoint_id"],
                            "success": True,
                            "error": "",
                        }
                    }
                ),
                encoding="utf-8",
            )

    monkeypatch.setattr(
        "praxis_coop.cap_policy.checkpoints._atomic_write_json",
        delayed_ack,
    )
    client = SimulatorCheckpointClient(
        heartbeat_file=heartbeat_file,
        runtime_state_file=runtime_state_file,
        artifact_dir=tmp_path / "events",
        timeout_s=0.5,
        poll_s=0.01,
        resend_s=0.02,
        restore_settle_s=0.0,
    )

    result = client.restore("accepted_step_45")

    assert result.success
    assert len(writes) == 4
    request_writes = writes[:3]
    assert {item["checkpoint_event_id"] for item in request_writes} == {result.event_id}
    assert all(item["checkpoint_id"] == "accepted_step_45" for item in request_writes)
    assert writes[-1]["phase"] == "sim_checkpoint_event_cleared"
    assert "checkpoint_event_id" not in writes[-1]


def test_checkpoint_client_fails_fast_when_term1_state_stops_advancing(
    tmp_path,
):
    heartbeat_file = tmp_path / "planner_heartbeat.json"
    runtime_state_file = tmp_path / "runtime_state.json"
    runtime_state_file.write_text(
        json.dumps(
            {
                "runtime_instance_id": "term1-a",
                "state_sequence": 41,
                "runtime_status": "running",
                "runtime_fault": {},
                "time_unix": time.time() - 5.0,
                "checkpoint": {"event_id": "old-event"},
            }
        ),
        encoding="utf-8",
    )
    client = SimulatorCheckpointClient(
        heartbeat_file=heartbeat_file,
        runtime_state_file=runtime_state_file,
        artifact_dir=tmp_path / "events",
        timeout_s=5.0,
        poll_s=0.01,
        resend_s=0.02,
        runtime_state_max_age_s=0.1,
        backend_stale_grace_s=0.02,
    )

    started = time.monotonic()
    with pytest.raises(
        CheckpointBackendFatalError,
        match="runtime state stopped advancing",
    ):
        client.restore("accepted_step_17")

    assert time.monotonic() - started < 1.0
    artifact = next((tmp_path / "events").glob("restore_accepted_step_17_*.json"))
    payload = json.loads(artifact.read_text(encoding="utf-8"))
    assert payload["success"] is False


def test_checkpoint_restore_can_clear_latched_numerical_fault(
    tmp_path,
    monkeypatch,
):
    heartbeat_file = tmp_path / "planner_heartbeat.json"
    runtime_state_file = tmp_path / "runtime_state.json"
    original_write = __import__(
        "praxis_coop.cap_policy.checkpoints",
        fromlist=["_atomic_write_json"],
    )._atomic_write_json

    def acknowledge_restore(path, payload):
        original_write(path, payload)
        if payload.get("checkpoint_action") == "restore":
            runtime_state_file.write_text(
                json.dumps(
                    {
                        "runtime_instance_id": "term1-a",
                        "state_sequence": 42,
                        "runtime_status": "running",
                        "runtime_fault": {},
                        "time_unix": time.time(),
                        "checkpoint": {
                            "event_id": payload["checkpoint_event_id"],
                            "success": True,
                            "error": "",
                        },
                    }
                ),
                encoding="utf-8",
            )

    runtime_state_file.write_text(
        json.dumps(
            {
                "runtime_instance_id": "term1-a",
                "state_sequence": 41,
                "runtime_status": "running",
                "runtime_fault": {"type": "numerical_instability"},
                "time_unix": time.time(),
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(
        "praxis_coop.cap_policy.checkpoints._atomic_write_json",
        acknowledge_restore,
    )
    client = SimulatorCheckpointClient(
        heartbeat_file=heartbeat_file,
        runtime_state_file=runtime_state_file,
        artifact_dir=tmp_path / "events",
        timeout_s=0.5,
        poll_s=0.01,
        resend_s=0.02,
    )

    assert client.restore("accepted_step_17").success


def test_startup_checkpoint_restore_waits_for_exact_state_hold(tmp_path, monkeypatch):
    calls: list[object] = []
    result = SimpleNamespace(event_id="restore_event")
    checkpoint_client = SimpleNamespace(
        restore_settle_s=8.0,
        restore=lambda checkpoint_id: (
            calls.append(("restore", checkpoint_id)) or result
        ),
    )

    def record_wait(_path, *, checkpoint_id, timeout_s):
        calls.append(("wait", checkpoint_id, timeout_s))
        return {"checkpoint": {"checkpoint_id": checkpoint_id, "resync_active": False}}

    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution._wait_for_checkpoint_resync_complete",
        record_wait,
    )

    restored = _restore_checkpoint_and_wait_for_release(
        checkpoint_client=checkpoint_client,
        checkpoint_id="accepted_step_03",
        runtime_state_file=tmp_path / "runtime_state.json",
        timeout_s=5.0,
    )

    assert restored is result
    assert calls == [
        ("restore", "accepted_step_03"),
        ("wait", "accepted_step_03", 10.0),
    ]


