def test_checkpoint_restore_forwards_task_profile_without_strict_overrides(
    monkeypatch,
    tmp_path,
):
    sequence: list[str] = []
    reference_state = _relaxed_supported_runtime_state()
    reference_state["checkpoint"] = {
        "checkpoint_id": "accepted_step_08",
        "resync_active": False,
    }
    checkpoint_client = SimpleNamespace(
        restore_settle_s=0.0,
        restore=lambda _checkpoint_id, **_kwargs: (
            sequence.append("restore")
            or SimpleNamespace(
                event_id=f"restore_{len(sequence)}",
                runtime_state_after=reference_state,
            )
        ),
    )
    backend = SimpleNamespace(
        resynchronize_idle=lambda **_kwargs: (
            sequence.append("planner_resync") or {"status": "ok"}
        ),
    )
    captured: dict[str, object] = {}

    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution._wait_for_checkpoint_resync_complete",
        lambda *_args, **_kwargs: (
            sequence.append("wait_for_release") or reference_state
        ),
    )
    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution.wait_for_payload_supported",
        lambda _path, **kwargs: captured.update(kwargs),
    )
    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution.read_json",
        lambda _path: reference_state,
    )
    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution._checkpoint_pose_verification",
        lambda *_args, **_kwargs: {
            "payload_xy_error_m": 0.0,
            "max_robot_xy_error_m": 0.0,
            "max_yaw_error_deg": 0.0,
            "within_tolerance": True,
        },
    )

    result = _restore_and_resynchronize(
        checkpoint_client=checkpoint_client,
        backend=backend,
        checkpoint_id="accepted_step_08",
        checkpoint_reference_state=reference_state,
        attempt_dir=tmp_path / "attempt",
        heartbeat_file=tmp_path / "heartbeat.json",
        runtime_state_file=tmp_path / "runtime_state.json",
        idle_s=0.0,
        max_payload_xy_error_m=0.06,
        max_robot_xy_error_m=0.06,
        max_z_error_m=0.03,
        max_yaw_error_deg=5.0,
        safety_profile="task",
    )

    assert result["within_tolerance"] is True
    assert sequence == ["restore", "planner_resync", "restore", "wait_for_release"]
    assert result["restore_sequence"]["order"] == (
        "restore_planner_reset_reassert_release"
    )
    assert captured["safety_profile"] == "task"
    assert "require_all_support_pads" not in captured
    assert "min_z_m" not in captured


