def test_coordination_repair_hint_swaps_executable_front_back_calls():
    front_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.2, speed_mps=0.25, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    back_code = "def policy(api):\n    api.hold_position(hold_s=2)\n    api.stop_all()"
    policy = PolicyScript(
        script_id="failed_front_mover",
        attempt=3,
        code=front_code,
        robot_scripts=(
            RobotPolicyScript(
                robot_id="front",
                script_id="front_mover",
                code=front_code,
                synchronization_group="carry_team",
                coordination_mode="async",
            ),
            RobotPolicyScript(
                robot_id="back",
                script_id="back_support",
                code=back_code,
                synchronization_group="carry_team",
                coordination_mode="async",
            ),
        ),
    )

    hint = _coordination_repair_hint(policy)

    assert "robot=front must call api.hold_position" in hint
    assert "robot=back must call api.carry_forward" in hint
    assert "coordination_mode fields must be async" in hint


def test_coordination_repair_hint_converts_failed_sync_pair_to_async_roles():
    mover_code = (
        "def policy(api):\n"
        "    api.carry_lateral_left(distance_m=0.2, speed_mps=0.25, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    policy = PolicyScript(
        script_id="failed_sync_lateral",
        attempt=22,
        code=mover_code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_sync_lateral",
                code=mover_code,
                synchronization_group="carry_team",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )

    hint = _coordination_repair_hint(policy)

    assert "failed relation had both robots call api.carry_lateral_left" in hint
    assert "front=api.carry_lateral_left" in hint
    assert "back=api.carry_lateral_left" in hint
    assert "do not let both robots call the mover method" in hint


def test_coordination_repair_hint_requires_arc_radius_role_swap():
    def arc_code(radius_m: float) -> str:
        return (
            "def policy(api):\n"
            "    api.coordinated_arc_transport(turn_direction='clockwise', angle_deg=45, "
            f"duration_s=4.0, radius_m={radius_m})\n"
            "    api.stop_all()"
        )

    policy = PolicyScript(
        script_id="failed_arc_roles",
        attempt=16,
        code=(
            "def policy(api):\n"
            "    api.coordinated_arc_transport(turn_direction='clockwise', angle_deg=45, "
            "duration_s=4.0, radius_m=0.8)\n"
            "    api.stop_all()"
        ),
        robot_scripts=(
            RobotPolicyScript(
                robot_id="front",
                script_id="front_outer",
                code=arc_code(0.8),
                synchronization_group="corner_arc",
                coordination_mode="async",
            ),
            RobotPolicyScript(
                robot_id="back",
                script_id="back_inner",
                code=arc_code(0.2),
                synchronization_group="corner_arc",
                coordination_mode="async",
            ),
        ),
    )

    hint = _coordination_repair_hint(policy)

    assert "swap which robot receives the larger versus smaller radius_m" in hint
    assert "changing only the two radius magnitudes" in hint
    assert "front" not in hint
    assert "back" not in hint


def test_coordination_repair_hint_requires_exact_alignment_delta_swap():
    def alignment_code(delta: float) -> str:
        return (
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='lateral', "
            f"delta={delta}, duration_s=2.0)\n"
            "    api.stop_all()"
        )

    policy = PolicyScript(
        script_id="failed_alignment_roles",
        attempt=31,
        code=alignment_code(0.10),
        robot_scripts=(
            RobotPolicyScript(
                "front",
                "front_alignment",
                alignment_code(0.10),
                "team",
                coordination_mode="async",
            ),
            RobotPolicyScript(
                "back",
                "back_alignment",
                alignment_code(-0.10),
                "team",
                coordination_mode="async",
            ),
        ),
    )

    hint = _coordination_repair_hint(policy)

    assert "front must use delta=-0.1" in hint
    assert "back must use delta=0.1" in hint
    assert "preserve axis='lateral', duration_s=2.0" in hint
    assert "do not merely change delta magnitude" in hint


def test_arc_assignment_role_conflict_is_rejected_without_host_rewrite():
    def arc_script(robot_id: str, radius_m: float) -> RobotPolicyScript:
        return RobotPolicyScript(
            robot_id=robot_id,
            script_id=f"{robot_id}_arc",
            code=(
                "def policy(api):\n"
                "    api.coordinated_arc_transport(turn_direction='counterclockwise', "
                f"angle_deg=45, duration_s=4.0, radius_m={radius_m})\n"
                "    api.stop_all()"
            ),
            synchronization_group="corner_arc",
            coordination_mode="async",
        )

    assignments = (
        RobotAssignment(
            "front", "outer", "arc", "corner_arc", coordination_mode="async"
        ),
        RobotAssignment(
            "back", "inner", "arc", "corner_arc", coordination_mode="async"
        ),
    )

    with pytest.raises(ModelAgentError, match="Host will not rewrite robot roles"):
        _normalize_coordination_assignment_roles(
            assignments,
            (arc_script("front", 0.05), arc_script("back", 0.8)),
        )

    assert {item.robot_id: item.role for item in assignments} == {
        "front": "outer",
        "back": "inner",
    }


