def test_static_skill_catalog_enforces_adjustable_parameter_bounds():
    validate_catalog_parameters(
        "carry_forward",
        {"distance_m": 1.0, "speed_mps": 0.50, "ramp_s": 1.5},
    )
    with pytest.raises(ValueError, match="distance_m must be <= 1.0"):
        validate_catalog_parameters(
            "carry_forward", {"distance_m": 1.01, "speed_mps": 0.50, "ramp_s": 1.5}
        )
