def test_remote_text_client_reads_secret_only_from_environment(monkeypatch):
    class FakeResponse:
        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def read(self):
            return json.dumps(
                {
                    "choices": [{"message": {"content": '{"ok": true}'}}],
                    "usage": {"prompt_tokens": 12, "completion_tokens": 5},
                }
            ).encode("utf-8")

    captured = {}

    def fake_urlopen(http_request, *, timeout):
        captured["authorization"] = http_request.headers["Authorization"]
        captured["timeout"] = timeout
        return FakeResponse()

    monkeypatch.setenv("TEST_REMOTE_KEY", "unit-test-secret")
    monkeypatch.setattr(openai_compatible_module.request, "urlopen", fake_urlopen)
    client = OpenAICompatibleTextClient(
        base_url="https://example.invalid/v1",
        model_name="test-model",
        api_key_env="TEST_REMOTE_KEY",
        timeout_s=4.0,
    )

    response = client.generate(system="system", user="user")

    assert response == '{"ok": true}'
    assert captured == {"authorization": "Bearer unit-test-secret", "timeout": 4.0}
    assert "unit-test-secret" not in json.dumps(client.call_records)
    assert client.usage_summary()["input_tokens"] == 12


def test_remote_client_encodes_image_without_persisting_image_bytes(
    monkeypatch,
    tmp_path,
):
    class FakeResponse:
        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def read(self):
            return json.dumps(
                {
                    "choices": [{"message": {"content": '{"ok": true}'}}],
                    "usage": {"prompt_tokens": 20, "completion_tokens": 5},
                }
            ).encode("utf-8")

    captured = {}

    def fake_urlopen(http_request, *, timeout):
        captured["body"] = json.loads(http_request.data.decode("utf-8"))
        captured["timeout"] = timeout
        return FakeResponse()

    frame = tmp_path / "global.png"
    frame.write_bytes(b"fake-png")
    monkeypatch.setenv("TEST_REMOTE_KEY", "unit-test-secret")
    monkeypatch.setattr(openai_compatible_module.request, "urlopen", fake_urlopen)
    client = OpenAICompatibleTextClient(
        base_url="https://example.invalid/v1",
        model_name="vision-model",
        api_key_env="TEST_REMOTE_KEY",
        timeout_s=4.0,
        seed=4,
    )

    response = client.analyze_image(
        system="system",
        user="inspect",
        image_path=frame,
    )

    assert response == '{"ok": true}'
    user_content = captured["body"]["messages"][1]["content"]
    assert captured["body"]["response_format"] == {"type": "json_object"}
    assert captured["body"]["seed"] == 4
    assert user_content[0] == {"type": "text", "text": "inspect"}
    assert user_content[1]["type"] == "image_url"
    assert user_content[1]["image_url"]["url"].startswith("data:image/png;base64,")
    assert client.call_records[-1]["kind"] == "remote_vision_generation"
    assert client.call_records[-1]["image_path"] == str(frame)
    assert client.call_records[-1]["requested_seed"] == 4
    assert "data:image/png;base64" not in json.dumps(client.call_records)


def test_remote_client_records_openai_compatible_request_billing(monkeypatch):
    class FakeResponse:
        def __init__(self, payload, *, headers=None):
            self.payload = payload
            self.headers = headers or {}
            self.status = 200

        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    calls = []

    def fake_urlopen(http_request, *, timeout):
        calls.append((http_request.full_url, timeout))
        if http_request.full_url.endswith("/chat/completions"):
            return FakeResponse(
                {
                    "model": "resolved-test-model",
                    "choices": [{"message": {"content": '{"ok": true}'}}],
                    "usage": {
                        "prompt_tokens": 20,
                        "completion_tokens": 5,
                        "total_tokens": 25,
                        "prompt_tokens_details": {
                            "cached_tokens": 3,
                            "image_tokens": 7,
                        },
                        "completion_tokens_details": {
                            "reasoning_tokens": 2,
                        },
                    },
                },
                headers={
                    "X-Provider-Request-Id": "req_test",
                    "X-Provider-Channel-Id": "47",
                },
            )
        assert http_request.full_url.endswith("/api/usage/requests/req_test")
        return FakeResponse(
            {
                "billing": {
                    "currency": "USD",
                    "amount_microusd": 123,
                    "pricing_version": 1,
                    "line_items": [],
                },
                "routing": {
                    "resolved_model": "resolved-test-model",
                },
                "provider_usage": {"family": "gemini"},
            }
        )

    monkeypatch.setenv("TEST_REMOTE_KEY", "unit-test-secret")
    monkeypatch.setattr(openai_compatible_module.request, "urlopen", fake_urlopen)
    client = OpenAICompatibleTextClient(
        model_name="requested-test-model",
        base_url="https://provider.example.invalid/v1",
        usage_path_template="/api/usage/requests/{request_id}",
        api_key_env="TEST_REMOTE_KEY",
        timeout_s=4.0,
    )

    assert client.generate(system="system", user="user") == '{"ok": true}'

    record = client.call_records[-1]
    assert len(calls) == 2
    assert record["request_id"] == "req_test"
    assert record["resolved_model"] == "resolved-test-model"
    assert record["cached_input_tokens"] == 3
    assert record["image_input_tokens"] == 7
    assert record["reasoning_tokens"] == 2
    assert record["billing_amount_microusd"] == 123
    assert record["billing_amount_usd"] == pytest.approx(0.000123)
    assert record["provider_family"] == "gemini"
    assert client.usage_summary()["billing_amount_microusd"] == 123
    assert "unit-test-secret" not in json.dumps(record)


def test_remote_client_reconciles_deferred_openai_compatible_billing(monkeypatch):
    class FakeResponse:
        status = 200

        def __init__(self, payload, *, headers=None):
            self.payload = payload
            self.headers = headers or {}

        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def read(self):
            return json.dumps(self.payload).encode("utf-8")

    usage_calls = 0

    def fake_urlopen(http_request, *, timeout):
        nonlocal usage_calls
        if http_request.full_url.endswith("/chat/completions"):
            return FakeResponse(
                {
                    "model": "resolved-test-model",
                    "choices": [{"message": {"content": '{"ok": true}'}}],
                    "usage": {
                        "prompt_tokens": 20,
                        "completion_tokens": 5,
                        "total_tokens": 25,
                    },
                },
                headers={"X-Provider-Request-Id": "req_deferred"},
            )
        usage_calls += 1
        if usage_calls == 1:
            raise openai_compatible_module.error.HTTPError(
                http_request.full_url,
                429,
                "rate limited",
                {},
                None,
            )
        return FakeResponse(
            {
                "billing": {
                    "currency": "USD",
                    "amount_microusd": 456,
                    "pricing_version": 1,
                    "line_items": [],
                },
                "routing": {"resolved_model": "resolved-test-model"},
                "provider_usage": {"family": "openai"},
            }
        )

    monkeypatch.setenv("TEST_REMOTE_KEY", "unit-test-secret")
    monkeypatch.setattr(openai_compatible_module.request, "urlopen", fake_urlopen)
    monkeypatch.setattr(openai_compatible_module.time, "sleep", lambda _seconds: None)
    client = OpenAICompatibleTextClient(
        model_name="requested-test-model",
        base_url="https://provider.example.invalid/v1",
        usage_path_template="/api/usage/requests/{request_id}",
        api_key_env="TEST_REMOTE_KEY",
        timeout_s=4.0,
    )

    assert client.generate(system="system", user="user") == '{"ok": true}'
    assert client.call_records[-1]["billing_amount_microusd"] is None
    report = client.reconcile_billing(
        max_rounds=2,
        initial_backoff_s=0.0,
        per_request_delay_s=0.0,
    )

    assert report["status"] == "complete"
    assert report["resolved"] == 1
    assert report["remaining"] == 0
    assert client.call_records[-1]["billing_amount_microusd"] == 456
    assert client.usage_summary()["unbilled_call_count"] == 0


