def test_remote_text_client_retries_transient_upstream_overload(monkeypatch):
    class FakeResponse:
        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def read(self):
            return json.dumps(
                {"choices": [{"message": {"content": '{"ok": true}'}}]}
            ).encode("utf-8")

    calls = []
    sleeps = []

    def fake_urlopen(http_request, *, timeout):
        calls.append((http_request.full_url, timeout))
        if len(calls) < 3:
            raise openai_compatible_module.error.HTTPError(
                http_request.full_url,
                503,
                "upstream overloaded",
                {},
                BytesIO(b'{"error":{"code":"upstream_overloaded"}}'),
            )
        return FakeResponse()

    monkeypatch.setenv("TEST_REMOTE_KEY", "unit-test-secret")
    monkeypatch.setattr(openai_compatible_module.request, "urlopen", fake_urlopen)
    monkeypatch.setattr(openai_compatible_module.time, "sleep", sleeps.append)
    client = OpenAICompatibleTextClient(
        base_url="https://example.invalid/v1",
        model_name="test-model",
        api_key_env="TEST_REMOTE_KEY",
        timeout_s=4.0,
    )

    assert client.generate(system="system", user="user") == '{"ok": true}'
    assert len(calls) == 3
    assert sleeps == [1.0, 2.0]
    assert client.call_records[-1]["network_retries"] == 2
    assert len(client.call_records[-1]["transport_failures"]) == 2


