def test_remote_client_keeps_term4_alive_across_exhausted_502_rounds(monkeypatch):
    class FakeResponse:
        headers = {}
        status = 200

        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def read(self):
            return json.dumps(
                {"choices": [{"message": {"content": '{"ok": true}'}}]}
            ).encode("utf-8")

    calls = 0
    sleeps = []

    def fake_urlopen(http_request, *, timeout):
        nonlocal calls
        calls += 1
        if calls <= 2:
            raise openai_compatible_module.error.HTTPError(
                http_request.full_url,
                502,
                "provider unavailable",
                {},
                BytesIO(b'{"error":{"code":502}}'),
            )
        return FakeResponse()

