def test_clearance_margin_allows_motion_away_from_physical_wall():
    wall = {
        "center_xy": (0.0, 0.0),
        "size_xy": (1.0, 4.0),
        "yaw_rad": 0.0,
        "inflation_m": 0.2,
    }

    away = _ray_oriented_box_distance(
        (0.65, 0.0),
        (1.0, 0.0),
        **wall,
    )
    toward = _ray_oriented_box_distance(
        (0.65, 0.0),
        (-1.0, 0.0),
        **wall,
    )

    assert away is None
    assert toward == pytest.approx(0.15)


