def test_host_wall_clearance_emits_small_correction_before_repeat_translation():
    runtime_state = {
        "payload": {
            "x": 1.426,
            "y": 4.830,
            "supporting_robots": ["front", "back"],
        },
        "robots": {
            "front": {
                "x": 1.361,
                "y": 5.597,
                "yaw_deg": -170.3,
            },
            "back": {
                "x": 1.683,
                "y": 4.299,
                "yaw_deg": -171.2,
            },
        },
    }
    correction = unique_small_heading_correction(
        authored_scene_motion_clearance(runtime_state)
    )

    assert correction == {
        "desired_translation_direction": "right",
        "turn_direction": "clockwise",
        "angle_deg": 5.0,
        "resulting_translation_clearance_m": 2.996,
        "resulting_translation_relation": "open",
        "inner_robot": "front",
        "outer_robot": "back",
        "basis": (
            "smallest sampled shared-yaw correction that makes the blocked "
            "body-frame translation locally wall-clear"
        ),
    }

    selected = _select_evolution_subtask(
        client=FakeModelClient([]),
        payload={
            "route_discovery": True,
            "current_policy": {
                "code": (
                    "def policy(api):\n"
                    "    api.coordinated_alignment(axis='longitudinal', "
                    "delta=0.1, duration_s=1.0)\n"
                    "    api.stop_all()"
                )
            },
            "evaluation": {
                "success": False,
                "failure_type": "no_payload_progress",
            },
            "observation": {"runtime_state": runtime_state},
            "coordination_primitive_sdk": "enabled",
        },
        forbidden_methods=(),
    )

    assert selected["selection_source"] == "host_wall_heading_correction"
    assert selected["motion_objective"] == "clockwise"
    assert selected["angle_deg"] == 5.0
    parameters = _select_coordination_parameters(
        client=FakeModelClient([]),
        selected_subtask=selected,
        payload={"observation": {"runtime_state": runtime_state}},
    )
    assert {
        robot_id: {
            "role": values["role"],
            "angle_deg": values["angle_deg"],
        }
        for robot_id, values in parameters["robot_parameters"].items()
    } == {
        "front": {"role": "inner", "angle_deg": 5.0},
        "back": {"role": "outer", "angle_deg": 5.0},
    }


