class FakeModelClient:
    def __init__(self, responses):
        self.responses = list(responses)
        self.prompts = []

    def generate(self, *, system: str, user: str) -> str:
        self.prompts.append({"system": system, "user": user})
        return self.responses.pop(0)


class FakeVisionClient:
    def __init__(self, response):
        self.response = response
        self.calls = []

    def analyze_image(self, *, system: str, user: str, image_path: str | Path) -> str:
        self.calls.append(
            {"system": system, "user": user, "image_path": str(image_path)}
        )
        return self.response


def _explicit_team_fields(code: str) -> dict:
    sync_group = "carry_team"
    return {
        "assignments": [
            {
                "robot_id": "front",
                "role": "formation_lead",
                "objective": "maintain the front support and command timing",
                "synchronization_group": sync_group,
                "safety_constraints": ["maintain payload contact"],
            },
            {
                "robot_id": "back",
                "role": "payload_guard",
                "objective": "match the lead motion and preserve rear support",
                "synchronization_group": sync_group,
                "safety_constraints": ["maintain payload contact"],
            },
        ],
        "robot_scripts": [
            {
                "robot_id": robot_id,
                "script_id": f"{robot_id}_policy",
                "synchronization_group": sync_group,
                "code": code,
            }
            for robot_id in ("front", "back")
        ],
    }


def _supported_observation() -> ObservationBundle:
    return ObservationBundle(
        runtime_state={
            "runtime_status": "running",
            "control_health": {"healthy": True},
            "elastic_band_dropped": True,
            "payload": {
                "present": True,
                "active": True,
                "contacts": {"support_robots": ["front", "back"]},
            },
        }
    )


def _controller_policy(
    attempt: int,
    *,
    method: str = "carry_forward",
    distance_m: float = 0.05,
    coordination_mode: str = "sync",
) -> PolicyScript:
    code = (
        "def policy(api):\n"
        f"    api.{method}(distance_m={distance_m}, speed_mps=0.20, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    return PolicyScript(
        script_id=f"box_carry_attempt_{attempt:02d}",
        attempt=attempt,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_{attempt:02d}",
                code=code,
                synchronization_group="carry_team",
                phase_id="bounded_transport",
                contact_intent="maintain_payload_support",
                coordination_mode=coordination_mode,
            )
            for robot_id in ("front", "back")
        ),
    )


def test_model_orchestrator_generates_safe_policy_from_json():
    code = (
        "def policy(api):\n"
        "    api.carry_lateral_left(distance_m=0.4, speed_mps=0.20)\n"
        "    api.stop_all()\n"
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_01",
                    "rationale": "Use payload placement followed by one lateral segment.",
                    "plan": ["place payload", "move left", "stop"],
                    "code": code,
                    **_explicit_team_fields(code),
                    "spec_candidate": "",
                }
            )
        ]
    )

    policy = ModelTaskOrchestrator(client=client).generate_initial_policy(
        BoxCarryTask(task_id="stage1", target="carry box"),
        ObservationBundle(
            runtime_state=_supported_observation().runtime_state,
            retrieved_specs=("keep synchronized lateral motion",),
        ),
    )

    assert policy.script_id == "box_carry_attempt_01"
    assert "api.carry_lateral_left" in policy.code
    assert {item.robot_id for item in policy.assignments} == {"front", "back"}
    assert {item.robot_id for item in policy.robot_scripts} == {"front", "back"}
    assert "keep synchronized lateral motion" in client.prompts[0]["user"]
    assert "FAST ACTION-MAGNITUDE PROTOCOL" in client.prompts[0]["user"]
    assert (
        "Optimize for the fewest verifier-accepted scripts" in client.prompts[0]["user"]
    )
    assert "Coordination is a per-phase decision" in client.prompts[0]["system"]


