def test_model_generation_gate_rejects_sync_scripts_with_different_atomic_skills():
    forward = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.05, speed_mps=0.20, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    hold = "def policy(api):\n    api.hold_position(hold_s=2.0)\n    api.stop_all()\n"
    scripts = (
        RobotPolicyScript(
            robot_id="front",
            script_id="front_move",
            code=forward,
            synchronization_group="carry_team",
            phase_id="corridor",
            contact_intent="maintain_payload_support",
            coordination_mode="sync",
        ),
        RobotPolicyScript(
            robot_id="back",
            script_id="back_hold",
            code=hold,
            synchronization_group="carry_team",
            phase_id="corridor",
            contact_intent="maintain_payload_support",
            coordination_mode="sync",
        ),
    )

    with pytest.raises(ValueError, match="requires the same atomic skill"):
        validate_team_policy_scripts(scripts)


