def test_route_regression_without_evolution_record_stays_at_dispatch_checkpoint(
    tmp_path,
):
    history_dir = tmp_path / "history"
    history_dir.mkdir()

    def write_rejected_attempt(
        attempt: int,
        *,
        checkpoint_id: str,
        direction: str,
    ) -> None:
        attempt_dir = history_dir / f"attempt_{attempt:02d}"
        attempt_dir.mkdir()
        code = (
            "def policy(api):\n"
            "    api.coordinated_linear_transport("
            f"direction='{direction}', distance_m=0.5, "
            "speed_mps=0.5, ramp_s=1.5)\n"
            "    api.stop_all()\n"
        )
        (attempt_dir / "policy.json").write_text(
            json.dumps(
                {
                    "script_id": f"rejected_{direction}_{attempt}",
                    "attempt": attempt,
                    "code": code,
                    "robot_scripts": [
                        {
                            "robot_id": robot_id,
                            "script_id": f"{robot_id}_{direction}_{attempt}",
                            "code": code,
                            "synchronization_group": "carry_team",
                            "coordination_mode": "sync",
                        }
                        for robot_id in ("front", "back")
                    ],
                }
            ),
            encoding="utf-8",
        )
        (attempt_dir / "evaluation.json").write_text(
            json.dumps(
                {
                    "success": False,
                    "failure_type": "route_regression",
                    "metrics": {"payload_target_progress_m": -0.25},
                    "evidence": {
                        "checkpoint_outcome": {
                            "checkpoint_before": checkpoint_id,
                            "checkpoint_after": checkpoint_id,
                            "physically_dispatched": True,
                        }
                    },
                }
            ),
            encoding="utf-8",
        )
        (attempt_dir / "execution_trace.json").write_text(
            json.dumps({"skill_calls": [{"status": "ok"}]}),
            encoding="utf-8",
        )

    write_rejected_attempt(
        58,
        checkpoint_id="accepted_step_43",
        direction="left",
    )
    write_rejected_attempt(
        59,
        checkpoint_id="accepted_step_44",
        direction="right",
    )
    output_dir = tmp_path / "resume"
    output_dir.mkdir()
    agent = ModelCollaborativeEvolutionAgent(
        output_dir=output_dir,
        client=FakeModelClient([]),
        history_dirs=(history_dir,),
        route_discovery=True,
        coordination_layer_enabled=True,
    )

    agent._refresh_rejected_transactions(checkpoint_id="accepted_step_44")

    assert agent.nonrelaxable_motion_objectives == (
        "coordinated_linear_transport:right",
    )
    assert agent._directionally_rejected_objectives == {
        "coordinated_linear_transport:right"
    }

    agent._refresh_rejected_transactions(checkpoint_id="accepted_step_45")

    assert agent.nonrelaxable_motion_objectives == ()
    assert agent._directionally_rejected_objectives == set()


