def test_model_prompt_requires_phase_coordination_without_leaking_scene_solution():
    code = "def policy(api):\n    api.hold_position(hold_s=2.0)\n    api.stop_all()\n"
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_01",
                    "rationale": "Observe before selecting the next bounded move.",
                    "plan": ["inspect current geometry"],
                    "code": code,
                    **_explicit_team_fields(code),
                }
            )
        ]
    )

    ModelTaskOrchestrator(client=client).generate_initial_policy(
        BoxCarryTask(task_id="stage3", target="reach the active target"),
        _supported_observation(),
    )

    combined_prompt = client.prompts[0]["system"] + client.prompts[0]["user"]
    assert client.prompts[0]["system"] == MODEL_AGENT_SYSTEM_PROMPT
    assert "Coordination is a per-phase decision" in combined_prompt
    assert "route contract gives connected free-space segments" in combined_prompt
    assert "never gives a primitive, body-frame direction" in combined_prompt
    assert "guard does not require a pivot" in TASK_ORCHESTRATOR_SYSTEM_PROMPT
    assert '"x_width": 6.54' in combined_prompt
    assert '"y_length": 8.03' in combined_prompt
    assert "0.25, 0.5, 0.75, or 1.0m" in combined_prompt
    assert "never multiple task-changing calls" in combined_prompt
    assert "wall_05" not in combined_prompt
    assert "corridor-entry" not in combined_prompt
    assert "Do not turn the long box inside" not in combined_prompt
    lowered_prompt = combined_prompt.lower()
    assert "one-behind" not in lowered_prompt
    assert "single-file" not in lowered_prompt
    assert "tandem formation" not in lowered_prompt


def test_strategy_memory_promotes_verifier_coordination_without_action_parameters(
    tmp_path,
):
    path = tmp_path / "active_strategy.json"
    store = StrategyMemoryStore(path)
    record = {
        "kind": "physical_rollout_finalized",
        "dry_run": False,
        "physically_dispatched": True,
        "physical_transaction_completed": True,
        "text": "untrusted model claim with distance_m=0.40 and speed_mps=0.25",
        "coordination_mode": "sync",
        "policy_execution_parameters": [
            {
                "robot_id": "front",
                "skill": "carry_lateral_left",
                "parameters": {"distance_m": 0.40, "speed_mps": 0.25, "ramp_s": 1.5},
            }
        ],
        "strategy_context": {"phase": "corridor_transport"},
        "verifier": {
            "step_accepted": False,
            "failure_type": "formation_desync",
            "checkpoint_before": "accepted_step_37",
            "checkpoint_after": "",
        },
    }

    assert store.update_from_rollout(record)
    assert not store.update_from_rollout(record)
    store.save()
    serialized = path.read_text(encoding="utf-8")
    retrieved = "\n".join(
        store.retrieve(
            StrategyContext(
                phase="corridor_transport",
                last_failure_type="formation_desync",
            )
        )
    )

    assert "formation_desync" in retrieved
    assert "observed_mode=sync" in retrieved
    assert "failure_level=script" in retrieved
    assert "materially different bounded transaction" in retrieved
    learned = next(
        item
        for item in store.specs
        if item["id"]
        == "counterexample_corridor_transport_sync_script_formation_desync"
    )
    assert learned["evidence"]["rejected_count"] == 1
    assert "untrusted model claim" not in serialized
    for forbidden in ("distance_m", "speed_mps", "ramp_s", "yaw_deg"):
        assert forbidden not in serialized
        assert forbidden not in retrieved


