def test_failure_taxonomy_limits_repairs_to_one_reasoning_level():
    assert classify_failure("payload_wall_contact").level == "strategy"
    assert classify_failure("formation_desync").level == "script"
    execution = classify_failure(
        "no_payload_progress",
        metrics={
            "payload_step_displacement_xy_m": 0.002,
            "required_step_displacement_m": 0.01,
        },
    )
    assert execution.level == "execution"
    ceiling_blocked = classify_failure(
        "no_payload_progress",
        metrics={
            "payload_step_displacement_xy_m": 0.002,
            "required_step_displacement_m": 0.01,
        },
        evidence={
            "linear_no_progress_at_verified_ceiling": {
                "requested_distance_m": 2.0,
            }
        },
    )
    assert ceiling_blocked.level == "strategy"
    assert "magnitude_only_retry" in ceiling_blocked.forbidden_repairs
    alignment = classify_failure(
        "no_payload_progress",
        metrics={
            "payload_step_displacement_xy_m": 0.002,
            "required_step_displacement_m": 0.01,
        },
        failed_subtask="coordinated_alignment",
    )
    assert alignment.level == "script"
    assert "change_alignment_delta_only" in alignment.forbidden_repairs
    strategy = classify_failure(
        "no_payload_progress",
        metrics={
            "payload_step_displacement_xy_m": 0.04,
            "required_step_displacement_m": 0.01,
        },
    )
    assert strategy.level == "strategy"
    assert classify_failure("script_error").promotable is False


