def test_generation_error_records_current_physical_attempt_without_prior_decision(
    tmp_path,
):
    controller = EvolutionController(
        max_physical_iterations=5,
        strategy_failure_budget=0,
        output_dir=tmp_path,
    )
    policy = _controller_policy(
        1,
        method="coordinated_linear_transport",
        coordination_mode="sync",
    )
    report = EvaluationReport(
        success=True,
        failure_type="none",
        evidence={
            "transition_decision": {
                "outcome": "ACCEPT_PROGRESS",
                "trusted_checkpoint_allowed": True,
                "positive_route_memory_allowed": True,
            }
        },
    )

    payload = _controller_decision_for_generation_error(
        completed_decision=None,
        policy=policy,
        report=report,
        trace=ExecutionTrace(
            script_id=policy.script_id,
            attempt=policy.attempt,
            status="success",
        ),
        checkpoint_id="accepted_step_00",
        physically_dispatched=True,
        error=ModelAgentError("Evolution Manager response was invalid"),
        evolution_controller=controller,
    )

    assert controller.physical_iterations == 1
    assert payload["physical_iterations"] == 1
    assert payload["generation_interrupted"] is True
    assert payload["next_policy_generated"] is False
    assert payload["generation_error_type"] == "ModelAgentError"


