def test_failure_level_code_gate_rejects_wrong_repair_layer():
    previous_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.05, speed_mps=0.20, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    tuned_code = previous_code.replace("distance_m=0.05", "distance_m=0.08")
    previous = PolicyScript(
        script_id="previous",
        attempt=1,
        code=previous_code,
        robot_scripts=(
            RobotPolicyScript("front", "front_previous", previous_code, "team"),
            RobotPolicyScript("back", "back_previous", previous_code, "team"),
        ),
    )
    tuned = PolicyScript(
        script_id="tuned",
        attempt=2,
        code=tuned_code,
        robot_scripts=(
            RobotPolicyScript("front", "front_tuned", tuned_code, "team"),
            RobotPolicyScript("back", "back_tuned", tuned_code, "team"),
        ),
    )

    with pytest.raises(ModelAgentError, match="strategy-level failure"):
        _validate_failure_level_repair(
            previous,
            tuned,
            failure_level="strategy",
            failure_type="goal_regression",
            blocked_strategy_signatures=set(),
        )
    with pytest.raises(ModelAgentError, match="coordination-level failure"):
        _validate_failure_level_repair(
            previous,
            tuned,
            failure_level="coordination",
            failure_type="formation_desync",
            blocked_strategy_signatures=set(),
        )
    _validate_failure_level_repair(
        previous,
        tuned,
        failure_level="execution",
        failure_type="no_payload_progress",
        blocked_strategy_signatures=set(),
    )


def test_strategy_repair_rejects_legacy_to_equivalent_coordinated_linear_rename():
    previous_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=2.0, speed_mps=0.50, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    same_objective_code = (
        "def policy(api):\n"
        '    api.coordinated_linear_transport(direction="forward", distance_m=2.0, '
        "speed_mps=0.50, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    changed_objective_code = same_objective_code.replace(
        'direction="forward"',
        'direction="left"',
    )

    def team_policy(script_id: str, attempt: int, code: str) -> PolicyScript:
        return PolicyScript(
            script_id=script_id,
            attempt=attempt,
            code=code,
            robot_scripts=tuple(
                RobotPolicyScript(
                    robot_id=robot_id,
                    script_id=f"{robot_id}_{script_id}",
                    code=code,
                    synchronization_group="carry_team",
                    coordination_mode="sync",
                )
                for robot_id in ("front", "back")
            ),
        )

    previous = team_policy("legacy_forward", 1, previous_code)
    same_objective = team_policy("renamed_forward", 2, same_objective_code)
    changed_objective = team_policy("linear_left", 2, changed_objective_code)

    with pytest.raises(
        ModelAgentError, match="renaming the same body-frame linear objective"
    ):
        _validate_failure_level_repair(
            previous,
            same_objective,
            failure_level="strategy",
            failure_type="goal_regression",
            blocked_strategy_signatures=set(),
        )

    with pytest.raises(
        ModelAgentError, match="renaming the same body-frame linear objective"
    ):
        _validate_failure_level_repair(
            previous,
            same_objective,
            failure_level="strategy",
            failure_type="goal_regression",
            blocked_strategy_signatures={"sync:carry_forward"},
        )

    _validate_failure_level_repair(
        previous,
        changed_objective,
        failure_level="strategy",
        failure_type="goal_regression",
        blocked_strategy_signatures=set(),
    )


def test_alignment_no_progress_repair_must_increase_delta_only():
    def alignment_policy(
        script_id: str,
        attempt: int,
        delta: float,
        *,
        duration_s: float = 2.0,
    ) -> PolicyScript:
        codes = {
            "front": (
                "def policy(api):\n"
                "    api.coordinated_alignment(axis='lateral', "
                f"delta={delta:g}, duration_s={duration_s:g})\n"
                "    api.stop_all()"
            ),
            "back": (
                "def policy(api):\n"
                "    api.coordinated_alignment(axis='lateral', "
                f"delta={-delta:g}, duration_s={duration_s:g})\n"
                "    api.stop_all()"
            ),
        }
        return PolicyScript(
            script_id=script_id,
            attempt=attempt,
            code=codes["front"],
            robot_scripts=tuple(
                RobotPolicyScript(
                    robot_id=robot_id,
                    script_id=f"{robot_id}_{script_id}",
                    code=codes[robot_id],
                    synchronization_group="alignment_team",
                    coordination_mode="async",
                )
                for robot_id in ("front", "back")
            ),
        )

    previous = alignment_policy("alignment_small", 1, 0.05)

    with pytest.raises(ModelAgentError, match=r"abs\(delta\) did not increase"):
        _validate_failure_level_repair(
            previous,
            alignment_policy("alignment_same", 2, 0.05),
            failure_level="execution",
            failure_type="no_payload_progress",
            blocked_strategy_signatures=set(),
        )

    with pytest.raises(ModelAgentError, match="changed fixed duration_s"):
        _validate_failure_level_repair(
            previous,
            alignment_policy("alignment_changed_duration", 2, 0.10, duration_s=3.0),
            failure_level="execution",
            failure_type="no_payload_progress",
            blocked_strategy_signatures=set(),
        )

    _validate_failure_level_repair(
        previous,
        alignment_policy("alignment_larger", 2, 0.10),
        failure_level="execution",
        failure_type="no_payload_progress",
        blocked_strategy_signatures=set(),
    )


def test_evolution_controller_selects_repair_layer_from_verifier(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )
    policy = _controller_policy(1)

    strategy = controller.record_and_decide(
        policy=policy,
        report=EvaluationReport(success=False, failure_type="goal_regression"),
        trace=None,
        checkpoint_id="accepted_step_00",
        physically_dispatched=True,
    )
    coordination = controller.record_and_decide(
        policy=_controller_policy(2, method="carry_lateral_left"),
        report=EvaluationReport(success=False, failure_type="formation_desync"),
        trace=None,
        checkpoint_id="accepted_step_00",
        physically_dispatched=True,
    )
    execution = controller.record_and_decide(
        policy=_controller_policy(3, method="carry_backward"),
        report=EvaluationReport(
            success=False,
            failure_type="no_payload_progress",
            metrics={
                "required_step_displacement_m": 0.05,
                "payload_step_displacement_xy_m": 0.0,
            },
        ),
        trace=None,
        checkpoint_id="accepted_step_00",
        physically_dispatched=True,
    )

    assert strategy.action == "switch_strategy"
    assert coordination.action == "rewrite_script"
    assert coordination.repair_level == "script"
    assert execution.action == "tune_parameter"
    assert execution.physical_iterations == 3
