def test_evolution_controller_retires_child_failure_budget_on_explicit_rewind(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=4,
        output_dir=tmp_path,
    )
    controller.record_and_decide(
        policy=_controller_policy(1, method="carry_lateral_left"),
        report=EvaluationReport(
            success=True,
            failure_type="none",
            evidence={
                "transition_decision": {
                    "outcome": "ACCEPT_PROGRESS",
                    "trusted_checkpoint_allowed": True,
                    "positive_route_memory_allowed": True,
                }
            },
        ),
        trace=None,
        checkpoint_id="accepted_step_21",
        physically_dispatched=True,
    )
    for attempt in range(2, 6):
        controller.record_and_decide(
            policy=_controller_policy(attempt, method="carry_lateral_left"),
            report=EvaluationReport(success=False, failure_type="payload_drop"),
            trace=None,
            checkpoint_id="accepted_step_22",
            physically_dispatched=True,
        )

    retired = controller.rewind_strategy_evidence_to_checkpoint("accepted_step_21")

    decision = controller.record_and_decide(
        policy=_controller_policy(6, method="carry_lateral_left"),
        report=EvaluationReport(success=False, failure_type="payload_slip"),
        trace=None,
        checkpoint_id="accepted_step_21",
        physically_dispatched=True,
    )

    assert retired == 4
    assert controller.physical_iterations == 6
    assert decision.strategy_failure_count == 1
    assert decision.action == "rewrite_script"
    assert controller.strategy_failure_counts == {"sync:carry_lateral_left": 1}


