def test_evolution_controller_escalates_exhausted_generation_candidates(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )
    decision = controller.record_and_decide(
        policy=_controller_policy(1, method="carry_lateral_left"),
        report=EvaluationReport(success=False, failure_type="formation_desync"),
        trace=None,
        checkpoint_id="accepted_step_08",
        physically_dispatched=True,
    )

    escalated = controller.escalate_candidate_space_exhausted(
        decision,
        error="all bounded role candidates were compiler-rejected",
    )

    assert decision.repair_level == "script"
    assert escalated.action == "switch_strategy"
    assert escalated.repair_level == "strategy"
    assert escalated.physical_iterations == 1
    assert controller.physical_iterations == 1
    reselected = controller.escalate_candidate_space_exhausted(
        escalated,
        error="the first strategy candidate repeated a blocked transaction",
    )
    assert reselected.action == "switch_strategy"
    assert reselected.repair_level == "strategy"
    assert reselected.physical_iterations == 1
    history = json.loads(
        (tmp_path / "evolution_controller_history.json").read_text(encoding="utf-8")
    )
    assert history["attempts"][-1]["controller_action"] == "switch_strategy"


