def test_controller_marks_payload_dropping_pivot_as_script_defect(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )

    def pivot_policy(attempt: int, front_role: str, angle_deg: float) -> PolicyScript:
        back_role = "outer" if front_role == "inner" else "inner"

        def code(role: str) -> str:
            return (
                "def policy(api):\n"
                f"    api.coordinated_pivot(turn_direction='clockwise', angle_deg={angle_deg}, "
                f"duration_s=4.0, role='{role}', swing_radius_m=0.8)\n"
                "    api.stop_all()\n"
            )

        return PolicyScript(
            script_id=f"pivot_{attempt}",
            attempt=attempt,
            code=code(front_role),
            robot_scripts=(
                RobotPolicyScript(
                    "front",
                    f"front_pivot_{attempt}",
                    code(front_role),
                    "pivot_team",
                    coordination_mode="async",
                ),
                RobotPolicyScript(
                    "back",
                    f"back_pivot_{attempt}",
                    code(back_role),
                    "pivot_team",
                    coordination_mode="async",
                ),
            ),
        )

    first = controller.record_and_decide(
        policy=pivot_policy(1, "inner", 30.0),
        report=EvaluationReport(success=False, failure_type="payload_drop"),
        trace=None,
        checkpoint_id="accepted_step_09",
        physically_dispatched=True,
    )
    second = controller.record_and_decide(
        policy=pivot_policy(2, "inner", 15.0),
        report=EvaluationReport(success=False, failure_type="payload_drop"),
        trace=None,
        checkpoint_id="accepted_step_09",
        physically_dispatched=True,
    )

    assert first.action == "rewrite_script"
    assert first.repair_level == "script"
    assert second.action == "change_coordination"
    assert second.repair_level == "coordination"
    assert "materially different executable AST" in first.required_change


