def test_structured_coordination_parameter_stage_compiles_stationary_inner_pivot():
    selected_subtask = {
        "selected_method": "coordinated_pivot",
        "coordination_mode": "async",
        "motion_objective_parameter": "turn_direction",
        "motion_objective": "counterclockwise",
        "reason": "hold the inner robot while the outer robot follows a forward arc",
    }

    client = FakeModelClient(
        [
            json.dumps(
                {
                    "travel_direction": "forward",
                    "angle_deg": 2.0,
                    "duration_s": 8.0,
                    "inner_robot": "back",
                    "swing_radius_m": 0.8,
                    "reason": "tiny route turn",
                }
            ),
            json.dumps(
                {
                    "travel_direction": "forward",
                    "angle_deg": 30.0,
                    "duration_s": 4.0,
                    "inner_robot": "back",
                    "swing_radius_m": 0.8,
                    "reason": "use an uncalibrated pivot window",
                }
            ),
            json.dumps(
                {
                    "travel_direction": "forward",
                    "angle_deg": 30.0,
                    "duration_s": 8.0,
                    "inner_robot": "back",
                    "swing_radius_m": 0.8,
                    "reason": "use one slow stationary-inner pivot segment",
                }
            ),
        ]
    )
    selected = _select_coordination_parameters(
        client=client,
        selected_subtask=selected_subtask,
        payload={
            "observation": {"runtime_state": _supported_observation().runtime_state},
            "evaluation": {"success": False, "failure_type": "goal_regression"},
        },
    )
    assert len(client.prompts) == 3
    assert (
        "one shared angle from 10, 15, 20, 30 degrees"
        in client.prompts[1]["user"]
    )
    assert "both remain the calibrated 8s" in client.prompts[2]["user"]
    current_code = (
        "def policy(api):\n"
        "    api.coordinated_arc_transport(turn_direction='clockwise', angle_deg=5.0, "
        "duration_s=6.0, radius_m=0.4)\n"
        "    api.stop_all()"
    )
    _payload, policy = _compile_model_selected_coordination_policy(
        current_policy=PolicyScript(
            script_id="failed_arc",
            attempt=1,
            code=current_code,
        ),
        attempt=2,
        selected_subtask=selected_subtask,
        selected_parameters=selected,
        failure_level="strategy",
        failure_type="goal_regression",
        blocked_strategy_signatures=set(),
        blocked_transaction_signatures=set(),
    )

    assert policy_strategy_signature(policy) == "async:coordinated_pivot"
    scripts = {script.robot_id: script.code for script in policy.robot_scripts}
    assert "api.coordinated_pivot" in scripts["front"]
    assert "travel_direction='forward'" in scripts["front"]
    assert "role='outer'" in scripts["front"]
    assert "role='inner'" in scripts["back"]
    assert {assignment.role for assignment in policy.assignments} == {"inner", "outer"}

    with pytest.raises(
        ModelAgentError,
        match="strategy-level failure requires changing",
    ):
        _compile_model_selected_coordination_policy(
            current_policy=policy,
            attempt=3,
            selected_subtask=selected_subtask,
            selected_parameters=selected,
            failure_level="strategy",
            failure_type="route_regression",
            blocked_strategy_signatures=set(),
            blocked_transaction_signatures=set(),
        )
    _compiled, rewound_policy = _compile_model_selected_coordination_policy(
        current_policy=policy,
        attempt=3,
        selected_subtask=selected_subtask,
        selected_parameters=selected,
        failure_level="strategy",
        failure_type="route_regression",
        blocked_strategy_signatures=set(),
        blocked_transaction_signatures=set(),
        explicit_branch_rewind=True,
    )
    assert policy_strategy_signature(rewound_policy) == "async:coordinated_pivot"


