def test_coordination_parameter_stage_retries_compiler_rejected_role_pattern():
    selected_subtask = {
        "selected_method": "coordinated_alignment",
        "coordination_mode": "async",
        "motion_objective_parameter": "axis",
        "motion_objective": "lateral",
        "reason": "repair one failed alignment relation",
    }

    def code(delta: float) -> str:
        return (
            "def policy(api):\n"
            f"    api.coordinated_alignment(axis='lateral', delta={delta}, duration_s=2.0)\n"
            "    api.stop_all()\n"
        )

    current = PolicyScript(
        script_id="alignment_current",
        attempt=1,
        code=code(0.05),
        robot_scripts=(
            RobotPolicyScript(
                "front",
                "front_current",
                code(0.05),
                "team",
                coordination_mode="async",
            ),
            RobotPolicyScript(
                "back",
                "back_current",
                code(0.0),
                "team",
                coordination_mode="async",
            ),
        ),
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "duration_s": 3.0,
                    "front_delta": 0.05,
                    "back_delta": 0.0,
                    "reason": "repeat the rejected roles",
                }
            ),
            json.dumps(
                {
                    "duration_s": 2.0,
                    "front_delta": 0.0,
                    "back_delta": 0.05,
                    "reason": "swap the temporary roles",
                }
            ),
        ]
    )
    compiled: list[PolicyScript] = []

    def validate_candidate(candidate: dict) -> None:
        _payload, policy = _compile_model_selected_coordination_policy(
            current_policy=current,
            attempt=2,
            selected_subtask=selected_subtask,
            selected_parameters=candidate,
            failure_level="coordination",
            failure_type="payload_drop",
            blocked_strategy_signatures=set(),
            blocked_transaction_signatures=set(),
        )
        compiled[:] = [policy]

    selected = _select_coordination_parameters(
        client=client,
        selected_subtask=selected_subtask,
        payload={
            "observation": {"runtime_state": _supported_observation().runtime_state},
            "evaluation": {"success": False, "failure_type": "payload_drop"},
        },
        candidate_validator=validate_candidate,
    )

    assert len(client.prompts) == 2
    assert "swap the front/back delta assignments" in client.prompts[1]["user"]
    assert selected["robot_parameters"]["front"]["delta"] == 0.0
    assert selected["robot_parameters"]["back"]["delta"] == 0.05
    assert compiled[0].robot_scripts[0].code.strip() == code(0.0).strip()


