def test_alignment_script_repair_rejects_magnitude_only_rewrite():
    def alignment_policy(
        attempt: int,
        *,
        axis: str = "longitudinal",
        front_delta: float = 0.0,
        back_delta: float = 0.082,
    ) -> PolicyScript:
        def code(delta: float) -> str:
            return (
                "def policy(api):\n"
                f"    api.coordinated_alignment(axis='{axis}', "
                f"delta={delta}, duration_s=1.0)\n"
                "    api.stop_all()\n"
            )

        return PolicyScript(
            script_id=f"alignment_script_{attempt}",
            attempt=attempt,
            code=code(front_delta),
            robot_scripts=(
                RobotPolicyScript(
                    "front",
                    f"front_alignment_{attempt}",
                    code(front_delta),
                    "alignment_team",
                    coordination_mode="async",
                ),
                RobotPolicyScript(
                    "back",
                    f"back_alignment_{attempt}",
                    code(back_delta),
                    "alignment_team",
                    coordination_mode="async",
                ),
            ),
        )

    previous = alignment_policy(1)
    with pytest.raises(ModelAgentError, match="structural rewrite"):
        _validate_failure_level_repair(
            previous,
            alignment_policy(2, back_delta=0.081),
            failure_level="script",
            failure_type="payload_slip",
            blocked_strategy_signatures=set(),
        )

    _validate_failure_level_repair(
        previous,
        alignment_policy(
            2,
            axis="lateral",
            front_delta=0.081,
            back_delta=0.0,
        ),
        failure_level="script",
        failure_type="payload_slip",
        blocked_strategy_signatures=set(),
    )


