def test_release_checkpoint_roundtrip_uses_target_support_gate(monkeypatch, tmp_path):
    calls = {}

    def fake_wait(path, **kwargs):
        calls["path"] = path
        calls.update(kwargs)
        return {"payload": {"contacts": {"target": True}}}

    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution.wait_for_payload_on_target",
        fake_wait,
    )
    monkeypatch.setattr(
        "scripts.run_cap_box_carry_evolution.read_payload_runtime_status",
        lambda *_args, **_kwargs: PayloadRuntimeStatus(
            available=True,
            fresh=True,
            active=True,
            z=0.65,
        ),
    )

    runtime_state_file = tmp_path / "runtime_state.json"
    gate = _observe_checkpoint_roundtrip_stability(
        runtime_state_file=runtime_state_file,
        policy_action="release_payload",
        stable_s=3.0,
        safety_profile="task",
    )

    assert gate["success"] is True
    assert gate["lifecycle"] == "post_release_target_support"
    assert gate["target_contact"] is True
    assert calls["path"] == runtime_state_file
    assert calls["require_released"] is True
    assert calls["allow_robot_contact"] is True


def test_linear_execution_repair_uses_latest_call_and_changes_one_magnitude():
    def linear_policy(
        attempt: int, distance_m: float, speed_mps: float
    ) -> PolicyScript:
        code = (
            "def policy(api):\n"
            "    api.coordinated_linear_transport(direction='forward', "
            f"distance_m={distance_m}, speed_mps={speed_mps}, ramp_s=1.5)\n"
            "    api.stop_all()\n"
        )
        return PolicyScript(
            script_id=f"linear_{attempt}",
            attempt=attempt,
            code=code,
            robot_scripts=tuple(
                RobotPolicyScript(
                    robot_id,
                    f"{robot_id}_linear",
                    code,
                    "team",
                    coordination_mode="sync",
                )
                for robot_id in ("front", "back")
            ),
        )

    previous = linear_policy(35, 1.5, 0.5)
