def test_repeated_physical_failure_escalates_without_permanent_strategy_ban(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )
    decisions = []
    for attempt in range(1, 3):
        decisions.append(
            controller.record_and_decide(
                policy=_controller_policy(attempt, coordination_mode="async"),
                report=EvaluationReport(
                    success=False,
                    failure_type="formation_desync",
                ),
                trace=None,
                checkpoint_id="accepted_step_01",
                physically_dispatched=True,
            )
        )
    decisions.append(
        controller.record_and_decide(
            policy=_controller_policy(3, coordination_mode="async"),
            report=EvaluationReport(
                success=False,
                failure_type="formation_desync",
            ),
            trace=None,
            checkpoint_id="accepted_step_01",
            physically_dispatched=True,
        )
    )

    assert [item.strategy_failure_count for item in decisions] == [1, 2, 3]
    assert [item.action for item in decisions] == [
        "rewrite_script",
        "change_coordination",
        "change_coordination",
    ]
    assert controller.exhausted_strategy_signatures == ()
    assert controller.exhausted_motion_objectives == ()

    controller.record_and_decide(
        policy=_controller_policy(4, coordination_mode="sync"),
        report=EvaluationReport(
            success=True,
            failure_type="none",
            metrics={"task_complete": 0.0},
        ),
        trace=None,
        checkpoint_id="accepted_step_01",
        physically_dispatched=True,
    )
    after_success = controller.record_and_decide(
        policy=_controller_policy(5, coordination_mode="sync"),
        report=EvaluationReport(
            success=False,
            failure_type="formation_desync",
        ),
        trace=None,
        checkpoint_id="accepted_step_04",
        physically_dispatched=True,
    )

    assert after_success.strategy_failure_count == 1
    assert after_success.action == "rewrite_script"


