def test_evolution_controller_stops_before_generating_attempt_beyond_budget(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=1,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )
    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        evolution_controller=controller,
    )
    policy = _controller_policy(1)
    report = EvaluationReport(
        success=False,
        failure_type="no_payload_progress",
        metrics={
            "required_step_displacement_m": 0.05,
            "payload_step_displacement_xy_m": 0.0,
        },
    )

    decision = agent.decide_next_step(
        policy,
        report,
        _supported_observation(),
        physically_dispatched=True,
    )
    next_policy, spec = agent.evolve(
        policy,
        report,
        _supported_observation(),
        controller_decision=decision,
    )

    assert decision.action == "stop_budget_exhausted"
    assert not decision.should_evolve
    assert next_policy == policy
    assert spec == ""
    assert agent.client.prompts == []


