def test_evolution_controller_reports_efficiency_and_strategy_improvement(tmp_path):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )
    controller.record_and_decide(
        policy=_controller_policy(1, method="carry_forward"),
        report=EvaluationReport(success=False, failure_type="goal_regression"),
        trace=None,
        checkpoint_id="accepted_step_00",
        physically_dispatched=True,
    )
    controller.record_and_decide(
        policy=_controller_policy(
            2,
            method="carry_lateral_left",
            coordination_mode="async",
        ),
        report=EvaluationReport(
            success=True, failure_type="none", metrics={"task_complete": 0.0}
        ),
        trace=None,
        checkpoint_id="accepted_step_00",
        physically_dispatched=True,
    )
    final_decision = controller.record_and_decide(
        policy=_controller_policy(
            3,
            method="carry_lateral_left",
            coordination_mode="async",
        ),
        report=EvaluationReport(
            success=True, failure_type="none", metrics={"task_complete": 1.0}
        ),
        trace=None,
        checkpoint_id="accepted_step_01",
        physically_dispatched=True,
    )
    metrics = controller.metrics()

    assert final_decision.action == "task_complete"
    assert not final_decision.should_evolve
    assert metrics["task_success_rate"] == 1.0
    assert metrics["physical_iterations"] == 3
    assert metrics["accepted_physical_iterations"] == 2
    assert metrics["rejected_physical_iterations"] == 1
    assert metrics["physical_accounting_complete"] is True
    assert (
        metrics["accepted_physical_iterations"]
        + metrics["rejected_physical_iterations"]
        == metrics["physical_iterations"]
    )
    assert metrics["iterations_to_success"] == 3
    assert metrics["evolution_efficiency"] == pytest.approx(1.0 / 3.0)
    assert (
        metrics["strategy_improvement"]["initial_failed_strategy"]
        == "sync:carry_forward"
    )
    assert (
        metrics["strategy_improvement"]["final_successful_strategy"]
        == "async:carry_lateral_left"
    )
    assert metrics["strategy_improvement"]["verified_strategy_improvement"] is True


