def test_attempt_memory_is_retrieved_by_the_next_policy_generation(tmp_path):
    memory_path = tmp_path / "strategy.json"
    store = StrategyMemoryStore(memory_path)
    trace = ExecutionTrace(
        script_id="box_carry_attempt_01",
        attempt=1,
        status="success",
        skill_calls=(
            SkillCallRecord(
                index=1,
                skill_name="carry_forward",
                parameters={},
                status="success",
                started_at_unix=1.0,
                finished_at_unix=2.0,
            ),
        ),
    )
    append_rollout_evidence(
        tmp_path / "raw.jsonl",
        "",
        dry_run=False,
        policy=_controller_policy(1),
        report=EvaluationReport(success=False, failure_type="formation_desync"),
        trace=trace,
        strategy_store=store,
        strategy_phase="straight_transport",
        physically_dispatched=True,
        physical_transaction_completed=True,
    )
    retrieved = tuple(
        store.retrieve(
            StrategyContext(
                phase="straight_transport",
                last_failure_type="formation_desync",
                last_failure_level="script",
            ),
            limit=3,
        )
    )
    code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.5, speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_02",
                    "rationale": "Use the verifier-grounded coordination evidence.",
                    "plan": ["execute one bounded transport"],
                    "code": code,
                    **_explicit_team_fields(code),
                }
            )
        ]
    )
    observation = replace(_supported_observation(), retrieved_specs=retrieved)

    ModelTaskOrchestrator(client=client).generate_initial_policy(
        BoxCarryTask(task_id="memory_timing", target="carry payload"),
        observation,
        attempt=2,
    )

    assert retrieved
    prompt = client.prompts[0]["user"]
    assert "deployment_spec" in prompt
    assert "formation_desync" in prompt
    assert "box_carry_attempt_02" not in memory_path.read_text(encoding="utf-8")


