def test_persisted_policy_and_trace_restore_coordination_mode(tmp_path):
    code = "def policy(api):\n    api.hold_position(hold_s=2.0)\n    api.stop_all()\n"
    team = _explicit_team_fields(code)
    for assignment in team["assignments"]:
        assignment["coordination_mode"] = "async"
    for script in team["robot_scripts"]:
        script["coordination_mode"] = "async"
    policy_path = tmp_path / "policy.json"
    policy_path.write_text(
        json.dumps(
            {
                "script_id": "resume_async",
                "attempt": 4,
                "code": code,
                **team,
            }
        ),
        encoding="utf-8",
    )
    trace_path = tmp_path / "execution_trace.json"
    trace_path.write_text(
        json.dumps(
            {
                "script_id": "resume_async",
                "attempt": 4,
                "status": "success",
                "robot_executions": [
                    {
                        "robot_id": robot_id,
                        "script_id": f"{robot_id}_policy",
                        "status": "command_publish_completed",
                        "synchronization_group": "carry_team",
                        "coordination_mode": "async",
                        "planned_calls": [],
                    }
                    for robot_id in ("front", "back")
                ],
            }
        ),
        encoding="utf-8",
    )

    policy = _load_policy(policy_path)
    trace = _load_execution_trace(trace_path)

    assert {item.coordination_mode for item in policy.assignments} == {"async"}
    assert {item.coordination_mode for item in policy.robot_scripts} == {"async"}
    assert {item.coordination_mode for item in trace.robot_executions} == {"async"}


def test_failed_resume_can_read_newly_blocked_parameters_without_reauthorizing_them(
    tmp_path,
):
    code = (
        "def policy(api):\n"
        "    api.coordinated_arc_transport(turn_direction='clockwise', angle_deg=15, "
        "duration_s=4.0, radius_m=0.0)\n"
        "    api.stop_all()\n"
    )
    team = _explicit_team_fields(code)
    policy_path = tmp_path / "failed_policy.json"
    policy_path.write_text(
        json.dumps(
            {
                "script_id": "legacy_failed_zero_radius_arc",
                "attempt": 16,
                "code": code,
                **team,
            }
        ),
        encoding="utf-8",
    )

    with pytest.raises(ValueError, match="radius_m must be >= 0.05"):
        _load_policy(policy_path)

    historical = _load_policy(
        policy_path,
        allow_legacy_invalid_parameters=True,
    )

    assert historical.script_id == "legacy_failed_zero_radius_arc"
    with pytest.raises(ValueError, match="radius_m must be >= 0.05"):
        validate_step_policy_code(historical.robot_scripts[0].code)

    evidence = append_rollout_evidence(
        tmp_path / "raw_rollout_evidence.jsonl",
        "failed historical evidence",
        dry_run=False,
        policy=historical,
        report=EvaluationReport(success=False, failure_type="payload_drop"),
    )
    assert evidence["executed_skill"] == "coordinated_arc_transport"


