def test_policy_executor_dispatches_distinct_sync_groups_to_robot_scopes(tmp_path):
    front_code = (
        "def policy(api):\n    api.hold_position(hold_s=1.5)\n    api.stop_all()\n"
    )
    back_code = (
        "def policy(api):\n    api.hold_position(hold_s=2.0)\n    api.stop_all()\n"
    )
    policy = PolicyScript(
        script_id="ordered_reposition",
        attempt=1,
        code=front_code,
        robot_scripts=(
            RobotPolicyScript(
                robot_id="front",
                script_id="front_reposition",
                code=front_code,
                synchronization_group="front_reposition_group",
                phase_id="front_wait",
                contact_intent="hold",
            ),
            RobotPolicyScript(
                robot_id="back",
                script_id="back_wait",
                code=back_code,
                synchronization_group="back_wait_group",
                phase_id="back_support_wait",
                contact_intent="hold",
            ),
        ),
    )
    api = G1SkillAPI(
        backend=StaticSonicSkillBackend(execute=False),
        output_dir=tmp_path / "skills",
        heartbeat_file=tmp_path / "planner_heartbeat.json",
    )

    trace = PolicyExecutor(tmp_path / "attempt").execute(policy, api)

    assert trace.status == "success"
    assert [record.skill_name for record in trace.skill_calls] == [
        "hold_position",
        "stop_all",
        "hold_position",
        "stop_all",
    ]
    assert [record.robot_ids for record in trace.skill_calls] == [
        ("front",),
        ("front",),
        ("back",),
        ("back",),
    ]


def test_skill_api_uses_backend_payload_support_center_limit(tmp_path, monkeypatch):
    captured: dict[str, object] = {}

    def fake_wait_for_payload_supported(runtime_state_file, **kwargs):
        captured["runtime_state_file"] = runtime_state_file
        captured.update(kwargs)

    monkeypatch.setattr(
        skill_api_module,
        "wait_for_payload_supported",
        fake_wait_for_payload_supported,
    )
    runtime_state_file = tmp_path / "runtime_state.json"
    api = G1SkillAPI(
        backend=StaticSonicSkillBackend(
            execute=True,
            max_payload_support_center_error_m=0.10,
        ),
        output_dir=tmp_path / "skills",
        heartbeat_file=tmp_path / "planner_heartbeat.json",
        runtime_state_file=runtime_state_file,
    )

    api._require_payload_supported(timeout_s=3.0, stable_s=0.3)

    assert captured["runtime_state_file"] == runtime_state_file
    assert captured["timeout_s"] == pytest.approx(3.0)
    assert captured["stable_s"] == pytest.approx(0.3)
    assert captured["max_support_center_xy_error_m"] == pytest.approx(0.10)


def test_static_transport_final_gate_uses_task_profile_dual_robot_support(
    tmp_path,
    monkeypatch,
):
    captured: dict[str, object] = {}
    expected = PayloadRuntimeStatus(available=True)

    def fake_wait_for_payload_supported(runtime_state_file, **kwargs):
        captured["runtime_state_file"] = runtime_state_file
        captured.update(kwargs)
        return expected

    monkeypatch.setattr(
        static_skill_runner_module,
        "wait_for_payload_supported",
        fake_wait_for_payload_supported,
    )
    args = SimpleNamespace(
        runtime_state_file=tmp_path / "runtime_state.json",
        payload_verify_timeout_s=15.0,
        payload_support_stable_s=1.0,
        runtime_state_max_age_s=1.0,
        payload_min_z=0.80,
        payload_safety_max_support_center_error_m=0.10,
        payload_require_all_support_pads=False,
        payload_safety_profile="task",
    )

    result = _wait_for_pre_transport_support(args)

    assert result is expected
    assert captured["runtime_state_file"] == args.runtime_state_file
    assert captured["stable_s"] == pytest.approx(1.0)
    assert captured["max_support_center_xy_error_m"] == pytest.approx(0.10)
    assert captured["require_all_support_pads"] is False
    assert captured["safety_profile"] == "task"


