def test_sync_compensation_keeps_both_robots_translating_for_shared_move_window():
    plan = CoordinatedTeamPlan(
        coordination_mode="sync",
        phase_id="measured_sync_compensation",
        synchronization_group="sync_compensation",
        actions={
            "front": TeamAction(
                "carry_forward",
                {"distance_m": 0.10, "speed_mps": 0.25, "ramp_s": 1.5},
            ),
            "back": TeamAction(
                "carry_forward",
                {"distance_m": 0.10, "speed_mps": 0.20, "ramp_s": 1.5},
            ),
        },
    )

    groups = build_coordinated_schedule(
        plan,
        minimum_transport_window_s=1.0,
        minimum_lateral_transport_window_s=2.0,
        transport_duration_gain=1.0,
        transport_duration_baseline_m=0.05,
        minimum_transport_ramp_s=1.5,
    )

    moving_groups = [
        group
        for group in groups
        if any(
            command.mode == SonicLocomotionMode.SLOW_WALK for command in group.values()
        )
    ]
    assert moving_groups
    assert all(
        all(command.mode == SonicLocomotionMode.SLOW_WALK for command in group.values())
        for group in moving_groups
    )
    assert all(
        all(command.motion_axis == "longitudinal" for command in group.values())
        for group in moving_groups
    )
    assert sum(group["front"].duration_s for group in moving_groups) == pytest.approx(
        1.25
    )
    assert sum(group["back"].duration_s for group in moving_groups) == pytest.approx(
        1.25
    )
    assert all(group["front"].speed == pytest.approx(0.25) for group in moving_groups)
    assert all(group["back"].speed == pytest.approx(0.20) for group in moving_groups)


def test_sync_compensated_schedule_remains_adjustable_for_both_robots(tmp_path):
    plan = CoordinatedTeamPlan(
        coordination_mode="sync",
        phase_id="measured_sync_compensation",
        synchronization_group="sync_compensation",
        actions={
            "front": TeamAction(
                "carry_forward",
                {"distance_m": 0.10, "speed_mps": 0.20, "ramp_s": 1.5},
            ),
            "back": TeamAction(
                "carry_forward",
                {"distance_m": 0.05, "speed_mps": 0.20, "ramp_s": 1.5},
            ),
        },
    )
    groups = build_coordinated_schedule(
        plan,
        minimum_transport_window_s=1.0,
        minimum_lateral_transport_window_s=2.0,
        transport_duration_gain=1.0,
        transport_duration_baseline_m=0.05,
        minimum_transport_ramp_s=1.5,
    )
    moving_group = next(
        group
        for group in groups
        if group["front"].mode == SonicLocomotionMode.SLOW_WALK
    )
    controller = FormationSyncController(
        tmp_path / "runtime_state.json",
        FormationSyncConfig(active_catchup=True, error_filter_alpha=1.0),
    )
    controller.adjust_snapshot(
        moving_group,
        TeamMotionSnapshot(
            available=True,
            fresh=True,
            sim_time_s=1.0,
            robot_xy={"front": (0.0, 0.5), "back": (0.0, -0.5)},
            payload_xy=(0.0, 0.0),
            support_target_xy=(0.0, 0.0),
        ),
    )

    adjusted, failure = controller.adjust_snapshot(
        moving_group,
        TeamMotionSnapshot(
            available=True,
            fresh=True,
            sim_time_s=1.1,
            robot_xy={"front": (0.0, 0.5), "back": (0.010, -0.5)},
            payload_xy=(0.0, 0.0),
            support_target_xy=(0.0, 0.0),
        ),
    )

    assert failure == ""
    assert adjusted["front"].mode == SonicLocomotionMode.SLOW_WALK
    assert adjusted["back"].mode == SonicLocomotionMode.SLOW_WALK
    assert adjusted["front"].speed > moving_group["front"].speed
    assert adjusted["back"].speed < moving_group["back"].speed


