def test_model_evolution_repairs_failed_policy_and_writes_spec(tmp_path):
    current = PolicyScript(
        script_id="box_carry_attempt_01",
        attempt=1,
        code="def policy(api):\n    api.carry_lateral_left(distance_m=1.5, speed_mps=0.35)\n",
        rationale="UNVERIFIED_MODEL_CLAIM: verifier accepted a hidden repair seed",
    )
    report = EvaluationReport(
        success=False,
        failure_type="payload_drop",
        failed_subtask="carry_lateral_left",
        recommendations=("reduce speed and re-place the payload",),
    )
    repaired_code = (
        "def policy(api):\n"
        "    api.carry_lateral_left(distance_m=0.4, speed_mps=0.20)\n"
        "    api.stop_all()\n"
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_02",
                    "rationale": "Payload dropped, so re-place and slow down.",
                    "plan": ["re-place payload", "short slow lateral segment"],
                    "code": repaired_code,
                    **_explicit_team_fields(repaired_code),
                    "spec_candidate": "failure_spec: payload_drop -> slow short lateral segment",
                }
            )
        ]
    )

    repaired, spec = ModelCollaborativeEvolutionAgent(tmp_path, client=client).evolve(
        current,
        report,
        _supported_observation(),
        ExecutionTrace(script_id=current.script_id, attempt=1, status="success"),
    )

    assert repaired.script_id == "box_carry_attempt_02"
    assert repaired.parent_script_id == "box_carry_attempt_01"
    assert "speed_mps=0.2" in repaired.code or "speed_mps=0.20" in repaired.code
    assert spec.startswith("failure_spec")
    assert (tmp_path / "model_evolution_decision_01.json").exists()
    assert "FAST ACTION-MAGNITUDE PROTOCOL" in client.prompts[0]["user"]
    assert (
        "bad API call, parameter, or front/back command relation"
        in client.prompts[0]["user"]
    )
    assert "materially different executable AST" in client.prompts[0]["user"]
    assert "shared coordination_mode" in client.prompts[0]["user"]
    assert "HOST EVOLUTION CONTROLLER DIRECTIVE (HARD)" in client.prompts[0]["user"]
    assert "action=rewrite_script" in client.prompts[0]["user"]
    assert '"failure_level": "script"' in client.prompts[0]["user"]
    assert "UNVERIFIED_MODEL_CLAIM" not in client.prompts[0]["user"]


def test_team_mode_conflict_is_rejected_without_host_rewrite():
    payload = {
        "assignments": {
            "front": {"coordination_mode": "sync"},
            "back": {"coordination_mode": "async"},
        },
        "robot_scripts": {
            "front": {
                "coordination_mode": "sync",
                "code": (
                    "def policy(api):\n"
                    "    api.carry_forward(distance_m=0.2, speed_mps=0.25, ramp_s=1.5)\n"
                    "    api.stop_all()"
                ),
            },
            "back": {
                "coordination_mode": "async",
                "code": "def policy(api):\n    api.hold_position(hold_s=2)\n    api.stop_all()",
            },
        },
    }

    before = json.loads(json.dumps(payload))
    with pytest.raises(ModelAgentError, match="Host will not rewrite"):
        _canonicalize_team_coordination_mode(payload)

    assert payload == before
    assert {
        entry["coordination_mode"] for entry in payload["assignments"].values()
    } == {"sync", "async"}
    assert {
        entry["coordination_mode"] for entry in payload["robot_scripts"].values()
    } == {"sync", "async"}
    assert "api.carry_forward" in payload["robot_scripts"]["front"]["code"]
    assert "api.hold_position" in payload["robot_scripts"]["back"]["code"]


def _identical_async_model_payload() -> dict[str, object]:
    code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.10, speed_mps=0.25, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    return {
        "script_id": "fake_async_model_plan",
        "rationale": "change only the mode label",
        "plan": ["move both robots"],
        "assignments": {
            robot_id: {
                "role": "mover",
                "objective": "shared forward transport",
                "synchronization_group": "carry_team",
                "phase_id": "transport",
                "contact_intent": "maintain_payload_support",
                "coordination_mode": "async",
            }
            for robot_id in ("front", "back")
        },
        "robot_scripts": {
            robot_id: {
                "script_id": f"{robot_id}_fake_async",
                "code": code,
                "synchronization_group": "carry_team",
                "phase_id": "transport",
                "contact_intent": "maintain_payload_support",
                "coordination_mode": "async",
            }
            for robot_id in ("front", "back")
        },
    }


def test_identical_async_model_calls_are_rejected_without_mode_rewrite():
    payload = _identical_async_model_payload()
    before = json.loads(json.dumps(payload))

    with pytest.raises(ModelAgentError, match="Host will not rewrite"):
        _canonicalize_team_coordination_mode(payload)

    assert payload == before


