def test_code_string_shorthand_inherits_only_redundant_assignment_metadata():
    front_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.2, speed_mps=0.2, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    back_code = front_code.replace("distance_m=0.2", "distance_m=0.15")
    payload = {
        "assignments": {
            robot_id: {
                "role": "mover",
                "objective": "calibrated forward transport",
                "synchronization_group": "carry_team",
                "phase_id": "forward_calibration",
                "contact_intent": "maintain_payload_support",
                "coordination_mode": "sync",
            }
            for robot_id in ("front", "back")
        },
        "robot_scripts": {"front": front_code, "back": back_code},
    }

    changes = _canonicalize_robot_script_shorthand(payload)

    assert changes
    assert payload["robot_scripts"]["front"]["code"] == front_code
    assert payload["robot_scripts"]["back"]["code"] == back_code
    assert payload["robot_scripts"]["front"]["synchronization_group"] == "carry_team"
    assert payload["robot_scripts"]["back"]["phase_id"] == "forward_calibration"


