def test_sync_replan_enforces_measured_per_robot_speed_order(tmp_path):
    rejected_dir = tmp_path / "attempt_02"
    rejected_dir.mkdir()
    equal_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.20, speed_mps=0.25, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    rejected_policy = {
        "script_id": "box_carry_attempt_02",
        "attempt": 2,
        "code": equal_code,
        **_explicit_team_fields(equal_code),
    }
    (rejected_dir / "policy.json").write_text(
        json.dumps(rejected_policy), encoding="utf-8"
    )
    (rejected_dir / "evaluation.json").write_text(
        json.dumps(
            {
                "success": False,
                "failure_type": "formation_desync",
                "failed_subtask": "carry_forward",
                "metrics": {
                    "front_step_displacement_m": 0.244,
                    "back_step_displacement_m": 0.329,
                    "front_back_step_vector_desync_m": 0.088,
                },
            }
        ),
        encoding="utf-8",
    )
    (rejected_dir / "evolution_record.json").write_text(
        json.dumps({"checkpoint_before": "accepted_step_01"}),
        encoding="utf-8",
    )
    (rejected_dir / "execution_trace.json").write_text(
        json.dumps({"skill_calls": [{"status": "ok"}]}),
        encoding="utf-8",
    )
    hold_code = (
        "def policy(api):\n    api.hold_position(hold_s=2.0)\n    api.stop_all()"
    )
    current = PolicyScript(
        script_id="box_carry_attempt_05",
        attempt=5,
        code=hold_code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_hold",
                code=hold_code,
                synchronization_group="carry_team",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )
    compensated_front = equal_code
    compensated_back = equal_code.replace("speed_mps=0.25", "speed_mps=0.20")

    def team_fields(front_code: str, back_code: str) -> dict:
        return {
            "assignments": [
                {
                    "robot_id": robot_id,
                    "role": "synchronized_mover",
                    "objective": "calibrate forward transport",
                    "synchronization_group": "carry_team",
                    "phase_id": "calibrated_forward",
                    "contact_intent": "maintain_payload_support",
                    "coordination_mode": "sync",
                    "safety_constraints": [],
                }
                for robot_id in ("front", "back")
            ],
            "robot_scripts": [
                {
                    "robot_id": "front",
                    "script_id": "front_06",
                    "code": front_code,
                    "synchronization_group": "carry_team",
                    "phase_id": "calibrated_forward",
                    "contact_intent": "maintain_payload_support",
                    "coordination_mode": "sync",
                },
                {
                    "robot_id": "back",
                    "script_id": "back_06",
                    "code": back_code,
                    "synchronization_group": "carry_team",
                    "phase_id": "calibrated_forward",
                    "contact_intent": "maintain_payload_support",
                    "coordination_mode": "sync",
                },
            ],
        }

    client = FakeModelClient(
        [
            json.dumps(
                {
                    "selected_method": "carry_forward",
                    "coordination_mode": "sync",
                    "reason": "retain the progress-producing method and calibrate the pair",
                }
            ),
            json.dumps(
                {
                    "front_distance_m": 0.20,
                    "back_distance_m": 0.20,
                    "front_speed_mps": 0.25,
                    "back_speed_mps": 0.19,
                    "reason": "over-correct the farther back executor",
                }
            ),
            json.dumps(
                {
                    "front_distance_m": 0.20,
                    "back_distance_m": 0.20,
                    "front_speed_mps": 0.25,
                    "back_speed_mps": 0.20,
                    "reason": "use the maximum permitted bounded sync compensation",
                }
            ),
            json.dumps(
                {
                    "script_id": "box_carry_attempt_06",
                    "rationale": "retry equal commands",
                    "plan": ["bounded forward calibration"],
                    "spec_candidate": "candidate only",
                    **team_fields(equal_code, equal_code),
                }
            ),
            json.dumps(
                {
                    "script_id": "box_carry_attempt_06",
                    "rationale": "apply measured back-speed compensation",
                    "plan": ["bounded forward calibration"],
                    "spec_candidate": "candidate only",
                    **team_fields(compensated_front, compensated_back),
                }
            ),
        ]
    )
    observation = ObservationBundle(
        runtime_state={
            **_supported_observation().runtime_state,
            "checkpoint": {"checkpoint_id": "accepted_step_01"},
        }
    )

    repaired, _spec = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=client,
        measured_sync_compensation_enabled=True,
    ).evolve(
        current,
        EvaluationReport(
            success=True,
            failure_type="none",
            metrics={"task_complete": 0.0},
        ),
        observation,
    )

    assert "speed_mps=0.2" in repaired.robot_scripts[1].code
    assert "measured-parameter calibration stage" in client.prompts[1]["system"]
    assert '"farther_robot": "back"' in client.prompts[1]["user"]
    assert '"farther_displacement_m": 0.329' in client.prompts[1]["user"]
    assert len(client.prompts) == 3
    assert "sync speed compensation delta 0.06" in client.prompts[2]["user"]
    compiled = json.loads(
        (tmp_path / "model_evolution_decision_05.json").read_text(encoding="utf-8")
    )["compiled_from_model_decisions"]
    assert compiled["subtask"]["coordination_mode"] == "sync"
    assert compiled["parameters"]["back_speed_mps"] == 0.20


