def test_coordination_selector_chooses_semantic_objective_before_code_synthesis():
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "selected_method": "coordinated_linear_transport",
                    "coordination_mode": "sync",
                    "motion_objective": "forward",
                    "reason": "rename the rejected forward mover",
                }
            ),
            json.dumps(
                {
                    "selected_method": "coordinated_linear_transport",
                    "coordination_mode": "sync",
                    "motion_objective": "left",
                    "reason": "infer another body-frame objective from current geometry",
                }
            ),
        ]
    )
    code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=2.0, speed_mps=0.50, ramp_s=1.5)\n"
        "    api.stop_all()"
    )

    selection = _select_evolution_subtask(
        client=client,
        payload={
            "task_stage": "full_scene",
            "current_policy": {
                "code": code,
                "robot_scripts": [
                    {
                        "robot_id": robot_id,
                        "code": code,
                        "coordination_mode": "sync",
                    }
                    for robot_id in ("front", "back")
                ],
            },
            "evaluation": {
                "success": False,
                "failure_type": "goal_regression",
                "metrics": {"payload_target_progress_m": -0.5},
            },
            "evolution_controller": {
                "action": "switch_strategy",
                "repair_level": "strategy",
            },
            "observation": {"runtime_state": {}},
            "coordination_primitive_sdk": "enabled",
        },
        forbidden_methods=("carry_forward",),
        blocked_strategy_signatures=("sync:carry_forward",),
        response_retries=1,
    )

    assert selection == {
        "selected_method": "coordinated_linear_transport",
        "coordination_mode": "sync",
        "motion_objective_parameter": "direction",
        "motion_objective": "left",
        "reason": "infer another body-frame objective from current geometry",
    }
    selector_context = json.loads(client.prompts[0]["user"].rsplit("\n\n", 1)[1])
    assert selector_context["required_motion_objective_by_method"][
        "coordinated_linear_transport"
    ] == {
        "parameter": "direction",
        "choices": ["backward", "left", "right"],
    }
    assert (
        "motion_objective for api.coordinated_linear_transport"
        in client.prompts[1]["user"]
    )


