    assert (
        'must literally be "clockwise" or "counterclockwise"'
        in client.prompts[1]["user"]
    )
    assert 'never return "turn_direction"' in client.prompts[1]["user"]
    assert "direction_evidence" in client.prompts[1]["user"]
    assert "alternative_rejection_reason" in client.prompts[1]["user"]
    assert "must additionally" in client.prompts[0]["system"]
    assert "contain direction_evidence" in client.prompts[0]["system"]
    assert "alternative_direction" in client.prompts[0]["system"]
    assert "coordinated_in_place_turn" not in client.prompts[0]["system"]
    assert "coordinated_pivot" in client.prompts[0]["system"]


