def test_selector_rejects_linear_direction_against_current_goal_projection():
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "selected_method": "coordinated_linear_transport",
                    "coordination_mode": "sync",
                    "motion_objective": "right",
                    "reason": "try another remaining body-frame direction",
                }
            ),
            json.dumps(
                {
                    "selected_method": "coordinated_linear_transport",
                    "coordination_mode": "sync",
                    "motion_objective": "left",
                    "reason": "body-left has the strongest positive current-goal projection",
                }
            ),
        ]
    )
    hold_code = (
        "def policy(api):\n    api.hold_position(hold_s=2.0)\n    api.stop_all()"
    )

    selection = _select_evolution_subtask(
        client=client,
        payload={
            "task_stage": "stage3_right",
            "current_policy": {
                "code": hold_code,
                "robot_scripts": [
                    {
                        "robot_id": robot_id,
                        "code": hold_code,
                        "coordination_mode": "sync",
                    }
                    for robot_id in ("front", "back")
                ],
            },
            "evaluation": {
                "success": True,
                "failure_type": "none",
                "metrics": {
                    "task_complete": 0.0,
                    "active_stage_goal_x_m": 1.35,
                    "active_stage_goal_y_m": 7.60,
                },
            },
            "evolution_controller": {
                "action": "continue",
                "repair_level": "none",
            },
            "observation": {
                "runtime_state": {
                    "payload": {"x": 1.90, "y": 2.19},
                    "robots": {
                        "front": {"yaw_deg": 0.0},
                        "back": {"yaw_deg": 0.0},
                    },
                }
            },
            "coordination_primitive_sdk": "enabled",
        },
        forbidden_methods=(),
        forbidden_objectives=(
            "coordinated_linear_transport:forward",
            "coordinated_linear_transport:backward",
        ),
        response_retries=1,
    )

    assert selection["motion_objective"] == "left"
    assert selection["best_available_goal_direction"] == "left"
    assert selection["goal_alignment_score"] > 0.9
    selector_context = json.loads(client.prompts[0]["user"].rsplit("\n\n", 1)[1])
    scores = selector_context["body_frame_goal_alignment"]["candidate_goal_alignment"]
    assert scores["left"] > 0.9
    assert scores["right"] < -0.9
    assert (
        "contradicts the current trusted-state goal projection"
        in client.prompts[1]["user"]
    )
    assert "FINAL HOST ENUM CONTRACT" in client.prompts[1]["user"]
    final_contract = client.prompts[1]["user"].split(
        "FINAL HOST ENUM CONTRACT",
        1,
    )[1]
    assert '"left"' in final_contract
    assert '"right"' in final_contract
    assert '"forward"' not in final_contract
    assert '"backward"' not in final_contract


