def _retired_left_transport_policy(
    attempt: int,
    *,
    distance_m: float,
) -> PolicyScript:
    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport("
        f"direction='left', distance_m={distance_m}, speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    return PolicyScript(
        script_id=f"box_carry_attempt_{attempt:02d}",
        attempt=attempt,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_box_carry_attempt_{attempt:02d}",
                code=code,
                synchronization_group=f"coordination_group_{attempt:02d}",
                phase_id=f"coordination_{attempt:02d}",
                contact_intent="maintain_payload_support",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )


def test_branch_rewind_records_failed_family_without_banning_it():
    retired_policy = _retired_left_transport_policy(12, distance_m=1.0)
    retired_signature = _policy_transaction_signature(retired_policy)
    context = _build_branch_rewind_context(
        task=BoxCarryTask(
            task_id="branch_family_exclusion",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        checkpoint_id="accepted_step_03",
        lesson="the restored checkpoint must leave the rejected pivot family",
        runtime_state={
            "payload": {"x": 0.0, "y": 0.0},
            "robots": {
                "front": {"yaw_deg": 0.0},
                "back": {"yaw_deg": 0.0},
            },
        },
        blocked_motion_objective="coordinated_linear_transport:forward",
        blocked_primitive_families=(
            "coordinated_pivot",
            "coordinated_pivot",
            "not_an_sdk_method",
        ),
        retired_child_transaction_signature=retired_signature,
        retired_child_transaction="front and back exact retired code",
    )

    assert context["blocked_motion_objective"] == ""
    assert context["blocked_primitive_families"] == []
    assert context["retired_child_motion_objective"] == (
        "coordinated_linear_transport:forward"
    )
    assert context["retired_child_primitive_families"] == ["coordinated_pivot"]
    assert context["source"] == "verified_descendant_branch_dead_end"
    assert _branch_rewind_forbidden_methods(context) == set()
    assert context["retired_child_transaction_signature"] == retired_signature
    assert context["retired_child_transaction"] == "front and back exact retired code"


def test_branch_rewind_can_exclude_one_route_regressing_objective(tmp_path):
    context = _build_branch_rewind_context(
        task=BoxCarryTask(
            task_id="branch_route_regression",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        checkpoint_id="accepted_step_31",
        lesson="forward repeatedly moved away from the active route frontier",
        runtime_state={
            "payload": {"x": 1.8, "y": 7.0},
            "robots": {
                "front": {"yaw_deg": 0.0},
                "back": {"yaw_deg": 0.0},
            },
        },
        blocked_motion_objective="coordinated_linear_transport:forward",
        enforce_blocked_motion_objective=True,
        source="operator_branch_rewind_note",
    )
    agent = ModelCollaborativeEvolutionAgent(
        output_dir=tmp_path,
        client=FakeModelClient([]),
        route_discovery=True,
        coordination_layer_enabled=True,
    )

    agent.rewind_to_checkpoint(
        "accepted_step_31",
        branch_rewind_context=context,
    )

    assert context["blocked_motion_objective"] == (
        "coordinated_linear_transport:forward"
    )
    assert agent.nonrelaxable_motion_objectives == (
        "coordinated_linear_transport:forward",
    )
    assert context["blocked_primitive_families"] == []
    assert context["persistence_mode"] == "until_route_objective_reoriented"

    translated_state = {
        "checkpoint": {"checkpoint_id": "accepted_step_32"},
        "payload": {"x": 1.67, "y": 7.26},
        "robots": {
            "front": {"yaw_deg": 0.0},
            "back": {"yaw_deg": 0.0},
        },
    }
    agent._refresh_rejected_transactions(
        checkpoint_id="accepted_step_32",
        runtime_state=translated_state,
    )
    assert agent.nonrelaxable_motion_objectives == (
        "coordinated_linear_transport:forward",
    )

    reoriented_state = {
        **translated_state,
        "checkpoint": {"checkpoint_id": "accepted_step_33"},
        "robots": {
            "front": {"yaw_deg": 180.0},
            "back": {"yaw_deg": 180.0},
        },
    }
    agent._refresh_rejected_transactions(
        checkpoint_id="accepted_step_33",
        runtime_state=reoriented_state,
    )
    assert agent.nonrelaxable_motion_objectives == ()


