def test_branch_rewind_expires_after_next_accepted_checkpoint():
    rewind = {
        "active": True,
        "scope_checkpoint_id": "accepted_step_35",
        "scope_active_goal_xy_m": [1.35, 7.6],
        "persistence_mode": "until_next_accepted_checkpoint",
        "blocked_motion_objective": "coordinated_linear_transport:left",
    }
    payload = {"branch_rewind_context": rewind}
    runtime = {"checkpoint": {"checkpoint_id": "accepted_step_37"}}
    still_left = {
        "active_goal_xy_m": [1.35, 7.6],
        "candidate_goal_alignment": {
            "forward": 0.25,
            "backward": -0.25,
            "left": 0.97,
            "right": -0.97,
        },
    }

    active = _active_branch_rewind_context(payload, runtime, still_left)

    assert active == {}

    restored_scope = {"checkpoint": {"checkpoint_id": "accepted_step_35"}}
    active_at_scope = _active_branch_rewind_context(
        payload,
        restored_scope,
        still_left,
    )
    assert active_at_scope["blocked_motion_objective"] == (
        "coordinated_linear_transport:left"
    )

    turned_forward = {
        **still_left,
        "candidate_goal_alignment": {
            "forward": 0.90,
            "backward": -0.90,
            "left": 0.43,
            "right": -0.43,
        },
    }
    assert _active_branch_rewind_context(payload, runtime, turned_forward) == {}

    changed_goal = {**still_left, "active_goal_xy_m": [-1.5, 7.6]}
    assert _active_branch_rewind_context(payload, runtime, changed_goal) == {}


