def test_repeated_controller_failures_do_not_remove_pairs_from_model_allowlist(
    tmp_path,
):
    controller = EvolutionController(
        max_physical_iterations=20,
        strategy_failure_budget=3,
        output_dir=tmp_path,
    )
    attempt = 1
    for method in ("coordinated_arc_transport", "coordinated_alignment"):
        for _ in range(3):
            controller.record_and_decide(
                policy=_controller_policy(
                    attempt,
                    method=method,
                    coordination_mode="async",
                ),
                report=EvaluationReport(
                    success=False,
                    failure_type="no_payload_progress",
                ),
                trace=None,
                checkpoint_id="accepted_step_09",
                physically_dispatched=True,
            )
            attempt += 1

    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        strategy_failure_budget=3,
        coordination_layer_enabled=True,
        evolution_controller=controller,
    )
    blocked = agent.blocked_strategy_signatures
    assert blocked == ()

    client = FakeModelClient(
        [
            json.dumps(
                {
                    "strategy_pair": "sync:coordinated_linear_transport",
                    "motion_objective": "forward",
                    "reason": "explore a remaining coordination primitive",
                }
            )
        ]
    )
    selection = _select_evolution_subtask(
        client=client,
        payload={
            "task_stage": "full_scene",
            "current_policy": {
                "code": (
                    "def policy(api):\n"
                    "    api.coordinated_arc_transport("
                    'turn_direction="counterclockwise", angle_deg=15, '
                    "duration_s=4.0, radius_m=0.8)\n"
                    "    api.stop_all()"
                )
            },
            "evaluation": {
                "success": False,
                "failure_type": "payload_drop",
                "metrics": {"payload_target_progress_m": 0.0},
            },
            "evolution_controller": {
                "action": "switch_strategy",
                "repair_level": "strategy",
            },
            "observation": {"runtime_state": {}},
            "coordination_primitive_sdk": "enabled",
        },
        forbidden_methods=(),
        blocked_strategy_signatures=blocked,
    )

    assert selection["selected_method"] == "coordinated_linear_transport"
    context = json.loads(client.prompts[0]["user"].rsplit("\n\n", 1)[1])
    assert "async:coordinated_alignment" in context["allowed_strategy_pairs"]


