def test_load_trusted_checkpoint_linear_motion_and_reuse_envelope(tmp_path):
    attempt_dir = tmp_path / "attempt_47"
    attempt_dir.mkdir()
    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport(direction='backward', distance_m=1.0, "
        "speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    (attempt_dir / "evaluation.json").write_text(
        json.dumps({"success": True, "failure_type": "none"}),
        encoding="utf-8",
    )
    (attempt_dir / "evolution_record.json").write_text(
        json.dumps({"checkpoint_after": "accepted_step_13"}),
        encoding="utf-8",
    )
    (attempt_dir / "policy.json").write_text(
        json.dumps(
            {
                "script_id": "box_carry_attempt_47",
                "attempt": 47,
                "code": code,
                "robot_scripts": [
                    {
                        "robot_id": robot_id,
                        "script_id": f"{robot_id}_box_carry_attempt_47",
                        "code": code,
                        "synchronization_group": "coordination_group_47",
                        "coordination_mode": "sync",
                    }
                    for robot_id in ("front", "back")
                ],
            }
        ),
        encoding="utf-8",
    )

    motion = _load_trusted_checkpoint_linear_motion(
        tmp_path,
        checkpoint_id="accepted_step_13",
    )
    constraint = _trusted_checkpoint_linear_continuation_constraint(
        {"trusted_checkpoint_linear_motion": motion},
        selected_subtask={
            "selected_method": "coordinated_linear_transport",
            "coordination_mode": "sync",
            "motion_objective": "backward",
        },
    )

    assert motion["direction"] == "backward"
    assert motion["source_script_id"] == "box_carry_attempt_47"
    assert constraint["maximum_distance_m"] == 1.0
    assert constraint["required_speed_mps"] == 0.5
    assert constraint["required_ramp_s"] == 1.5


