def test_sync_compensation_retries_compiler_rejected_transaction():
    responses = [
        json.dumps(
            {
                "front_distance_m": 0.075,
                "back_distance_m": 0.075,
                "front_speed_mps": 0.25,
                "back_speed_mps": back_speed,
                "reason": "choose a distinct measured compensation",
            }
        )
        for back_speed in (0.20, 0.21)
    ]
    validated_speeds: list[float] = []

    def validate(candidate: dict[str, object]) -> None:
        back_speed = float(candidate["back_speed_mps"])
        validated_speeds.append(back_speed)
        if back_speed == pytest.approx(0.20):
            raise ModelAgentError(
                "structured measured-sync parameters repeat a rejected transaction"
            )

    selected = _select_sync_compensation_parameters(
        client=FakeModelClient(responses),
        constraint={
            "method": "carry_forward",
            "farther_robot": "back",
            "nearer_robot": "front",
            "farther_displacement_m": 0.19,
            "nearer_displacement_m": 0.05,
            "minimum_distance_m": 0.05,
            "maximum_distance_m": 0.075,
            "minimum_speed_mps": 0.15,
            "maximum_speed_mps": 0.25,
            "required_speed_mps": 0.25,
            "required_distance_m": 0.075,
            "maximum_pair_speed_delta_mps": 0.05,
        },
        candidate_validator=validate,
    )

    assert validated_speeds == pytest.approx([0.20, 0.21])
    assert selected["back_speed_mps"] == pytest.approx(0.21)


