def test_coordination_validation_accepts_verified_measured_sync_compensation():
    equal_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.20, speed_mps=0.25, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    compensated_front = equal_code
    compensated_back = equal_code.replace("speed_mps=0.25", "speed_mps=0.20")
    previous = PolicyScript(
        script_id="equal_sync",
        attempt=1,
        code=equal_code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_equal_sync",
                code=equal_code,
                synchronization_group="carry_team",
                contact_intent="maintain_payload_support",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )
    candidate = PolicyScript(
        script_id="compensated_sync",
        attempt=2,
        code=compensated_front,
        robot_scripts=(
            RobotPolicyScript(
                robot_id="front",
                script_id="front_compensated_sync",
                code=compensated_front,
                synchronization_group="carry_team",
                coordination_mode="sync",
            ),
            RobotPolicyScript(
                robot_id="back",
                script_id="back_compensated_sync",
                code=compensated_back,
                synchronization_group="carry_team",
                coordination_mode="sync",
            ),
        ),
    )

    _validate_failure_level_repair(
        previous,
        candidate,
        failure_level="coordination",
        failure_type="formation_desync",
        blocked_strategy_signatures=set(),
        allow_measured_sync_compensation=True,
    )

    _validate_failure_level_repair(
        previous,
        candidate,
        failure_level="execution",
        failure_type="formation_desync",
        blocked_strategy_signatures=set(),
        allow_measured_sync_compensation=True,
    )


