def test_qwen_vl_visual_verifier_blocks_payload_drop(tmp_path):
    frame = tmp_path / "frame.jpg"
    frame.write_bytes(b"fake-image-bytes-for-fake-client")
    client = FakeVisionClient(
        json.dumps(
            {
                "summary": "The long box is visibly below the support pose.",
                "scene_visible": True,
                "payload_on_floor": True,
                "robots_standing_stably": True,
                "wall_collision_or_stuck": False,
                "payload_placed_on_target": False,
                "visible_evidence": ["The cyan box rests on the floor."],
                "failure_type": "payload_drop",
                "confidence": 0.9,
            }
        )
    )

    report = QwenVLBoxCarryVisualVerifier(client=client).evaluate(
        task=BoxCarryTask(task_id="stage1", target="carry box"),
        trace=ExecutionTrace(
            script_id="box_carry_attempt_01", attempt=1, status="success"
        ),
        visual=VisualObservation(source="test", frame_path=str(frame)),
        before_state={"payload": {"x": 1.0, "y": 1.0}},
        runtime_state={"payload": {"x": 0.9, "y": 1.2}},
    )

    assert report.blocks_success
    assert report.failure_type == "payload_drop"
    assert report.evidence["payload_dropped"] is True
    assert report.evidence["payload_on_floor"] is True
    assert report.evidence["robots_standing_stably"] is True
    assert report.evidence["wall_collision_or_stuck"] is False
    assert report.recommendations == ()
    assert client.calls
    assert client.calls[0]["system"] == VISUAL_EVALUATOR_SYSTEM_PROMPT
    assert "orange-red cylindrical pedestal" in client.calls[0]["user"]
    assert "payload_on_floor" in client.calls[0]["user"]
    assert "runtime_state_hint" not in client.calls[0]["user"]
    assert "payload_target_progress_m" not in client.calls[0]["user"]
    assert "route_direction_risk" not in client.calls[0]["user"]


