def test_qwen_vl_rechecks_non_aligned_posture_when_robot_headings_agree(tmp_path):
    frame = tmp_path / "frame.jpg"
    frame.write_bytes(b"fake-image-bytes-for-fake-client")

    class SequencedVisionClient:
        def __init__(self):
            self.calls = []
            self.responses = [
                json.dumps(
                    {
                        "summary": "The team is at a visible corridor corner.",
                        "payload_on_arms": True,
                        "both_robots_supporting_payload": True,
                        "payload_dropped": False,
                        "payload_wall_contact_or_high_risk": False,
                        "robot_fallen_or_unstable": False,
                        "team_payload_posture_relative_to_visible_passage": "mixed",
                        "visible_free_space_connectivity": [
                            "one horizontal passage",
                            "one vertical passage",
                        ],
                        "payload_axis_relative_to_passage": "horizontal",
                        "failure_type": "none",
                        "confidence": 0.9,
                    }
                ),
                json.dumps(
                    {
                        "posture": "lateral_aligned",
                        "evidence": (
                            "The support and long-box axis follows the horizontal "
                            "connected passage."
                        ),
                    }
                ),
            ]

        def analyze_image(self, *, system, user, image_path):
            self.calls.append(
                {"system": system, "user": user, "image_path": str(image_path)}
            )
            return self.responses.pop(0)

    client = SequencedVisionClient()
    report = QwenVLBoxCarryVisualVerifier(client=client).evaluate(
        task=BoxCarryTask(task_id="corner", target="carry box"),
        trace=ExecutionTrace(script_id="pivot", attempt=4, status="success"),
        visual=VisualObservation(source="test", frame_path=str(frame)),
        runtime_state={
            "payload": {
                "active": True,
                "z": 1.0,
                "contacts": {
                    "support_robots": ["front", "back"],
                    "floor": False,
                    "walls": [],
                },
            },
            "robots": {
                "front": {"yaw_rad": -1.15},
                "back": {"yaw_rad": -1.23},
            },
        },
    )

    assert len(client.calls) == 2
    assert (
        report.evidence["team_payload_posture_relative_to_visible_passage"]
        == "lateral_aligned"
    )
    assert report.evidence["passage_posture_recheck"]["accepted"] is True
    assert report.evidence["passage_posture_recheck"]["original_posture"] == "mixed"


