def test_initial_visual_cache_key_tracks_physical_state_and_material_camera_change(
    tmp_path,
):
    from PIL import Image

    frame = tmp_path / "frame.png"
    Image.new("RGB", (64, 64), (20, 30, 40)).save(frame)
    state = {
        "checkpoint": {"checkpoint_id": "accepted_step_33"},
        "payload": {
            "active": True,
            "x": 1.2341,
            "y": 2.3451,
            "z": 0.981,
            "yaw_deg": 90.0,
            "tilt_deg": 0.2,
            "contacts": {
                "support_robots": ["front", "back"],
                "support_geometries": ["front_left", "back_left"],
                "floor": False,
                "walls": [],
            },
        },
        "robots": {
            "front": {"x": 1.0, "y": 2.0, "yaw_deg": 0.0, "pelvis_height_m": 0.79},
            "back": {"x": 1.0, "y": 3.0, "yaw_deg": 0.0, "pelvis_height_m": 0.79},
        },
    }
    task = BoxCarryTask(
        task_id="stage3", target="reach active target", task_stage="stage3_right"
    )

    first = _initial_visual_cache_key(
        task=task, runtime_state=state, frame_path=str(frame)
    )
    state["payload"]["x"] = 1.2342
    equivalent = _initial_visual_cache_key(
        task=task, runtime_state=state, frame_path=str(frame)
    )
    Image.new("RGB", (64, 64), (220, 230, 240)).save(frame)
    changed_view = _initial_visual_cache_key(
        task=task, runtime_state=state, frame_path=str(frame)
    )

    assert first == equivalent
    assert changed_view != equivalent


def test_cap_policy_executor_uses_safe_static_skill_sdk(tmp_path):
    policy = TaskOrchestrator(default_transport_distance_m=0.4).generate_initial_policy(
        BoxCarryTask(task_id="test", target="carry box"),
        ObservationBundle(),
    )
    runtime_state = tmp_path / "live" / "runtime_state.json"
    api = G1SkillAPI(
        backend=StaticSonicSkillBackend(execute=False),
        output_dir=tmp_path / "skills",
        heartbeat_file=tmp_path / "planner_heartbeat.json",
        runtime_state_file=runtime_state,
    )
    trace = PolicyExecutor(tmp_path / "attempt").execute(policy, api)

    assert trace.status == "success"
    assert [item.skill_name for item in trace.skill_calls] == [
        "place_payload_on_arms",
        "carry_lateral_left",
        "stop_all",
    ]
    command_files = sorted((tmp_path / "skills").glob("**/*_command.sh"))
    assert command_files
    first_command = command_files[0].read_text(encoding="utf-8")
    assert "validate_static_sonic_skill.py" in first_command
    assert f"--runtime-state-file {runtime_state}" in first_command
    stop_command = next(
        path for path in command_files if "stop_all" in path.name
    ).read_text(encoding="utf-8")
    assert "run_dual_official_sonic_motor_preflight.py" in stop_command
    assert "--walk-meters 0" in stop_command
    assert "--stand-seconds 1.0" in stop_command
    assert "validate_static_sonic_skill.py" not in stop_command


def test_formal_carry_forward_uses_verified_short_payload_envelope(tmp_path):
    backend = StaticSonicSkillBackend(execute=False)
    command = backend._command(
        "carry_forward",
        {"distance_m": 0.05, "speed_mps": 0.25, "transport_ramp_seconds": 0.5},
        tmp_path / "skill",
        tmp_path / "planner_heartbeat.json",
        tmp_path / "runtime_state.json",
    )

    front_index = command.index("--front-speed-mps") + 1
    back_index = command.index("--back-speed-mps") + 1
    assert float(command[front_index]) == pytest.approx(0.25)
    assert float(command[back_index]) == pytest.approx(0.25)
    duration_index = command.index("--minimum-motion-duration-s") + 1
    assert float(command[duration_index]) == pytest.approx(1.0)
    ramp_index = command.index("--transport-ramp-seconds") + 1
    assert float(command[ramp_index]) == pytest.approx(1.5)
    idle_index = command.index("--post-skill-idle-seconds") + 1
    assert float(command[idle_index]) == pytest.approx(1.0)
    profile_index = command.index("--payload-safety-profile") + 1
    assert command[profile_index] == "task"
    assert "--payload-safety-max-support-center-error-m" not in command


def test_agent_default_transport_matches_manual_four_second_move(tmp_path):
    backend = StaticSonicSkillBackend(execute=False)
    command = backend._command(
        "carry_forward",
        {"distance_m": 2.0, "speed_mps": 0.50, "transport_ramp_seconds": 1.5},
        tmp_path / "skill",
        tmp_path / "planner_heartbeat.json",
        tmp_path / "runtime_state.json",
    )

    assert float(command[command.index("--front-speed-mps") + 1]) == pytest.approx(0.50)
    assert float(command[command.index("--back-speed-mps") + 1]) == pytest.approx(0.50)
    assert float(
        command[command.index("--minimum-motion-duration-s") + 1]
    ) == pytest.approx(1.0)
    stream = build_static_sonic_skill_stream(
        SonicStaticSkillBuildConfig(
            skill_name="carry_forward",
            robot_ids=("front", "back"),
            distance_m=2.0,
            speed_mps=0.50,
            transport_ramp_seconds=1.5,
            minimum_motion_duration_s=1.0,
        )
    )
    move_commands = [
        item for item in stream.commands if item.phase_id.endswith(".move")
    ]
    assert {item.speed for item in move_commands} == {0.50}
    assert {item.duration_s for item in move_commands} == {4.0}


def test_formal_loaded_turn_uses_experiment_payload_support_limit(tmp_path):
    backend = StaticSonicSkillBackend(
        execute=False,
        max_payload_support_center_error_m=0.10,
    )
    command = backend._command(
        "carry_turn_in_place",
        {"yaw_deg": 90.0, "yaw_rate_degps": 5.0, "turn_segment_deg": 3.0},
        tmp_path / "skill",
        tmp_path / "planner_heartbeat.json",
        tmp_path / "runtime_state.json",
    )

    support_error_index = (
        command.index("--payload-safety-max-support-center-error-m") + 1
    )
    assert float(command[support_error_index]) == pytest.approx(0.10)
    assert command[command.index("--payload-safety-profile") + 1] == "task"
    assert "--payload-support-min-force-n" not in command
    assert "--payload-support-min-balance-ratio" not in command


