def test_payload_runtime_status_requires_live_clean_dual_support(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    runtime_state.write_text(
        json.dumps(
            {
                "runtime_status": "running",
                "runtime_fault": {},
                "control_health": {
                    "healthy": True,
                    "streams": {
                        "front": {"received": True, "fresh": True},
                        "back": {"received": True, "fresh": True},
                    },
                },
                "checkpoint": {"resync_active": False},
                "elastic_band_dropped": True,
                "payload": {
                    "present": True,
                    "active": True,
                    "x": -1.46,
                    "y": 2.33,
                    "z": 1.02,
                    "tilt_deg": 1.0,
                    "top_surface_corner_z_range_m": 0.02,
                    "linear_speed_mps": 0.0,
                    "angular_speed_radps": 0.0,
                    "live_support_target": {
                        "ready": True,
                        "wait_reasons": [],
                        "x": -1.46,
                        "y": 2.33,
                    },
                    "contacts": {
                        "robots": ["front", "back"],
                        "support_robots": ["front", "back"],
                        "support_geometries": [
                            "front_left_carry_support_plate",
                            "back_left_carry_support_plate",
                        ],
                        "floor": False,
                        "walls": [],
                    },
                },
                "robots": {
                    "front": {"x": 0.0, "y": 0.0, "pelvis_height_m": 0.79},
                    "back": {"x": 0.0, "y": 0.84, "pelvis_height_m": 0.79},
                },
            }
        ),
        encoding="utf-8",
    )

    status = read_payload_runtime_status(runtime_state, max_age_s=1.0)
    assert status.ready_to_place()
    assert status.payload_supported()
    assert status.robot_xy_separation_available
    assert status.robot_xy_separation_m == pytest.approx(0.84)

    payload = json.loads(runtime_state.read_text(encoding="utf-8"))
    payload["robots"]["back"]["y"] = 0.45
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    too_close = read_payload_runtime_status(runtime_state)
    assert too_close.robot_xy_separation_m == pytest.approx(0.45)
    assert not too_close.payload_supported()
    payload["robots"]["back"]["y"] = 0.84
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")

    with pytest.raises(RuntimeError, match="initialization gate"):
        wait_for_payload_initialization_ready(
            runtime_state,
            timeout_s=0.0,
            stable_s=0.0,
            max_age_s=1.0,
            require_all_support_pads=True,
        )

    payload = json.loads(runtime_state.read_text(encoding="utf-8"))
    payload["control_health"]["healthy"] = False
    payload["control_health"]["streams"]["back"]["fresh"] = False
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    stale_status = read_payload_runtime_status(runtime_state)
    assert not stale_status.ready_to_place()
    assert not stale_status.payload_supported()

    payload["control_health"]["healthy"] = True
    payload["control_health"]["streams"]["back"]["fresh"] = True
    payload["checkpoint"]["resync_active"] = True
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    resync_status = read_payload_runtime_status(runtime_state)
    assert not resync_status.ready_to_place()
    assert not resync_status.payload_supported()

    payload["checkpoint"]["resync_active"] = False
    payload["payload"]["contacts"]["walls"] = ["wall_01"]
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    assert read_payload_runtime_status(runtime_state).payload_supported()
    assert not read_payload_runtime_status(runtime_state).payload_supported(
        safety_profile="strict"
    )

    payload["payload"]["contacts"]["walls"] = []
    payload["payload"]["tilt_deg"] = 12.0
    payload["payload"]["top_surface_corner_z_range_m"] = 0.20
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    assert read_payload_runtime_status(runtime_state).payload_supported()
    assert read_payload_runtime_status(runtime_state).payload_supported(
        max_tilt_deg=5.0,
        max_top_surface_z_range_m=0.08,
    )
    assert not read_payload_runtime_status(runtime_state).payload_supported(
        max_tilt_deg=5.0,
        max_top_surface_z_range_m=0.08,
        safety_profile="strict",
    )

    payload["payload"]["tilt_deg"] = 1.0
    payload["payload"]["top_surface_corner_z_range_m"] = 0.02
    payload["payload"]["linear_speed_mps"] = 0.08
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    assert not read_payload_runtime_status(runtime_state).payload_supported()

    payload["payload"]["linear_speed_mps"] = 0.0
    payload["payload"]["x"] = -1.40
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")
    offset_status = read_payload_runtime_status(runtime_state)
    assert offset_status.support_center_xy_error_m == pytest.approx(0.06)
    assert offset_status.payload_supported()
    assert not offset_status.payload_supported(
        max_support_center_xy_error_m=0.05,
        support_center_is_hard_failure=True,
    )
    relaxed_status = wait_for_payload_supported(
        runtime_state,
        timeout_s=0.0,
        stable_s=0.0,
        max_age_s=1.0,
        max_support_center_xy_error_m=0.08,
    )
    assert relaxed_status.payload_supported(max_support_center_xy_error_m=0.08)
    resumed_status = wait_for_payload_initialization_ready(
        runtime_state,
        timeout_s=0.0,
        stable_s=0.0,
        max_age_s=1.0,
        max_support_center_xy_error_m=0.08,
    )
    assert resumed_status.payload_supported(max_support_center_xy_error_m=0.08)


def test_payload_inward_recovery_gate_requires_pose_support_and_outward_slip(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    state = _relaxed_supported_runtime_state()
    state["checkpoint"] = {"resync_active": False}
    recovery_threshold = TASK_CARRY_SAFETY.warning_payload_formation_slip_m
    ready_offset = recovery_threshold + 0.01
    state["payload"]["support_center_signed_longitudinal_offset_m"] = ready_offset
    state["upper_body_pose_lock"] = {
        "configured": True,
        "pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "target_pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "transition_active": False,
    }
    runtime_state.write_text(json.dumps(state), encoding="utf-8")

    ready = wait_for_payload_recovery_ready(
        runtime_state,
        timeout_s=0.0,
        stable_s=0.0,
        max_age_s=1.0,
    )
    assert ready["payload"][
        "support_center_signed_longitudinal_offset_m"
    ] == pytest.approx(ready_offset)

    state["payload"]["support_center_signed_longitudinal_offset_m"] = (
        recovery_threshold - 0.01
    )
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    with pytest.raises(RuntimeError, match="has not reached either preventive"):
        wait_for_payload_recovery_ready(
            runtime_state,
            timeout_s=0.0,
            stable_s=0.0,
            max_age_s=1.0,
        )

    state["payload"]["tilt_deg"] = PAYLOAD_RECOVERY_TILT_TRIGGER_DEG + 1.0
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    tilt_ready = wait_for_payload_recovery_ready(
        runtime_state,
        timeout_s=0.0,
        stable_s=0.0,
        max_age_s=1.0,
    )
    assert tilt_ready["payload"]["tilt_deg"] == pytest.approx(
        PAYLOAD_RECOVERY_TILT_TRIGGER_DEG + 1.0
    )

    state["payload"]["support_center_signed_longitudinal_offset_m"] = ready_offset
    state["payload"]["tilt_deg"] = 0.0
    state["upper_body_pose_lock"]["pose_name"] = PAYLOAD_RECOVERY_POSE_NAME
    state["upper_body_pose_lock"]["target_pose_name"] = PAYLOAD_RECOVERY_POSE_NAME
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    with pytest.raises(RuntimeError, match="already complete"):
        wait_for_payload_recovery_ready(
            runtime_state,
            timeout_s=0.0,
            stable_s=0.0,
            max_age_s=1.0,
        )


def test_billing_reconciliation_supports_legacy_no_argument_client():
    calls = []

    def reconcile():
        calls.append(True)
        return {"status": "complete", "remaining": 0}

    assert _call_billing_reconcile_bounded(reconcile, 0.5) == {
        "status": "complete",
        "remaining": 0,
    }
    assert calls == [True]


def test_billing_reconciliation_uses_deferred_multi_round_contract():
    captured = {}

    def reconcile(
        *,
        max_rounds,
        initial_backoff_s,
        per_request_delay_s,
        total_timeout_s,
        lookup_timeout_s,
    ):
        captured.update(
            {
                "max_rounds": max_rounds,
                "initial_backoff_s": initial_backoff_s,
                "per_request_delay_s": per_request_delay_s,
                "total_timeout_s": total_timeout_s,
                "lookup_timeout_s": lookup_timeout_s,
            }
        )
        return {"status": "complete", "remaining": 0}

    assert _call_billing_reconcile_bounded(reconcile, 0.5) == {
        "status": "complete",
        "remaining": 0,
    }
    assert captured == {
        "max_rounds": 3,
        "initial_backoff_s": 2.0,
        "per_request_delay_s": 0.05,
        "total_timeout_s": 0.5,
        "lookup_timeout_s": 0.5,
    }


def test_billing_reconciliation_bounds_legacy_client_wall_clock():
    def reconcile():
        time.sleep(0.5)

    started = time.monotonic()
    with pytest.raises(TimeoutError, match="terminal deadline"):
        _call_billing_reconcile_bounded(reconcile, 0.05)
    assert time.monotonic() - started < 0.3


def test_payload_recovery_gate_retains_restored_checkpoint_slip_evidence(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    state = _relaxed_supported_runtime_state()
    recovery_threshold = TASK_CARRY_SAFETY.warning_payload_formation_slip_m
    state["payload"]["support_center_signed_longitudinal_offset_m"] = (
        recovery_threshold - 0.01
    )
    state["upper_body_pose_lock"] = {
        "configured": True,
        "pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "target_pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "transition_active": False,
    }
    state["checkpoint"] = {
        "action": "restore",
        "checkpoint_id": "accepted_step_46",
        "success": True,
        "resync_active": False,
        "reference_pose": {
            "payload": {
                "support_center_signed_longitudinal_offset_m": (
                    recovery_threshold + 0.01
                )
            }
        },
    }
    runtime_state.write_text(json.dumps(state), encoding="utf-8")

    ready = wait_for_payload_recovery_ready(
        runtime_state,
        timeout_s=0.0,
        stable_s=0.0,
        max_age_s=1.0,
    )
    assert ready["checkpoint"]["checkpoint_id"] == "accepted_step_46"

    summary = compact_runtime_state(state)
    assert summary["payload_inward_recovery"]["available"]
    assert summary["payload_inward_recovery"][
        "current_body_forward_offset_m"
    ] == pytest.approx(recovery_threshold - 0.01)
    assert summary["payload_inward_recovery"][
        "measured_body_forward_offset_m"
    ] == pytest.approx(recovery_threshold + 0.01)


def test_payload_recovery_rejects_large_support_center_displacement(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    state = _relaxed_supported_runtime_state()
    recovery_threshold = TASK_CARRY_SAFETY.warning_payload_formation_slip_m
    state["payload"]["support_center_signed_longitudinal_offset_m"] = (
        recovery_threshold + 0.01
    )
    state["payload"]["x"] = (
        state["payload"]["live_support_target"]["x"]
        + TASK_CARRY_SAFETY.max_support_center_error_m
        + 0.01
    )
    state["upper_body_pose_lock"] = {
        "configured": True,
        "pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "target_pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "transition_active": False,
    }
    state["checkpoint"] = {"resync_active": False}
    runtime_state.write_text(json.dumps(state), encoding="utf-8")

    with pytest.raises(RuntimeError, match="outside the arm-recovery support envelope"):
        wait_for_payload_recovery_ready(
            runtime_state,
            timeout_s=0.0,
            stable_s=0.0,
            max_age_s=1.0,
        )
    assert not compact_runtime_state(state)["payload_inward_recovery"]["available"]


