def test_model_runtime_summary_exposes_only_guarded_payload_inward_recovery():
    state = {
        "runtime_status": "running",
        "control_health": {"healthy": True},
        "checkpoint": {"resync_active": False},
        "payload": {
            "active": True,
            "x": 0.20,
            "y": 0.0,
            "live_support_target": {"x": 0.0, "y": 0.0},
            "support_center_signed_longitudinal_offset_m": 0.20,
            "support_center_signed_lateral_offset_m": -0.01,
            "support_offset_convention": "positive longitudinal is body-forward/outward",
            "contacts": {
                "support_robots": ["front", "back"],
                "floor": False,
            },
        },
        "upper_body_pose_lock": {
            "configured": True,
            "pose_name": DEFAULT_CARRY_READY_POSE_NAME,
            "target_pose_name": DEFAULT_CARRY_READY_POSE_NAME,
            "transition_active": False,
        },
    }

    summary = compact_runtime_state(state)

    assert summary["payload"][
        "support_center_signed_longitudinal_offset_m"
    ] == pytest.approx(0.20)
    assert summary["payload"][
        "support_center_signed_lateral_offset_m"
    ] == pytest.approx(-0.01)
    assert summary["upper_body_pose_lock"]["pose_name"] == DEFAULT_CARRY_READY_POSE_NAME
    assert summary["payload_inward_recovery"]["available"]
    assert summary["payload_inward_recovery"][
        "minimum_body_forward_offset_m"
    ] == pytest.approx(TASK_CARRY_SAFETY.warning_payload_formation_slip_m)
    assert summary["payload_inward_recovery"]["coordination_mode"] == "sync_only"
    required_method, required_example, _reason = _required_evolution_call(
        {"observation": {"runtime_state": summary}}
    )
    assert required_method == "recover_payload_inward"
    assert required_example == "recover_payload_inward(ramp_s=3, hold_s=2)"

    state["payload"]["support_center_signed_longitudinal_offset_m"] = 0.0
    state["payload"]["tilt_deg"] = PAYLOAD_RECOVERY_TILT_TRIGGER_DEG + 1.0
    tilt_summary = compact_runtime_state(state)
    assert tilt_summary["payload_inward_recovery"]["available"]
    assert tilt_summary["payload_inward_recovery"]["trigger_reasons"] == [
        "high_tilt_before_overturn"
    ]

    state["upper_body_pose_lock"]["pose_name"] = PAYLOAD_RECOVERY_POSE_NAME
    state["upper_body_pose_lock"]["target_pose_name"] = PAYLOAD_RECOVERY_POSE_NAME
    assert not compact_runtime_state(state)["payload_inward_recovery"]["available"]


def test_task_post_action_gate_accepts_current_settled_dual_upper_limb_support(
    monkeypatch,
    tmp_path,
):
    moving_with_four_palm_support = PayloadRuntimeStatus(
        available=True,
        fresh=True,
        elastic_band_dropped=True,
        present=True,
        active=True,
        support_center_xy_error_available=True,
        support_center_xy_error_m=0.02,
        z=0.98,
        tilt_deg=0.2,
        top_surface_corner_z_range_m=0.01,
        linear_speed_mps=0.022,
        angular_speed_radps=0.061,
        supporting_robots=frozenset({"front", "back"}),
        supporting_geometries=frozenset(
            {
                "front_left_carry_support_plate",
                "front_right_carry_support_plate",
                "back_left_carry_support_plate",
                "back_right_carry_support_plate",
            }
        ),
        non_support_robot_contacts=(
            "back_torso_link",
            "front_right_shoulder_yaw_link",
        ),
        min_robot_pelvis_height_m=0.79,
        robot_xy_separation_available=True,
        robot_xy_separation_m=0.84,
        control_healthy=True,
        runtime_status="running",
    )
    monkeypatch.setattr(
        runtime_state_module,
        "read_payload_runtime_status",
        lambda *_args, **_kwargs: moving_with_four_palm_support,
    )

    result = observe_payload_carry_stability(
        tmp_path / "runtime_state.json",
        timeout_s=0.0,
        stable_s=0.0,
        contact_loss_grace_s=0.0,
    )

    assert result["success"]
    assert result["failure_type"] == "none"
    assert moving_with_four_palm_support.payload_supported(
        allow_non_support_robot_contacts=True,
        safety_profile="task",
    )
    assert not moving_with_four_palm_support.payload_supported(
        safety_profile="strict",
    )

    strict_result = observe_payload_carry_stability(
        tmp_path / "runtime_state.json",
        timeout_s=0.0,
        stable_s=0.0,
        contact_loss_grace_s=0.0,
        safety_profile="strict",
    )

    assert not strict_result["success"]


def test_payload_initialization_requires_real_support_margin_and_primary_support():
    stable = PayloadRuntimeStatus(
        available=True,
        fresh=True,
        elastic_band_dropped=True,
        present=True,
        active=True,
        support_center_xy_error_available=True,
        support_center_xy_error_m=0.01,
        z=1.0,
        tilt_deg=1.0,
        top_surface_corner_z_range_m=0.02,
        linear_speed_mps=0.0,
        angular_speed_radps=0.0,
        supporting_robots=frozenset({"front", "back"}),
        support_polygon_available=True,
        support_polygon_com_margin_m=0.03,
        robot_xy_separation_available=True,
        robot_xy_separation_m=0.84,
        control_healthy=True,
    )

    assert stable.payload_supported(min_support_polygon_com_margin_m=0.02)
    assert not replace(
        stable,
        support_polygon_com_margin_m=0.01,
    ).payload_supported(min_support_polygon_com_margin_m=0.02)
    assert not replace(
        stable,
        non_support_robot_contacts=("front_torso_collision",),
    ).payload_supported(min_support_polygon_com_margin_m=0.02)
    assert replace(
        stable,
        non_support_robot_contacts=("front_torso_collision",),
    ).payload_supported(
        min_support_polygon_com_margin_m=0.02,
        allow_non_support_robot_contacts=True,
        safety_profile="task",
    )


def test_task_post_action_gate_honors_continuous_stability_duration(
    monkeypatch,
    tmp_path,
):
    settled = PayloadRuntimeStatus(
        available=True,
        fresh=True,
        elastic_band_dropped=True,
        present=True,
        active=True,
        support_center_xy_error_available=True,
        support_center_xy_error_m=0.02,
        z=0.98,
        tilt_deg=0.2,
        top_surface_corner_z_range_m=0.01,
        linear_speed_mps=0.0,
        angular_speed_radps=0.0,
        supporting_robots=frozenset({"front", "back"}),
        supporting_geometries=frozenset(
            {
                "front_left_carry_support_plate",
                "front_right_carry_support_plate",
                "back_left_carry_support_plate",
                "back_right_carry_support_plate",
            }
        ),
        min_robot_pelvis_height_m=0.79,
        robot_xy_separation_available=True,
        robot_xy_separation_m=0.84,
        control_healthy=True,
        runtime_status="running",
    )
    clock = {"now": 0.0}
    monkeypatch.setattr(
        runtime_state_module,
        "read_payload_runtime_status",
        lambda *_args, **_kwargs: settled,
    )
    monkeypatch.setattr(
        runtime_state_module.time,
        "monotonic",
        lambda: clock["now"],
    )
    monkeypatch.setattr(
        runtime_state_module.time,
        "sleep",
        lambda duration: clock.__setitem__("now", clock["now"] + duration),
    )

    result = observe_payload_carry_stability(
        tmp_path / "runtime_state.json",
        timeout_s=2.0,
        stable_s=1.0,
        poll_s=0.1,
        safety_profile="task",
    )

    assert result["success"]
    assert result["stable_duration_s"] >= 1.0
    assert result["sample_count"] >= 11

    clock["now"] = 0.0
    restored = wait_for_payload_supported(
        tmp_path / "runtime_state.json",
        timeout_s=2.0,
        stable_s=1.0,
        poll_s=0.1,
        safety_profile="task",
    )
    assert restored is settled
    assert clock["now"] >= 1.0


