def test_box_carry_evaluator_success_and_wall_contact(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    runtime_state.write_text(
        json.dumps(
            {
                "payload": {
                    "active": True,
                    "x": 1.0,
                    "y": 2.0,
                    "z": 1.05,
                    "contacts": {
                        "robots": ["front", "back"],
                        "support_robots": ["front", "back"],
                        "support_geometries": [
                            "front_left_carry_support_plate",
                            "back_left_carry_support_plate",
                        ],
                        "walls": [],
                        "floor": False,
                    },
                },
                "robots": {
                    "front": {
                        "x": 1.0,
                        "y": 0.0,
                        "initial_x": 0.0,
                        "initial_y": 0.0,
                        "pelvis_height_m": 0.7,
                    },
                    "back": {
                        "x": 1.0,
                        "y": 0.84,
                        "initial_x": 0.0,
                        "initial_y": 0.84,
                        "pelvis_height_m": 0.7,
                    },
                },
            }
        ),
        encoding="utf-8",
    )
    trace = PolicyExecutor(tmp_path / "attempt").execute(
        PolicyScript(
            script_id="ok", attempt=1, code="def policy(api):\n    api.stop_all()\n"
        ),
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )
    task = BoxCarryTask(
        task_id="test",
        target="carry",
        require_payload_on_target=False,
        require_robots_exit=False,
    )

    report = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert report.success

    payload = json.loads(runtime_state.read_text(encoding="utf-8"))
    payload["payload"]["contacts"]["walls"] = ["wall_01"]
    runtime_state.write_text(json.dumps(payload), encoding="utf-8")

    wall_report = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert wall_report.success
    assert wall_report.evidence["physical_quality_warnings"][0]["type"] == (
        "payload_wall_contact"
    )
    strict_wall_report = BoxCarryEvaluator(
        runtime_state,
        safety_profile="strict",
    ).evaluate(task=task, trace=trace)
    assert not strict_wall_report.success
    assert strict_wall_report.failure_type == "payload_wall_contact"


def test_stepwise_evaluator_requires_completed_dual_support_payload_recovery(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = _relaxed_supported_runtime_state()
    before["payload"].update(
        {
            "z": 1.0,
            "tilt_deg": 4.0,
            "support_center_signed_longitudinal_offset_m": 0.21,
        }
    )
    before["payload"]["contacts"].update({"walls": [], "floor": False})
    before["upper_body_pose_lock"] = {
        "configured": True,
        "pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "target_pose_name": DEFAULT_CARRY_READY_POSE_NAME,
        "transition_active": False,
        "waist_and_legs_unchanged_by_runtime_events": True,
        "last_event": {},
    }
    after = json.loads(json.dumps(before))
    after["payload"]["support_center_signed_longitudinal_offset_m"] = 0.14
    after["upper_body_pose_lock"].update(
        {
            "pose_name": PAYLOAD_RECOVERY_POSE_NAME,
            "target_pose_name": PAYLOAD_RECOVERY_POSE_NAME,
            "last_event": {
                "event": "recover_payload_inward",
                "event_id": "recover_001",
                "success": True,
                "completed": True,
            },
        }
    )
    runtime_state.write_text(json.dumps(after), encoding="utf-8")
    trace = ExecutionTrace(
        script_id="payload_recovery",
        attempt=1,
        status="success",
        skill_calls=(
            SkillCallRecord(
                index=1,
                skill_name="carry_recover_payload_inward",
                parameters={"recovery_ramp_seconds": 3.0, "recovery_hold_seconds": 2.0},
                status="success",
                started_at_unix=1.0,
                finished_at_unix=2.0,
                robot_ids=("front", "back"),
            ),
        ),
    )
    task = BoxCarryTask(
        task_id="payload_recovery",
        target="keep carrying",
        require_payload_on_target=False,
        require_robots_exit=False,
    )

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
        before_state=before,
        stepwise=True,
    )
    assert report.success
    assert report.evidence["payload_inward_recovery"]["pose_name"] == (
        PAYLOAD_RECOVERY_POSE_NAME
    )

    after["upper_body_pose_lock"]["last_event"]["completed"] = False
    runtime_state.write_text(json.dumps(after), encoding="utf-8")
    incomplete = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
        before_state=before,
        stepwise=True,
    )
    assert not incomplete.success
    assert incomplete.failure_type == "script_error"
    assert "recovery event is incomplete" in incomplete.recommendations[0]


