def test_box_carry_evaluator_completes_on_released_physical_target_support(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    state = {
        "payload": {
            "active": True,
            "released": True,
            "x": -1.5,
            "y": 7.6,
            "z": 0.65,
            "contacts": {
                "robots": [],
                "walls": [],
                "floor": False,
                "target": True,
            },
        },
        "robots": {
            "front": {
                "x": -3.0,
                "y": 7.6,
                "initial_x": -1.7,
                "initial_y": 2.0,
                "pelvis_height_m": 0.7,
            },
            "back": {
                "x": 0.0,
                "y": 7.6,
                "initial_x": -1.7,
                "initial_y": 2.8,
                "pelvis_height_m": 0.7,
            },
        },
    }
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    trace = PolicyExecutor(tmp_path / "attempt").execute(
        PolicyScript(
            script_id="ok", attempt=1, code="def policy(api):\n    api.stop_all()\n"
        ),
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )
    task = BoxCarryTask(task_id="final", target="place box on cylinder and leave")

    report = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert report.success
    assert report.metrics["payload_on_target"] == pytest.approx(1.0)
    assert report.metrics["robots_clear_after_place"] == pytest.approx(1.0)

    state["payload"]["contacts"]["target"] = False
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    no_physical_target_support = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
    )
    assert not no_physical_target_support.success
    assert no_physical_target_support.metrics["payload_on_target"] == pytest.approx(0.0)
    state["payload"]["contacts"]["target"] = True

    state["robots"]["front"]["x"] = -1.7
    state["robots"]["front"]["y"] = 7.6
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    not_clear = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert not_clear.success
    assert not_clear.metrics["payload_on_target"] == pytest.approx(1.0)

    optional_exit_task = replace(task, require_robots_exit=True)
    not_clear_ablation = BoxCarryEvaluator(runtime_state).evaluate(
        task=optional_exit_task,
        trace=trace,
    )
    assert not_clear_ablation.failure_type == "robots_not_clear"

    state["robots"]["front"]["x"] = -3.0
    state["payload"]["x"] = -1.0
    state["payload"]["z"] = 1.05
    state["payload"]["contacts"] = {
        "robots": ["front", "back"],
        "support_robots": ["front", "back"],
        "support_geometries": ["front_left", "back_left"],
        "walls": [],
        "floor": False,
        "target": False,
    }
    runtime_state.write_text(json.dumps(state), encoding="utf-8")
    off_target = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert off_target.failure_type == "payload_not_on_target"


def test_stepwise_exit_requires_measurable_robot_clearance_progress(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = {
        "payload": {
            "active": True,
            "released": True,
            "x": -1.5,
            "y": 7.6,
            "z": 0.65,
            "tilt_deg": 1.0,
            "contacts": {
                "robots": [],
                "support_robots": [],
                "walls": [],
                "floor": False,
                "target": True,
            },
        },
        "robots": {
            "front": {
                "x": -2.0,
                "y": 7.6,
                "pelvis_height_m": 0.60,
                "place_crouch": {"crouch": 1.0, "post_release_latched": True},
            },
            "back": {
                "x": -1.0,
                "y": 7.6,
                "pelvis_height_m": 0.60,
                "place_crouch": {"crouch": 1.0, "post_release_latched": True},
            },
        },
        "post_release_lifecycle": {
            "payload_released": True,
            "crouch_latched": True,
            "crouched_retreat_completed": False,
            "stand_recovered": False,
        },
    }
    policy = PolicyScript(
        script_id="exit_step",
        attempt=1,
        code=(
            "def policy(api):\n"
            "    api.exit_backward(distance_m=0.5, speed_mps=0.2, ramp_s=1.5)\n"
            "    api.stop_all()\n"
        ),
    )
    trace = PolicyExecutor(tmp_path / "attempt").execute(
        policy,
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )
    task = BoxCarryTask(
        task_id="exit",
        target="leave target",
        task_stage="full_scene",
        require_robots_exit=True,
    )

    runtime_state.write_text(json.dumps(before), encoding="utf-8")
    stationary = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
        before_state=before,
        stepwise=True,
    )
    assert stationary.failure_type == "robots_not_clear"

    after = json.loads(json.dumps(before))
    after["robots"]["front"]["x"] = -2.2
    after["robots"]["back"]["x"] = -0.8
    after["post_release_lifecycle"]["crouched_retreat_completed"] = True
    runtime_state.write_text(json.dumps(after), encoding="utf-8")
    progressing = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
        before_state=before,
        stepwise=True,
    )
    assert progressing.success
    assert progressing.metrics["robot_exit_progress_m"] == pytest.approx(0.2)

    small_progress = json.loads(json.dumps(before))
    small_progress["robots"]["front"]["x"] = -2.008
    small_progress["robots"]["back"]["x"] = -0.992
    small_progress["post_release_lifecycle"]["crouched_retreat_completed"] = True
    runtime_state.write_text(json.dumps(small_progress), encoding="utf-8")
    cumulative = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
        before_state=before,
        stepwise=True,
    )
    assert cumulative.success
    assert cumulative.metrics["robot_exit_progress_m"] == pytest.approx(0.008)


def test_formal_completion_requires_crouched_backward_exit_then_upright_recovery(
    tmp_path,
):
    runtime_state = tmp_path / "runtime_state.json"
    released = {
        "payload": {
            "active": True,
            # Regression for V32: stable physical target support was 0.226m
            # off-center, inside the 0.30m cylinder but outside the 0.18m
            # preferred alignment tolerance.
            "x": -1.719741275926257,
            "y": 7.654516396937293,
            "z": 0.65,
            "released": True,
            "contacts": {
                "robots": [],
                "support_robots": [],
                "support_geometries": [],
                "walls": [],
                "floor": False,
                "target": True,
            },
        },
        "robots": {
            "front": {
                "x": -2.0,
                "y": 7.6,
                "pelvis_height_m": 0.60,
                "place_crouch": {"crouch": 1.0, "post_release_latched": True},
            },
            "back": {
                "x": -1.0,
                "y": 7.6,
                "pelvis_height_m": 0.60,
                "place_crouch": {"crouch": 1.0, "post_release_latched": True},
            },
        },
        "post_release_lifecycle": {
            "payload_released": True,
            "crouch_latched": True,
            "crouched_retreat_completed": False,
            "stand_recovered": False,
        },
    }
    task = BoxCarryTask(
        task_id="formal_finalization",
        target="place, crouched retreat, and recover upright",
        task_stage="full_scene",
        require_robots_exit=True,
    )
    exit_trace = PolicyExecutor(tmp_path / "exit_attempt").execute(
        PolicyScript(
            script_id="crouched_exit",
            attempt=1,
            code=(
                "def policy(api):\n"
                "    api.exit_backward(distance_m=0.5, speed_mps=0.2, ramp_s=1.5)\n"
                "    api.stop_all()\n"
            ),
        ),
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "exit_skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )

    retreated = json.loads(json.dumps(released))
    retreated["robots"]["front"]["x"] = -2.8
    retreated["robots"]["back"]["x"] = -0.2
    retreated["post_release_lifecycle"]["crouched_retreat_completed"] = True
    runtime_state.write_text(json.dumps(retreated), encoding="utf-8")
    exit_report = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=exit_trace,
        before_state=released,
        stepwise=True,
    )
    assert exit_report.success
    assert exit_report.metrics["post_release_crouched_retreat_completed"] == 1.0
    assert exit_report.metrics["task_complete"] == 0.0

    recover_trace = PolicyExecutor(tmp_path / "recover_attempt").execute(
        PolicyScript(
            script_id="recover_upright",
            attempt=2,
            code=(
                "def policy(api):\n"
                "    api.recover_stand(height=0.8, ramp_s=6.0, hold_s=2.0)\n"
                "    api.stop_all()\n"
            ),
        ),
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "recover_skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )
    standing = json.loads(json.dumps(retreated))
    for robot in standing["robots"].values():
        robot["pelvis_height_m"] = 0.76
        robot["place_crouch"] = {}
    standing["post_release_lifecycle"].update(
        {
            "crouch_latched": False,
            "stand_recovered": True,
        }
    )
    runtime_state.write_text(json.dumps(standing), encoding="utf-8")
    complete = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=recover_trace,
        before_state=retreated,
        stepwise=True,
    )
