def test_payload_target_gate_separates_release_transition_from_final_state():
    state = {
        "control_health": {"healthy": True},
        "payload": {
            "active": True,
            "released": True,
            "x": -1.18,
            "y": 7.74,
            "z": 0.52,
            "linear_speed_mps": 0.0,
            "angular_speed_radps": 0.0,
            "contacts": {
                "robots": ["back"],
                "support_robots": ["back"],
                "walls": [],
                "floor": False,
                "target": True,
            },
        },
        "target": {
            "available": True,
            "center_x_m": -1.5,
            "center_y_m": 7.6,
            "payload_center_target_z_m": 0.65,
        },
        "robots": {
            "front": {"pelvis_height_m": 0.57},
            "back": {"pelvis_height_m": 0.57},
        },
    }

    transition_ok, transition_reason = runtime_state_module._payload_on_target(
        state,
        target_xy_tolerance_m=None,
        target_z_tolerance_m=None,
        require_released=True,
        allow_robot_contact=True,
    )
    final_ok, final_reason = runtime_state_module._payload_on_target(
        state,
        target_xy_tolerance_m=None,
        target_z_tolerance_m=None,
        require_released=True,
        allow_robot_contact=False,
    )

    assert transition_ok, transition_reason
    assert not final_ok
    assert final_reason == "robot contact remains after payload release"


def test_box_carry_evaluator_detects_missing_support_and_drop(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    base = {
        "payload": {
            "active": True,
            "x": 1.0,
            "y": 2.0,
            "z": 1.05,
            "contacts": {
                "robots": ["front"],
                "support_robots": ["front"],
                "support_geometries": ["front_left_carry_support_plate"],
                "walls": [],
                "floor": False,
            },
        },
        "robots": {
            "front": {
                "x": 1.0,
                "y": 0.0,
                "initial_x": 0.0,
                "initial_y": 0.0,
                "pelvis_height_m": 0.7,
            },
            "back": {
                "x": 1.0,
                "y": 0.84,
                "initial_x": 0.0,
                "initial_y": 0.84,
                "pelvis_height_m": 0.7,
            },
        },
    }
    runtime_state.write_text(json.dumps(base), encoding="utf-8")
    trace = PolicyExecutor(tmp_path / "attempt").execute(
        PolicyScript(
            script_id="ok", attempt=1, code="def policy(api):\n    api.stop_all()\n"
        ),
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )
    task = BoxCarryTask(
        task_id="test",
        target="carry",
        require_payload_on_target=False,
        require_robots_exit=False,
    )

    support_report = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert support_report.failure_type == "payload_not_supported"

    base["payload"]["contacts"]["robots"] = ["front", "back"]
    base["payload"]["contacts"]["support_robots"] = ["front", "back"]
    base["payload"]["contacts"]["support_geometries"] = [
        "front_left_carry_support_plate",
        "back_left_carry_support_plate",
    ]
    base["payload"]["z"] = 0.2
    runtime_state.write_text(json.dumps(base), encoding="utf-8")
    drop_report = BoxCarryEvaluator(runtime_state).evaluate(task=task, trace=trace)
    assert drop_report.failure_type == "payload_drop"


