def _pivot_execution_trace(
    turn_direction: str = "counterclockwise",
    *,
    angle_deg: float = 2.2,
) -> ExecutionTrace:
    actions = {
        robot_id: {
            "method": "coordinated_pivot",
            "parameters": {
                "turn_direction": turn_direction,
                "travel_direction": "forward",
                "angle_deg": angle_deg,
                "duration_s": 4.0,
                "role": "inner" if robot_id == "front" else "outer",
                "swing_radius_m": 0.8,
            },
        }
        for robot_id in ("front", "back")
    }
    return ExecutionTrace(
        script_id="pivot",
        attempt=1,
        status="success",
        skill_calls=(
            SkillCallRecord(
                index=1,
                skill_name="coordinated_pivot",
                parameters={"coordination_mode": "async", "actions": actions},
                status="success",
                started_at_unix=0.0,
                finished_at_unix=1.0,
                robot_ids=("front", "back"),
            ),
        ),
    )


def _turn_episode_pivot_policy(
    *,
    direction: str = "counterclockwise",
    inner_robot: str = "back",
    angle_deg: float = 7.5,
    attempt: int = 1,
) -> PolicyScript:
    scripts = []
    for robot_id in ("front", "back"):
        role = "inner" if robot_id == inner_robot else "outer"
        code = (
            "def policy(api):\n"
            "    api.coordinated_pivot("
            f"turn_direction={direction!r}, travel_direction='forward', "
            f"angle_deg={angle_deg}, duration_s=6.0, "
            f"role={role!r}, swing_radius_m=0.8)\n"
            "    api.stop_all()"
        )
        scripts.append(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_pivot_{attempt}",
                code=code,
                synchronization_group=f"pivot_{attempt}",
                coordination_mode="async",
            )
        )
    return PolicyScript(
        script_id=f"pivot_{attempt}",
        attempt=attempt,
        code=scripts[0].code,
        robot_scripts=tuple(scripts),
    )


def _turn_episode_static_policy(
    *,
    direction: str = "counterclockwise",
    angle_deg: float = 15.0,
    attempt: int = 1,
) -> PolicyScript:
    method = f"turn_{direction}"
    code = (
        "def policy(api):\n"
        f"    api.{method}(yaw_deg={angle_deg}, yaw_rate_degps=5.0, "
        "turn_segment_deg=3.0)\n"
        "    api.stop_all()"
    )
    return PolicyScript(
        script_id=f"static_turn_{attempt}",
        attempt=attempt,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_static_turn_{attempt}",
                code=code,
                synchronization_group=f"static_turn_{attempt}",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )


def _turn_episode_linear_policy(
    distance_m: float,
    *,
    attempt: int = 2,
    direction: str = "forward",
) -> PolicyScript:
    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport("
        f"direction={direction!r}, distance_m={distance_m}, "
        "speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    return PolicyScript(
        script_id=f"linear_probe_{attempt}",
        attempt=attempt,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_linear_probe_{attempt}",
                code=code,
                synchronization_group=f"linear_probe_{attempt}",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )


def _turn_episode_lifecycle_policy(method: str) -> PolicyScript:
    arguments = {
        "place_crouch": "place_height=0.55, ramp_s=2.0, hold_s=3.0",
        "release_payload": "ramp_s=4.0, hold_s=2.0",
        "exit_backward": "distance_m=0.5, speed_mps=0.2, ramp_s=1.5",
        "recover_stand": "height=0.8, ramp_s=6.0, hold_s=2.0",
    }[method]
    code = (
        "def policy(api):\n"
        f"    api.{method}({arguments})\n"
        "    api.stop_all()"
    )
    return PolicyScript(
        script_id=f"lifecycle_{method}",
        attempt=1,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_{method}",
                code=code,
                synchronization_group=f"lifecycle_{method}",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )


