def test_trusted_checkpoint_formation_gate_maps_lagger_to_immutable_robot_id():
    state = _supported_alignment_state()
    state["checkpoint"] = {"checkpoint_id": "accepted_step_14"}
    state["robots"]["back"]["x"] = 0.20

    gate = _trusted_checkpoint_longitudinal_alignment(state)

    assert gate["scope_checkpoint_id"] == "accepted_step_14"
    assert gate["lagging_robot"] == "front"
    assert gate["reference_robot"] == "back"
    assert gate["team_roles"] == {
        "front": "corrector",
        "back": "reference",
    }
    assert gate["robot_deltas_m"] == {"front": 0.15, "back": 0.0}

    state["robots"]["front"]["x"] = 0.40
    reverse_gate = _trusted_checkpoint_longitudinal_alignment(state)
    assert reverse_gate["lagging_robot"] == "back"
    assert reverse_gate["team_roles"] == {
        "front": "reference",
        "back": "corrector",
    }
    assert reverse_gate["robot_deltas_m"] == {"front": 0.0, "back": 0.15}


