def _supported_hold_trace() -> ExecutionTrace:
    return ExecutionTrace(
        script_id="supported_hold",
        attempt=1,
        status="success",
        skill_calls=(
            SkillCallRecord(
                index=1,
                skill_name="hold_position",
                parameters={},
                status="success",
                started_at_unix=0.0,
                finished_at_unix=1.0,
                robot_ids=("front", "back"),
            ),
        ),
    )


@pytest.mark.parametrize(
    ("signed_stagger_m", "lagging_robot", "reference_robot"),
    [
        (0.20, "front", "back"),
        (-0.20, "back", "front"),
    ],
)
def test_supported_endpoint_stagger_is_accepted_with_forward_only_followup(
    tmp_path,
    signed_stagger_m,
    lagging_robot,
    reference_robot,
):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    after = json.loads(json.dumps(before))
    if signed_stagger_m > 0.0:
        after["robots"]["back"]["x"] = signed_stagger_m
    else:
        after["robots"]["front"]["x"] = -signed_stagger_m
    payload_x = 0.5 * (after["robots"]["front"]["x"] + after["robots"]["back"]["x"])
    after["payload"]["x"] = payload_x
    after["payload"]["live_support_target"]["x"] = payload_x
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="accepted_stagger",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        trace=_supported_hold_trace(),
        before_state=before,
        stepwise=True,
    )

    followup = report.evidence["endpoint_longitudinal_alignment"]
    assert report.success
    assert followup["required"]
    assert followup["lagging_robot"] == lagging_robot
    assert followup["reference_robot"] == reference_robot
    assert followup["robot_deltas_m"][lagging_robot] == pytest.approx(0.15)
    assert followup["robot_deltas_m"][reference_robot] == pytest.approx(0.0)
    assert all(delta >= 0.0 for delta in followup["robot_deltas_m"].values())


