def test_signed_turn_verifier_rejects_opposite_physical_response(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    after = json.loads(json.dumps(before))
    after["payload"].update({"y": 0.05, "yaw_deg": -10.0})
    after["payload"]["live_support_target"]["y"] = 0.05
    for robot in after["robots"].values():
        robot["y"] += 0.05
        robot["yaw_rad"] = math.radians(-10.0)
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="signed_turn_guard",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        trace=_arc_execution_trace("counterclockwise"),
        before_state=before,
        stepwise=True,
    )

    # The task evaluator owns physical measurements; the transition verifier
    # owns route/heading acceptance so there is only one rollback decision.
    assert report.success
    assert report.metrics["requested_turn_sign"] == pytest.approx(1.0)
    assert report.metrics["payload_step_signed_yaw_change_deg"] == pytest.approx(-10.0)
    assert report.metrics["team_step_signed_yaw_change_deg"] == pytest.approx(-10.0)
    assert report.evidence["signed_turn_verification"]["payload_opposed_request"]
    decision = verify_transition(
        task=BoxCarryTask(
            task_id="signed_turn_guard",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        report=report,
        trace=_arc_execution_trace("counterclockwise"),
        before_state=before,
        after_state=after,
        accepted_manifest={"steps": []},
    )
    assert decision.outcome is TransitionOutcome.REJECT_REGRESSION
    assert decision.evidence["source"] == "local_setup_effect"


def test_turn_episode_preserves_roles_until_global_passage_alignment():
    accepted = EvaluationReport(success=True, failure_type="none")
    initial_policy = _turn_episode_pivot_policy()
    episode = update_turn_episode(
        empty_turn_episode(),
        policy=initial_policy,
        report=accepted,
        visual_report=VisualVerifierReport(
            status="ok",
            evidence={
                "team_heading_relative_to_visible_free_space": "crosswise_to_passage",
            },
        ),
        checkpoint_id="accepted_step_04",
    )

    validate_policy_for_turn_episode(initial_policy, episode)
    with pytest.raises(TurnEpisodeError, match="opposite direction"):
        validate_policy_for_turn_episode(
            _turn_episode_pivot_policy(direction="clockwise"),
            episode,
        )
    with pytest.raises(TurnEpisodeError, match="inner/outer"):
        validate_policy_for_turn_episode(
            _turn_episode_pivot_policy(inner_robot="front"),
            episode,
        )
    with pytest.raises(TurnEpisodeError, match="linear transport is blocked"):
        validate_policy_for_turn_episode(_turn_episode_linear_policy(0.5), episode)

    visually_aligned_episode = update_turn_episode(
        episode,
        policy=initial_policy,
        report=accepted,
        visual_report=VisualVerifierReport(
            status="ok",
            evidence={
                "team_payload_posture_relative_to_visible_passage": ("lateral_aligned"),
                "route_direction_risk_confirmed": False,
            },
        ),
        checkpoint_id="accepted_step_05",
    )
    assert visually_aligned_episode["status"] == PASSAGE_ALIGNED_STATUS
    assert not visually_aligned_episode["active"]
    assert visually_aligned_episode["translation_pending"]
    assert visually_aligned_episode["latest_passage_posture"] == "lateral_aligned"
    validate_policy_for_turn_episode(
        _turn_episode_linear_policy(1.0),
        visually_aligned_episode,
    )
    with pytest.raises(TurnEpisodeError, match="already verifies"):
        validate_policy_for_turn_episode(initial_policy, visually_aligned_episode)

    completed = update_turn_episode(
        visually_aligned_episode,
        policy=_turn_episode_linear_policy(1.0),
        report=accepted,
        visual_report=None,
        checkpoint_id="accepted_step_06",
    )
