@pytest.mark.parametrize(
    "failure_type",
    [
        "payload_drop",
        "payload_not_supported",
        "payload_slip",
        "payload_unstable",
        "formation_desync",
    ],
)
def test_turn_episode_physics_failure_requires_a_new_executable_script(
    failure_type,
):
    policy = _turn_episode_pivot_policy(direction="counterclockwise")
    episode = update_turn_episode(
        empty_turn_episode(),
        policy=policy,
        report=EvaluationReport(success=True, failure_type="none"),
        visual_report=None,
        checkpoint_id="accepted_step_03",
    )

    rewrite = update_turn_episode(
        episode,
        policy=policy,
        report=EvaluationReport(success=False, failure_type=failure_type),
        visual_report=None,
        checkpoint_id="accepted_step_03",
    )

    assert rewrite["status"] == "script_rewrite_required"
    assert rewrite["switch_allowed"] is True
    assert rewrite["script_failure_type"] == failure_type
    assert rewrite["failed_executable"]["primitive"] == "coordinated_pivot"
    validate_policy_for_turn_episode(
        _turn_episode_pivot_policy(direction="clockwise", inner_robot="front"),
        rewrite,
    )


def test_straightness_failure_creates_one_shot_opposite_heading_correction():
    failed = EvaluationReport(
        success=False,
        failure_type="straightness_regression",
        evidence={
            "straight_transport": {
                "correction_method": "coordinated_pivot",
                "correction_turn_direction": "counterclockwise",
                "correction_turn_angle_deg": 3.2,
                "correction_yaw_deltas_deg": {"front": 3.2, "back": 0.0},
            }
        },
    )
    episode = update_turn_episode(
        empty_turn_episode(),
        policy=_turn_episode_linear_policy(2.0),
        report=failed,
        visual_report=None,
        checkpoint_id="accepted_step_02",
    )

    assert episode["active"] is True
    assert episode["purpose"] == "heading_correction"
    assert episode["status"] == "correction_required"
    assert episode["direction"] == "counterclockwise"
    assert episode["roles"] == {"front": "outer", "back": "inner"}
    assert episode["correction_angle_deg"] == pytest.approx(3.2)

    correction = _turn_episode_pivot_policy(
        direction="counterclockwise",
        inner_robot="back",
        angle_deg=3.2,
    )
    validate_policy_for_turn_episode(correction, episode)
    with pytest.raises(TurnEpisodeError, match="opposite direction"):
        validate_policy_for_turn_episode(
            _turn_episode_pivot_policy(
                direction="clockwise",
                inner_robot="back",
                angle_deg=3.2,
            ),
            episode,
        )
    with pytest.raises(TurnEpisodeError, match="verifier-reported"):
        validate_policy_for_turn_episode(
            _turn_episode_pivot_policy(
                direction="counterclockwise",
                inner_robot="back",
                angle_deg=30.0,
            ),
            episode,
        )

    completed = update_turn_episode(
        episode,
        policy=correction,
        report=EvaluationReport(success=True, failure_type="none"),
        visual_report=None,
        checkpoint_id="accepted_step_03",
    )
    assert completed["active"] is False
    assert completed["status"] == "correction_completed"


def test_heading_correction_accepts_material_robot_yaw_without_payload_yaw(
    tmp_path,
):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    after = json.loads(json.dumps(before))
    # A freely supported box can transiently slip in the opposite yaw direction
    # while both locomotion roots execute the requested small heading correction.
    after["payload"]["yaw_deg"] = -4.75
    for robot in after["robots"].values():
        robot["yaw_rad"] = math.radians(1.65)
    runtime_state.write_text(json.dumps(after), encoding="utf-8")
    episode = {
        "active": True,
        "purpose": "heading_correction",
        "primitive": "coordinated_pivot",
        "direction": "counterclockwise",
        "roles": {"front": "inner", "back": "outer"},
        "correction_angle_deg": 2.17876,
    }

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="small_heading_correction",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        trace=_pivot_execution_trace(angle_deg=2.17876),
        before_state=before,
        stepwise=True,
        turn_episode=episode,
    )

    assert report.success
    correction = report.evidence["heading_correction_verification"]
    assert correction["payload_yaw_is_diagnostic_only"]
    assert correction["signed_robot_yaw_deg"]["front"] == pytest.approx(1.65)
    assert correction["signed_robot_yaw_deg"]["back"] == pytest.approx(1.65)


