def test_heading_correction_bypasses_strategy_budget_but_not_rejected_ast():
    episode = {
        "active": True,
        "purpose": "heading_correction",
        "primitive": "coordinated_pivot",
        "direction": "counterclockwise",
        "roles": {"front": "outer", "back": "inner"},
        "correction_angle_deg": 2.0,
    }
    payload = {
        "observation": {"runtime_state": {"turn_episode": episode}},
        "coordination_primitive_sdk": coordination_primitive_library_doc(),
    }
    client = FakeModelClient([])

    selected = _select_evolution_subtask(
        client=client,
        payload=payload,
        forbidden_methods=("coordinated_pivot",),
        blocked_strategy_signatures=("async:coordinated_pivot",),
    )
    parameters = _select_coordination_parameters(
        client=client,
        selected_subtask=selected,
        payload=payload,
    )
    _compiled, policy = _compile_model_selected_coordination_policy(
        current_policy=_turn_episode_linear_policy(2.0),
        attempt=3,
        selected_subtask=selected,
        selected_parameters=parameters,
        failure_level="strategy",
        failure_type="straightness_regression",
        blocked_strategy_signatures={"async:coordinated_pivot"},
        blocked_transaction_signatures=set(),
    )

    assert client.prompts == []
    assert selected["selection_source"] == "verifier_heading_correction"
    assert parameters["selection_source"] == "verifier_heading_correction_fallback"
    assert parameters["robot_parameters"]["front"]["role"] == "outer"
    assert parameters["robot_parameters"]["back"]["role"] == "inner"
    assert parameters["robot_parameters"]["front"]["angle_deg"] == pytest.approx(2.0)
    assert "api.coordinated_pivot" in policy.code

    rejected_signature = _policy_transaction_signature(policy)
    with pytest.raises(
        ModelAgentError,
        match="repeats a verifier-rejected executable transaction",
    ):
        _compile_model_selected_coordination_policy(
            current_policy=_turn_episode_linear_policy(2.0),
            attempt=4,
            selected_subtask=selected,
            selected_parameters=parameters,
            failure_level="strategy",
            failure_type="straightness_regression",
            blocked_strategy_signatures={"async:coordinated_pivot"},
            blocked_transaction_signatures={rejected_signature},
        )


