def test_diagonal_passage_posture_forces_model_selected_shared_heading_turn():
    episode = {
        "active": False,
        "status": PASSAGE_ALIGNMENT_REQUIRED_STATUS,
        "purpose": "route_turn",
        "primitive": "coordinated_pivot",
        "direction": "clockwise",
        "roles": {"front": "inner", "back": "outer"},
        "last_angle_deg": 30.0,
        "accepted_turn_steps": 3,
        "cumulative_signed_team_yaw_deg": -89.0,
        "cumulative_turn_progress_deg": 89.0,
        "switch_allowed": True,
        "translation_pending": False,
    }
    payload = {
        "route_discovery": True,
        "observation": {
            "runtime_state": {
                "payload": {"supporting_robots": ["front", "back"]},
                "turn_episode": episode,
                "trusted_route_observation": {
                    "team_payload_posture_relative_to_visible_passage": (
                        "diagonal_to_passage"
                    ),
                    "team_heading_relative_to_visible_free_space": (
                        "crosswise_to_passage"
                    ),
                },
            }
        },
        "coordination_primitive_sdk": coordination_primitive_library_doc(),
        "evolution_controller": {
            "repair_level": "strategy",
            "action": "switch_strategy",
        },
        "evaluation": {
            "success": False,
            "failure_type": "payload_slip",
            "metrics": {"task_complete": 0},
        },
    }
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "strategy_pair": "async:coordinated_pivot",
                    "motion_objective": "counterclockwise",
                    "direction_evidence": (
                        "The current trusted global view labels the complete "
                        "team-payload posture diagonal to the connected passage."
                    ),
                    "alternative_direction": "clockwise",
                    "alternative_rejection_reason": (
                        "The opposite sign continues the previously measured "
                        "misalignment at this checkpoint."
                    ),
                    "reason": "Change shared heading before loaded translation.",
                }
            )
        ]
    )

    selected = _select_evolution_subtask(
        client=client,
        payload=payload,
        forbidden_methods=(),
    )

    assert selected["selected_method"] == "coordinated_pivot"
    assert selected["coordination_mode"] == "async"
    assert selected["motion_objective"] == "counterclockwise"
    assert "async:coordinated_pivot" in client.prompts[0]["user"]
    assert '"requires_heading_change": true' in client.prompts[0]["user"]
    with pytest.raises(TurnEpisodeError, match="straight transport is blocked"):
        validate_policy_for_turn_episode(_turn_episode_linear_policy(1.0), episode)


