def test_route_turn_budget_requires_visual_passage_alignment_before_translation():
    episode = {
        "active": True,
        "status": "turning",
        "purpose": "route_turn",
        "primitive": "coordinated_pivot",
        "direction": "clockwise",
        "roles": {"front": "inner", "back": "outer"},
        "last_angle_deg": 30.0,
        "accepted_turn_steps": 2,
        "cumulative_signed_team_yaw_deg": -60.0,
        "cumulative_signed_payload_yaw_deg": -80.0,
        "cumulative_payload_turn_progress_deg": 80.0,
        "cumulative_turn_progress_deg": 80.0,
        "cumulative_turn_progress_source": "physical_payload_yaw",
        "switch_allowed": False,
    }
    policy = _turn_episode_pivot_policy(
        direction="clockwise",
        inner_robot="front",
        angle_deg=30.0,
    )
    updated = update_turn_episode(
        episode,
        policy=policy,
        report=EvaluationReport(
            success=True,
            failure_type="none",
            metrics={
                "team_step_signed_yaw_change_deg": -29.0,
                "payload_step_signed_yaw_change_deg": -10.0,
            },
        ),
        visual_report=None,
        checkpoint_id="accepted_step_03",
    )

    assert updated["status"] == PASSAGE_ALIGNMENT_REQUIRED_STATUS
    assert not updated["active"]
    assert not updated["translation_pending"]
    assert updated["switch_allowed"]
    assert (
        updated["completion_trigger"] == "turn_budget_reached_without_passage_alignment"
    )
    assert updated["cumulative_signed_team_yaw_deg"] == pytest.approx(-89.0)
    assert updated["cumulative_signed_payload_yaw_deg"] == pytest.approx(-90.0)
    assert updated["cumulative_turn_progress_deg"] == pytest.approx(90.0)
    assert updated["cumulative_turn_progress_deg"] >= ROUTE_TURN_PROBE_YAW_DEG


