def test_reconstruct_turn_episode_stops_at_restored_checkpoint(tmp_path):
    steps = []
    checkpoint_before = "accepted_step_00"
    for index, payload_yaw_deg in enumerate((30.0, 30.0, 30.0), start=1):
        source_dir = tmp_path / f"attempt_{index:02d}"
        source_dir.mkdir()
        (source_dir / "evaluation.json").write_text(
            json.dumps(
                {
                    "success": True,
                    "failure_type": "none",
                    "metrics": {
                        "team_step_signed_yaw_change_deg": 25.0,
                        "payload_step_signed_yaw_change_deg": payload_yaw_deg,
                    },
                }
            ),
            encoding="utf-8",
        )
        checkpoint_after = f"accepted_step_{index:02d}"
        front_code = (
            "def policy(api):\n"
            "    api.coordinated_pivot(turn_direction='counterclockwise', "
            "travel_direction='forward', angle_deg=30.0, duration_s=4.0, "
            "role='outer', swing_radius_m=0.8)\n"
            "    api.stop_all()"
        )
        back_code = front_code.replace("role='outer'", "role='inner'")
        steps.append(
            {
                "index": index,
                "script_id": f"accepted_turn_{index}",
                "attempt": index,
                "checkpoint_before": checkpoint_before,
                "checkpoint_after": checkpoint_after,
                "coordination_mode": "async",
                "source_artifact_dir": str(source_dir),
                "robot_calls": {
                    "front": {"code": front_code},
                    "back": {"code": back_code},
                },
                "robot_scripts": {
                    "front": {
                        "robot_id": "front",
                        "script_id": f"front_{index}",
                        "code": front_code,
                        "synchronization_group": f"turn_{index}",
                        "coordination_mode": "async",
                    },
                    "back": {
                        "robot_id": "back",
                        "script_id": f"back_{index}",
                        "code": back_code,
                        "synchronization_group": f"turn_{index}",
                        "coordination_mode": "async",
                    },
                },
            }
        )
        checkpoint_before = checkpoint_after

    reconstructed = _reconstruct_turn_episode_from_manifest(
        {
            "initial_checkpoint": "accepted_step_00",
            "latest_checkpoint": "accepted_step_03",
            "steps": steps,
        },
        checkpoint_id="accepted_step_03",
    )

    assert reconstructed["status"] == PASSAGE_ALIGNMENT_REQUIRED_STATUS
    assert not reconstructed["translation_pending"]
    assert reconstructed["switch_allowed"]
    assert reconstructed["cumulative_signed_payload_yaw_deg"] == pytest.approx(90.0)
    assert reconstructed["replayed_through_checkpoint_id"] == "accepted_step_03"


