def test_successful_yaw_alignment_reopens_same_route_turn_probe():
    episode = {
        "active": True,
        "status": "switch_allowed",
        "purpose": "route_turn",
        "primitive": "coordinated_pivot",
        "direction": "counterclockwise",
        "roles": {"front": "outer", "back": "inner"},
        "last_angle_deg": 30.0,
        "accepted_turn_steps": 4,
        "probe_direction": "forward",
        "probe_max_distance_m": 0.5,
        "cumulative_signed_team_yaw_deg": 112.0,
        "cumulative_turn_progress_deg": 112.0,
        "switch_allowed": True,
        "probe_retry_count": 2,
    }
    code_by_robot = {
        "front": (
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='yaw', delta=0.0, duration_s=2.0)\n"
            "    api.stop_all()"
        ),
        "back": (
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='yaw', delta=8.087, duration_s=2.0)\n"
            "    api.stop_all()"
        ),
    }
    policy = PolicyScript(
        script_id="verifier_yaw_alignment",
        attempt=24,
        code=code_by_robot["front"],
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_verifier_yaw_alignment",
                code=code_by_robot[robot_id],
                synchronization_group="alignment_group",
                phase_id="alignment",
                contact_intent="maintain_payload_support",
                coordination_mode="async",
            )
            for robot_id in ("front", "back")
        ),
    )

    updated = update_turn_episode(
        episode,
        policy=policy,
        report=EvaluationReport(success=True, failure_type="none"),
        visual_report=None,
        checkpoint_id="accepted_step_08",
    )

    assert updated["active"]
    assert updated["status"] == "probe_ready"
    assert not updated["switch_allowed"]
    assert updated["latest_checkpoint_id"] == "accepted_step_08"
    assert updated["last_heading_alignment_deltas_deg"] == {
        "front": 0.0,
        "back": 8.087,
    }
    assert updated["probe_retry_count"] == 0
    assert updated["probe_retry_failure_type"] == ""
    validate_policy_for_turn_episode(_turn_episode_linear_policy(0.5), updated)


