def _coordinated_linear_execution_trace(direction: str) -> ExecutionTrace:
    actions = {
        robot_id: {
            "method": "coordinated_linear_transport",
            "parameters": {
                "direction": direction,
                "distance_m": 1.0,
                "speed_mps": 0.5,
                "ramp_s": 1.5,
            },
        }
        for robot_id in ("front", "back")
    }
    return ExecutionTrace(
        script_id=f"linear_{direction}",
        attempt=1,
        status="success",
        skill_calls=(
            SkillCallRecord(
                index=1,
                skill_name="coordinated_linear_transport",
                parameters={"coordination_mode": "sync", "actions": actions},
                status="success",
                started_at_unix=0.0,
                finished_at_unix=1.0,
                robot_ids=("front", "back"),
            ),
        ),
    )


def test_straightness_contract_rejects_loaded_forward_heading_drift(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    after = json.loads(json.dumps(before))
    for robot in after["robots"].values():
        robot["x"] += 1.0
        robot["y"] -= 0.15
        robot["yaw_rad"] = math.radians(-5.0)
    after["payload"]["x"] += 1.0
    after["payload"]["y"] -= 0.15
    after["payload"]["live_support_target"].update(
        {"x": after["payload"]["x"], "y": after["payload"]["y"]}
    )
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state, safety_profile="strict").evaluate(
        task=BoxCarryTask(
            task_id="straight_heading_guard",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        trace=_coordinated_linear_execution_trace("forward"),
        before_state=before,
        stepwise=True,
        straight_heading_reference_rad=0.0,
    )

    assert not report.success
    assert report.failure_type == "straightness_regression"
    assert report.metrics["straight_heading_error_deg"] == pytest.approx(-5.0)
    assert report.evidence["straight_transport"]["correction_turn_direction"] == (
        "counterclockwise"
    )
    assert report.evidence["straight_transport"]["correction_method"] == (
        "coordinated_pivot"
    )


