def test_task_profile_warns_on_moderate_skew_when_dual_support_remains(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    after = json.loads(json.dumps(before))
    after["robots"]["front"].update({"x": 1.0, "y": -0.4, "yaw_rad": math.radians(8.0)})
    after["robots"]["back"].update({"x": 1.2, "y": 0.4, "yaw_rad": math.radians(8.0)})
    after["payload"]["x"] += 1.1
    after["payload"]["tilt_deg"] = 33.0
    after["payload"]["live_support_target"]["x"] += 1.1
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="recoverable_linear_skew",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        trace=_coordinated_linear_execution_trace("forward"),
        before_state=before,
        stepwise=True,
        straight_heading_reference_rad=0.0,
    )

    assert report.success
    assert report.evidence["linear_formation_geometry"]["violated"]
    assert not report.evidence["linear_formation_geometry"]["hard_failure"]
    assert not report.evidence["straight_transport"]["hard_failure"]
    warning_types = {
        item["type"] for item in report.evidence["physical_quality_warnings"]
    }
    assert "linear_formation_skew" in warning_types
    assert "straightness_regression" in warning_types
    assert "payload_tilt" in warning_types

    classified = _with_checkpoint_outcome(
        report,
        route_discovery=True,
        checkpoint_committed=True,
        checkpoint_before="accepted_step_01",
        checkpoint_after="accepted_step_02",
        rollback_performed=False,
        physically_dispatched=True,
    )
    outcome = classified.evidence["checkpoint_outcome"]
    assert outcome["physics_safe"] is True
    assert outcome["progress_status"] == "route_progress"
    assert outcome["transition_outcome"] == "ACCEPT_PROGRESS"
    assert outcome["phase_completion_proven"] is False
    assert outcome["carry_quality"] == "degraded"
    compact = _evaluation_payload(classified, include_goal_metrics=False)
    assert compact["evidence"]["checkpoint_outcome"] == outcome
    assert compact["evidence"]["physical_quality_warnings"]


