    after["robots"]["back"]["yaw_rad"] = math.radians(4.0)
    after["payload"]["x"] += 1.0
    after["payload"]["live_support_target"]["x"] += 1.0
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state, safety_profile="strict").evaluate(
        task=BoxCarryTask(
            task_id="relative_heading_split",
            target="discover route while carrying",
            route_discovery=True,
            require_payload_on_target=False,
            require_robots_exit=False,
        ),
        trace=_coordinated_linear_execution_trace("forward"),
        before_state=before,
        stepwise=True,
        straight_heading_reference_rad=0.0,
    )

    assert not report.success
    assert report.failure_type == "straightness_regression"
    straight = report.evidence["straight_transport"]
    assert straight["correction_method"] == "coordinated_alignment"
    assert straight["correction_alignment_axis"] == "yaw"
    assert straight["correction_yaw_deltas_deg"] == {
        "front": pytest.approx(4.0),
        "back": 0.0,
    }


