def test_post_restore_heading_plan_separates_shared_bias_from_robot_split():
    state = _supported_alignment_state()
    state["robots"]["front"]["yaw_rad"] = math.radians(-7.0)
    state["robots"]["back"]["yaw_rad"] = math.radians(-5.0)
    shared = _straight_heading_status(state, reference_yaw_rad=0.0)
    shared_plan = _post_restore_heading_correction_plan(shared)

    assert shared_plan["coordination_mode"] == "async"
    assert shared_plan["method"] == "coordinated_pivot"
    assert {
        action["parameters"]["turn_direction"]
        for action in shared_plan["actions"].values()
    } == {"counterclockwise"}
    assert shared_plan["actions"]["back"]["parameters"]["role"] == "inner"
    assert shared_plan["actions"]["front"]["parameters"]["role"] == "outer"
    assert {
        action["parameters"]["travel_direction"]
        for action in shared_plan["actions"].values()
    } == {"forward"}

    state["robots"]["front"]["yaw_rad"] = math.radians(-4.0)
    state["robots"]["back"]["yaw_rad"] = math.radians(-0.5)
    split = _straight_heading_status(state, reference_yaw_rad=0.0)
    split_plan = _post_restore_heading_correction_plan(split)

    assert split_plan["coordination_mode"] == "async"
    assert split_plan["method"] == "coordinated_alignment"
    assert split_plan["actions"]["front"]["parameters"] == {
        "axis": "yaw",
        "delta": 5.0,
        "duration_s": 6.0,
    }
    assert split_plan["actions"]["back"]["parameters"]["delta"] == 0.0


