def test_straight_heading_ledger_inherits_translation_and_tracks_turns(tmp_path):
    ledger = tmp_path / "straight_heading_references.json"
    initial_reference = math.radians(12.0)
    references = {
        "accepted_step_00": initial_reference,
        "accepted_step_04": initial_reference,
    }
    _write_straight_heading_references(
        ledger,
        active_checkpoint_id="accepted_step_04",
        references=references,
    )

    loaded = _load_straight_heading_references(ledger, reset=False)
    assert loaded["accepted_step_04"] == pytest.approx(initial_reference)
    assert _straight_heading_reference_for_checkpoint(
        "accepted_step_04",
        references=loaded,
        fallback_state=_supported_alignment_state(),
        runtime_state_file=tmp_path / "runtime_state.json",
    ) == pytest.approx(initial_reference)

    translated_state = _supported_alignment_state()
    translated_reference = _straight_heading_reference_after_accepted_action(
        current_reference_rad=initial_reference,
        trace=_coordinated_linear_execution_trace("left"),
        runtime_state=translated_state,
    )
    assert translated_reference == pytest.approx(initial_reference)

    correction_state = _supported_alignment_state()
    for robot in correction_state["robots"].values():
        robot["yaw_rad"] = math.radians(14.0)
    turn_trace = ExecutionTrace(
        script_id="heading_correction",
        attempt=1,
        status="success",
        skill_calls=(
            SkillCallRecord(
                index=1,
                skill_name="coordinated_pivot",
                parameters={"turn_direction": "counterclockwise", "angle_deg": 2.0},
                status="success",
                started_at_unix=0.0,
                finished_at_unix=1.0,
                robot_ids=("front", "back"),
            ),
        ),
    )
    corrected_reference = _straight_heading_reference_after_accepted_action(
        current_reference_rad=initial_reference,
        trace=turn_trace,
        runtime_state=correction_state,
    )
    assert corrected_reference == pytest.approx(initial_reference)

    intentional_turn_state = _supported_alignment_state()
    for robot in intentional_turn_state["robots"].values():
        robot["yaw_rad"] = math.radians(42.0)
    turned_reference = _straight_heading_reference_after_accepted_action(
        current_reference_rad=initial_reference,
        trace=turn_trace,
        runtime_state=intentional_turn_state,
    )
    assert turned_reference == pytest.approx(math.radians(42.0))

    loaded["accepted_step_05"] = turned_reference
    assert _straight_heading_reference_for_checkpoint(
        "accepted_step_04",
        references=loaded,
        fallback_state=intentional_turn_state,
        runtime_state_file=tmp_path / "runtime_state.json",
    ) == pytest.approx(initial_reference)
    assert _straight_heading_reference_for_checkpoint(
        "accepted_step_11",
        references={"accepted_step_11": initial_reference},
        fallback_state=intentional_turn_state,
        runtime_state_file=tmp_path / "runtime_state.json",
        resume_as_episode_root=True,
    ) == pytest.approx(math.radians(42.0))


