def test_arc_rejects_large_active_goal_regression(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    after = json.loads(json.dumps(before))
    after["payload"]["x"] = -0.50
    after["payload"]["yaw_deg"] = 45.0
    after["payload"]["live_support_target"]["x"] = -0.50
    for robot in after["robots"].values():
        robot["x"] = -0.50
        robot["yaw_rad"] = math.radians(45.0)
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    task = BoxCarryTask(
        task_id="arc_goal_regression",
        target="turn while carrying toward the stage goal",
        task_stage="stage1_straight",
        stage1_goal_x_m=1.0,
        stage1_goal_y_m=0.0,
    )
    trace = _arc_execution_trace()
    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=task,
        trace=trace,
        before_state=before,
        stepwise=True,
    )

    decision = verify_transition(
        task=task,
        report=report,
        trace=trace,
        before_state=before,
        after_state=after,
        accepted_manifest={"steps": []},
    )
    assert report.success
    assert report.evidence["deferred_transition_semantic_diagnostic"][
        "failure_type"
    ] == "goal_regression"
    assert decision.outcome is TransitionOutcome.REJECT_REGRESSION
    assert report.metrics["payload_target_progress_m"] == pytest.approx(-0.50)
    assert not report.evidence["turn_progress_verification"].get(
        "semantic_turn_improved",
        False,
    )


