@pytest.mark.integration
def test_dual_g1_sonic_mujoco_scene_generator_namespaces_robot_xml(tmp_path):
    assert DEFAULT_PAYLOAD_MASS_KG == pytest.approx(0.5)

    source_g1 = Path("third_party/GR00T-WholeBodyControl") / DEFAULT_G1_SOURCE_XML
    gear_root = tmp_path / "gear_root"
    copied_source = gear_root / DEFAULT_G1_SOURCE_XML
    copied_source.parent.mkdir(parents=True)
    copied_source.write_text(source_g1.read_text(encoding="utf-8"), encoding="utf-8")

    result = generate_dual_manual_layout_scene(
        source_usda=DEFAULT_USDA_SCENE, gear_root=gear_root
    )

    assert result.scene_path.exists()
    assert {robot.prefix for robot in result.robot_xmls} == {"front_", "back_"}
    front_xml = result.robot_xmls[0].output_path.read_text(encoding="utf-8")
    back_xml = result.robot_xmls[1].output_path.read_text(encoding="utf-8")
    scene_xml = result.scene_path.read_text(encoding="utf-8")
    assert "front_pelvis" in front_xml
    assert "back_pelvis" in back_xml
    assert "praxis_g1_front_29dof_with_hand.xml" in scene_xml
    assert "praxis_g1_back_29dof_with_hand.xml" in scene_xml

    scene_root = ET.parse(result.scene_path).getroot()
    wall_08 = scene_root.find(".//geom[@name='wall_08']")
    assert wall_08 is not None
    assert [float(item) for item in wall_08.attrib["pos"].split()] == pytest.approx(
        (-2.6943596811389874, 2.2552938124255535, 0.35)
    )
    assert [float(item) for item in wall_08.attrib["size"].split()] == pytest.approx(
        (1.35, 0.075, 0.35)
    )
    long_box = scene_root.find(".//body[@name='long_box']")
    assert long_box is not None
    box_pos = [float(item) for item in long_box.attrib["pos"].split()]
    assert box_pos == pytest.approx(DEFAULT_PAYLOAD_STAGING_XYZ)
    support_site = scene_root.find(".//site[@name='long_box_support_pose']")
    assert support_site is not None
    global_camera = scene_root.find(".//camera[@name='vlm_global_topdown']")
    assert global_camera is not None
    assert global_camera.attrib["xyaxes"] == "-1 0 0 0 -1 0"
    assert float(global_camera.attrib["fovy"]) == pytest.approx(45.0)
    assert float(global_camera.attrib["pos"].split()[2]) == pytest.approx(13.0)
    box_geom = scene_root.find(".//geom[@name='long_box_geom']")
    assert box_geom is not None
    assert float(box_geom.attrib["mass"]) == pytest.approx(DEFAULT_PAYLOAD_MASS_KG)
    assert box_geom.attrib["rgba"].split()[-1] == "0"
    assert box_geom.attrib["contype"] == "1"
    assert box_geom.attrib["conaffinity"] == "3"
    support_geoms = []
    for robot_xml in result.robot_xmls:
        support_geoms.extend(
            geom
            for geom in ET.parse(robot_xml.output_path).getroot().iter("geom")
            if geom.get("name", "").endswith("_support_plate")
        )
    assert {geom.get("name") for geom in support_geoms} == {
        "front_left_carry_support_plate",
        "front_right_carry_support_plate",
        "back_left_carry_support_plate",
        "back_right_carry_support_plate",
        "front_left_carry_forearm_support_plate",
        "front_right_carry_forearm_support_plate",
        "back_left_carry_forearm_support_plate",
        "back_right_carry_forearm_support_plate",
    }
    assert all(geom.attrib["type"] == "box" for geom in support_geoms)
    assert {geom.attrib["size"] for geom in support_geoms} == {
        "0.06 0.035 0.006",
        "0.11 0.032 0.006",
    }
    assert all(geom.attrib["contype"] == "2" for geom in support_geoms)
    assert all(geom.attrib["conaffinity"] == "0" for geom in support_geoms)
    assert not any(
        marker in geom.get("name", "")
        for geom in support_geoms
        for marker in ("rail", "bumper", "tray")
    )

    active_result = generate_dual_manual_layout_scene(
        source_usda=DEFAULT_USDA_SCENE,
        gear_root=gear_root,
        scene_rel_path=Path(
            "gear_sonic/data/robot_model/model_data/g1/active_payload.xml"
        ),
        payload_initial_state="active",
    )
    active_root = ET.parse(active_result.scene_path).getroot()
    active_geom = active_root.find(".//geom[@name='long_box_geom']")
    assert active_geom is not None
    assert active_geom.attrib["rgba"].split()[-1] == "1"


def test_payload_rearward_offset_uses_live_robot_heading():
    import numpy as np

    assert DEFAULT_PAYLOAD_REARWARD_OFFSET_M == pytest.approx(0.10)
    assert payload_rearward_offset_xy([0.0, 0.0], 0.01) == pytest.approx([-0.01, 0.0])
    assert payload_rearward_offset_xy(
        [0.5 * np.pi, 0.5 * np.pi], 0.01
    ) == pytest.approx([0.0, -0.01])


def test_support_surface_pitch_correction_is_heading_relative():
    import numpy as np

    tilted_toward_negative_x = np.asarray([-0.2, 0.0, 0.98])
    correction_x = support_surface_pitch_correction(tilted_toward_negative_x, 0.0)
    correction_y = support_surface_pitch_correction(
        tilted_toward_negative_x, 0.5 * np.pi
    )

    assert correction_x > 0.0
    assert correction_x == pytest.approx(np.arctan2(0.2, 0.98))
    assert correction_y == pytest.approx(0.0, abs=1.0e-9)


def test_support_surface_roll_correction_is_heading_relative():
    import numpy as np

    tilted_toward_negative_y = np.asarray([0.0, -0.2, 0.98])
    correction_x_heading = support_surface_roll_correction(
        tilted_toward_negative_y,
        0.0,
    )
    correction_y_heading = support_surface_roll_correction(
        tilted_toward_negative_y,
        0.5 * np.pi,
    )

    assert correction_x_heading == pytest.approx(np.arctan2(-0.2, 0.98))
    assert correction_y_heading == pytest.approx(0.0, abs=1.0e-9)


