def test_carry_stability_latches_floor_contact_but_not_recoverable_support_offset():
    dropped = PayloadRuntimeStatus(
        available=True, active=True, z=0.05, floor_contact=True
    )
    failure, _reason = _hard_carry_failure(
        dropped,
        min_z_m=0.80,
        min_robot_pelvis_height_m=0.35,
        max_tilt_deg=8.0,
        max_top_surface_z_range_m=0.12,
        wall_contact_is_hard_failure=False,
    )
    assert failure == "payload_drop"

    slipped = PayloadRuntimeStatus(
        available=True,
        active=True,
        z=0.95,
        tilt_deg=1.0,
        top_surface_corner_z_range_m=0.01,
        min_robot_pelvis_height_m=0.78,
        support_center_xy_error_available=True,
        support_center_xy_error_m=0.051,
    )
    failure, _reason = _hard_carry_failure(
        slipped,
        min_z_m=0.80,
        min_robot_pelvis_height_m=0.35,
        max_tilt_deg=8.0,
        max_top_surface_z_range_m=0.12,
        wall_contact_is_hard_failure=False,
    )
    assert failure == ""

    overturned_pose = PayloadRuntimeStatus(
        available=True,
        active=True,
        z=1.0,
        tilt_deg=102.0,
        min_robot_pelvis_height_m=0.78,
        robot_xy_separation_available=True,
        robot_xy_separation_m=0.84,
    )
    failure, _reason = _hard_carry_failure(
        overturned_pose,
        min_z_m=0.65,
        min_robot_pelvis_height_m=0.35,
        min_robot_xy_separation_m=0.60,
        max_tilt_deg=25.0,
        max_top_surface_z_range_m=0.30,
        wall_contact_is_hard_failure=False,
    )
    assert failure == ""

    failure, _reason = _hard_carry_failure(
        overturned_pose,
        min_z_m=0.65,
        min_robot_pelvis_height_m=0.35,
        min_robot_xy_separation_m=0.60,
        max_tilt_deg=25.0,
        max_top_surface_z_range_m=0.30,
        wall_contact_is_hard_failure=False,
        enforce_geometry_limits=True,
    )
    assert failure == "payload_unstable"


def test_visual_observation_keeps_global_frame_and_appends_tracking_panel(tmp_path):
    from PIL import Image

    source = tmp_path / "global.png"
    output = tmp_path / "composite.png"
    Image.new("RGB", (800, 450), (80, 70, 60)).save(source)
    runtime_state = {
        "payload": {
            "x": -0.85,
            "y": 2.16,
            "z": 0.99,
            "tilt_deg": 1.2,
            "contacts": {
                "support_robots": ["front", "back"],
                "support_geometries": ["a", "b", "c", "d"],
                "floor": False,
                "walls": [],
            },
        },
        "viewer_camera": {
            "lookat_xyz": [0.47, 4.93, 0.45],
            "distance_m": 11.0,
            "fovy_deg": 45.0,
        },
        "robots": {
            "front": {"yaw_deg": -34.5},
            "back": {"yaw_deg": -36.0},
        },
    }

    result = _write_global_tracking_composite(
        source,
        output,
        runtime_state=runtime_state,
        world_span_m=4.6,
    )

    assert result == output
    assert output.exists()
