    method, example, reason = _required_evolution_call(
        {"observation": {"runtime_state": runtime}}
    )

    assert method == "place_crouch"
    assert example == "place_crouch(place_height=0.55, ramp_s=2, hold_s=3)"
    assert "lower both robots" in reason

    runtime["payload"]["z"] = 0.86
    method, example, reason = _required_evolution_call(
        {"observation": {"runtime_state": runtime}}
    )

    assert method == "release_payload"
    assert example == "release_payload(ramp_s=4, hold_s=2)"
    assert "guarded crouch-and-release" in reason


