def test_post_release_lifecycle_repeats_crouched_exit_until_robots_are_clear():
    released_runtime = {
        "payload": {
            "active": True,
            "x": -1.50,
            "y": 7.60,
            "z": 0.65,
            "supporting_robots": [],
            "all_robot_contacts": [],
            "target_contact": True,
            "released": True,
        },
        "target": {
            "center_x_m": -1.50,
            "center_y_m": 7.60,
            "payload_center_target_z_m": 0.65,
        },
        "robots": {
            "front": {"x": -1.00, "y": 7.10},
            "back": {"x": -2.00, "y": 7.10},
        },
        "post_release_lifecycle": {
            "payload_released": True,
            "crouch_latched": True,
            "crouched_retreat_completed": True,
            "stand_recovered": False,
        },
    }
    payload = {"observation": {"runtime_state": released_runtime}}

    method, example, reason = _required_evolution_call(payload)

    assert method == "exit_backward"
    assert example == "exit_backward(distance_m=0.5, speed_mps=0.50, ramp_s=1.5)"
    assert "stand-recovery drift" in reason
    assert "exit_backward" not in _lifecycle_forbidden_methods(payload)
    assert "recover_stand" in _lifecycle_forbidden_methods(payload)

    released_runtime["robots"] = {
        "front": {"x": -0.20, "y": 7.60},
        "back": {"x": -2.80, "y": 7.60},
    }
    method, example, reason = _required_evolution_call(payload)

    assert method == "recover_stand"
    assert example == "recover_stand(height=0.80, ramp_s=6, hold_s=2)"
    assert "recover both robots upright" in reason
    assert "exit_backward" not in _lifecycle_forbidden_methods(payload)
    assert "recover_stand" not in _lifecycle_forbidden_methods(payload)


def test_failed_stand_clearance_forces_another_crouched_exit():
    runtime = {
        "payload": {
            "active": True,
            "x": -1.50,
            "y": 7.60,
            "z": 0.65,
            "supporting_robots": [],
            "target_contact": True,
            "released": True,
        },
        "target": {
            "center_x_m": -1.50,
            "center_y_m": 7.60,
            "payload_center_target_z_m": 0.65,
        },
        "robots": {
            "front": {"x": -0.25, "y": 7.60},
            "back": {"x": -2.75, "y": 7.60},
        },
        "post_release_lifecycle": {
            "payload_released": True,
            "crouch_latched": True,
            "crouched_retreat_completed": True,
            "stand_recovered": False,
        },
    }
    payload = {"observation": {"runtime_state": runtime}}
    policy = PolicyScript(
        script_id="failed_recover_stand",
        attempt=24,
        code=(
            "def policy(api):\n"
            "    api.recover_stand(height=0.8, ramp_s=6, hold_s=2)\n"
            "    api.stop_all()"
        ),
    )
    report = EvaluationReport(success=False, failure_type="robots_not_clear")

    method, example, reason = _required_evolution_call(
        payload,
        previous_policy=policy,
        previous_report=report,
    )

    assert method == "exit_backward"
    assert example == "exit_backward(distance_m=0.5, speed_mps=0.50, ramp_s=1.5)"
    assert "stand recovery physically crossed back" in reason
    forbidden = _lifecycle_forbidden_methods(
        payload,
        previous_policy=policy,
        previous_report=report,
    )
    assert "exit_backward" not in forbidden
    assert "recover_stand" in forbidden


