def test_recover_stand_rejects_post_stand_clearance_regression(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = {
        "payload": {
            "active": True,
            "x": -1.5,
            "y": 7.6,
            "z": 0.65,
            "released": True,
            "contacts": {
                "robots": [],
                "support_robots": [],
                "walls": [],
                "floor": False,
                "target": True,
            },
        },
        "robots": {
            robot_id: {
                "x": x,
                "y": 7.6,
                "pelvis_height_m": 0.60,
                "place_crouch": {"crouch": 1.0, "post_release_latched": True},
            }
            for robot_id, x in (("front", -0.19), ("back", -2.81))
        },
        "post_release_lifecycle": {
            "payload_released": True,
            "crouch_latched": True,
            "crouched_retreat_completed": True,
            "stand_recovered": False,
        },
    }
    after = json.loads(json.dumps(before))
    after["robots"]["front"]["x"] = -0.40
    after["robots"]["back"]["x"] = -2.60
    for robot in after["robots"].values():
        robot["pelvis_height_m"] = 0.78
        robot["place_crouch"] = {}
    after["post_release_lifecycle"].update(
        {"crouch_latched": False, "stand_recovered": True}
    )
    runtime_state.write_text(json.dumps(after), encoding="utf-8")
    trace = PolicyExecutor(tmp_path / "attempt").execute(
        PolicyScript(
            script_id="recover_with_drift",
            attempt=1,
            code=(
                "def policy(api):\n"
                "    api.recover_stand(height=0.8, ramp_s=6.0, hold_s=2.0)\n"
                "    api.stop_all()\n"
            ),
        ),
        G1SkillAPI(
            backend=StaticSonicSkillBackend(execute=False),
            output_dir=tmp_path / "skills",
            heartbeat_file=tmp_path / "planner_heartbeat.json",
        ),
    )

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="stand_drift",
            target="recover upright clear of target",
            require_robots_exit=True,
        ),
        trace=trace,
        before_state=before,
        stepwise=True,
    )

    assert not report.success
    assert report.failure_type == "robots_not_clear"
    assert report.metrics["robots_clear_after_place"] == 0.0
    assert any(
        "latest crouched checkpoint" in recommendation
        for recommendation in report.recommendations
    )


def test_host_lifecycle_gate_rejects_coder_parameter_drift():
    def make_policy(distance_m: float, speed_mps: float) -> PolicyScript:
        scripts = tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_exit",
                synchronization_group="exit",
                coordination_mode="sync",
                code=(
                    "def policy(api):\n"
                    f"    api.exit_backward(distance_m={distance_m}, "
                    f"speed_mps={speed_mps}, ramp_s=1.5)\n"
                    "    api.stop_all()"
                ),
            )
            for robot_id in ("front", "back")
        )
        return PolicyScript(
            script_id="team_exit",
            attempt=1,
            code=scripts[0].code,
            robot_scripts=scripts,
        )

    gate = {
        "hard_required": True,
        "required_call": "exit_backward(distance_m=0.5, speed_mps=0.50, ramp_s=1.5)",
    }

    with pytest.raises(ModelAgentError, match="exact host lifecycle transaction"):
        _validate_policy_matches_host_lifecycle_gate(make_policy(0.45, 0.2), gate)

    _validate_policy_matches_host_lifecycle_gate(make_policy(0.5, 0.5), gate)


def test_orchestrator_allows_place_setup_but_not_exit_before_release():
    loaded_far_from_target = {
        "payload": {
            "active": True,
            "x": 1.85,
            "y": 6.16,
            "z": 1.10,
            "supporting_robots": ["front", "back"],
            "target_contact": False,
            "floor_contact": False,
            "wall_contacts": [],
        },
        "target": {
            "center_x_m": -1.50,
            "center_y_m": 7.60,
            "payload_center_target_z_m": 0.65,
        },
    }
    plan = {
        "current_phase_id": "phase_06_place_and_exit",
        "global_plan": [
            {
                "phase_id": "phase_06_place_and_exit",
                "abstract_goal": (
                    "Place and release payload, retreat backward crouched, "
                    "then recover upright"
                ),
            }
        ],
        "current_subtask": {
            "strategy": {
                "primitive": "coordinated_linear_transport",
                "coordination_mode": "sync",
                "semantic_objective": "backward",
            },
            "team_assignment": {
                "front": {"role": "front"},
                "back": {"role": "back"},
            },
        },
    }

    _validate_orchestrator_plan_strategy(
        plan,
        allowed_sdk_methods={"coordinated_linear_transport"},
        runtime_state=loaded_far_from_target,
    )

    plan["current_subtask"]["strategy"].update(
        {
            "primitive": "exit_backward",
            "coordination_mode": "sync",
            "semantic_objective": "exit_backward",
        }
    )
    with pytest.raises(
        ModelRoleError,
        match="post-release exit cannot activate",
    ):
        _validate_orchestrator_plan_strategy(
            plan,
            allowed_sdk_methods={"exit_backward"},
            runtime_state=loaded_far_from_target,
        )


