def test_evolution_call_uses_checkpoint_rollback_for_active_payload_support_loss():
    payload = {
        "observation": {
            "runtime_state": {
                "payload": {"active": True, "supporting_robots": ["front"]}
            }
        }
    }
    method, example, reason = _required_evolution_call(payload)

    assert method == ""
    assert example == ""
    assert "checkpoint rollback" in reason
    assert "reinitialized" in reason
    assert {
        "place_payload_on_arms",
        "recover_payload_inward",
        "release_payload",
        "exit_forward",
        "exit_backward",
        "exit_lateral_left",
        "exit_lateral_right",
    }.issubset(_lifecycle_forbidden_methods(payload))
    inactive_forbidden = _lifecycle_forbidden_methods(
        {"observation": {"runtime_state": {"payload": {"active": False}}}}
    )
    assert "place_payload_on_arms" not in inactive_forbidden
    assert "recover_payload_inward" in inactive_forbidden
    assert "release_payload" in inactive_forbidden


