def test_formation_desync_retry_uses_model_selected_alternative(tmp_path):
    rejected_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.050, speed_mps=0.250, ramp_s=2.000)\n"
        "    api.stop_all()"
    )
    repaired_code = (
        "def policy(api):\n"
        "    api.carry_forward(distance_m=0.050, speed_mps=0.200, ramp_s=1.500)\n"
        "    api.stop_all()"
    )
    current = PolicyScript(
        script_id="box_carry_attempt_13",
        attempt=13,
        code=rejected_code,
        robot_scripts=(
            RobotPolicyScript(
                robot_id="front",
                script_id="front_box_carry_attempt_13",
                code=rejected_code,
                synchronization_group="stage1_transport_13",
            ),
            RobotPolicyScript(
                robot_id="back",
                script_id="back_box_carry_attempt_13",
                code=rejected_code,
                synchronization_group="stage1_transport_13",
            ),
        ),
    )
    report = EvaluationReport(
        success=False,
        failure_type="formation_desync",
        failed_subtask="carry_forward",
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_14",
                    "code": rejected_code,
                    **_explicit_team_fields(rejected_code),
                }
            ),
            json.dumps(
                {
                    "script_id": "box_carry_attempt_14",
                    "code": repaired_code,
                    **_explicit_team_fields(repaired_code),
                }
            ),
        ]
    )

    repaired, _spec = ModelCollaborativeEvolutionAgent(tmp_path, client=client).evolve(
        current,
        report,
        _supported_observation(),
    )

    assert repaired.code == repaired_code
    assert (
        "api.carry_forward(distance_m=0.050, speed_mps=0.200, ramp_s=1.500)"
        not in client.prompts[1]["user"]
    )
    assert "OPEN MODEL REPLAN" in client.prompts[1]["user"]
    assert "host has not preselected one" in client.prompts[1]["user"]


def test_unsafe_transport_failure_reprompts_model_before_magnitude_increase(tmp_path):
    rejected_code = (
        "def policy(api):\n"
        "    api.carry_lateral_left(distance_m=0.15, speed_mps=0.25, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    unsafe_escalation = rejected_code.replace("distance_m=0.15", "distance_m=0.20")
    safer_alternative = rejected_code.replace("distance_m=0.15", "distance_m=0.10")
    current = PolicyScript(
        script_id="box_carry_attempt_47",
        attempt=47,
        code=rejected_code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_box_carry_attempt_47",
                code=rejected_code,
                synchronization_group="transport_47",
            )
            for robot_id in ("front", "back")
        ),
    )
    report = EvaluationReport(
        success=False,
        failure_type="formation_desync",
        failed_subtask="carry_lateral_left",
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_48",
                    "code": unsafe_escalation,
                    **_explicit_team_fields(unsafe_escalation),
                }
            ),
            json.dumps(
                {
                    "script_id": "box_carry_attempt_48",
                    "code": safer_alternative,
                    **_explicit_team_fields(safer_alternative),
                }
            ),
        ]
    )

    repaired, _spec = ModelCollaborativeEvolutionAgent(tmp_path, client=client).evolve(
        current,
        report,
        _supported_observation(),
    )

    assert repaired.code == safer_alternative
    assert len(client.prompts) == 2
    correction_prompt = client.prompts[1]["user"]
    assert "may not increase transport magnitude" in correction_prompt
    assert "increases distance_m from the unsafe bound 0.15 to 0.2" in correction_prompt
    assert (
        "host has not selected a skill, direction, route, formation, or coordination pattern"
        in correction_prompt
    )
    assert "one-behind" not in correction_prompt.lower()
    assert "single-file" not in correction_prompt.lower()


def test_pre_dispatch_rejection_blocks_repeated_candidate_transaction(tmp_path):
    rejected_code = (
        "def policy(api):\n"
        "    api.carry_lateral_left(distance_m=0.10, speed_mps=0.15, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    unsafe_candidate = rejected_code.replace("speed_mps=0.15", "speed_mps=0.20")
    safer_candidate = rejected_code.replace("distance_m=0.10", "distance_m=0.05")
    current = PolicyScript(
        script_id="box_carry_attempt_67",
        attempt=67,
        code=rejected_code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_box_carry_attempt_67",
                code=rejected_code,
                synchronization_group="transport_67",
            )
            for robot_id in ("front", "back")
        ),
    )
    report = EvaluationReport(
        success=False,
        failure_type="formation_desync",
        failed_subtask="carry_lateral_left",
    )
    client = FakeModelClient(
        [
            json.dumps(
                {
                    "script_id": "box_carry_attempt_68",
                    "code": unsafe_candidate,
                    **_explicit_team_fields(unsafe_candidate),
                }
            ),
            json.dumps(
                {
                    "script_id": "box_carry_attempt_68",
                    "code": unsafe_candidate,
                    **_explicit_team_fields(unsafe_candidate),
                }
            ),
            json.dumps(
                {
                    "script_id": "box_carry_attempt_68",
                    "code": safer_candidate,
                    **_explicit_team_fields(safer_candidate),
                }
            ),
        ]
    )

    repaired, _spec = ModelCollaborativeEvolutionAgent(tmp_path, client=client).evolve(
        current,
        report,
        _supported_observation(),
    )

    assert repaired.code == safer_candidate
    assert len(client.prompts) == 3
    assert "BLOCKED TEAM TRANSACTION" in client.prompts[1]["user"]
    assert (
        "repeats a verifier-rejected executable transaction"
        in client.prompts[2]["user"]
    )
    assert unsafe_candidate in client.prompts[2]["user"]


