def _formation_sync_linear_policy(
    *,
    attempt: int,
    distance_m: float,
    verification_contract: dict | None = None,
) -> PolicyScript:
    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport("
        f"direction='forward', distance_m={distance_m:g}, "
        "speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    return PolicyScript(
        script_id=f"formation_sync_attempt_{attempt:02d}",
        attempt=attempt,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"{robot_id}_formation_sync_attempt_{attempt:02d}",
                code=code,
                synchronization_group="formation_sync_probe",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
        verification_contract=dict(verification_contract or {}),
    )


def test_formation_sync_repair_gate_persists_until_physical_probe_passes(tmp_path):
    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        coordination_layer_enabled=True,
    )
    rejected = _formation_sync_linear_policy(attempt=6, distance_m=2.0)
    agent._prepare_evolution_evidence(
        rejected,
        EvaluationReport(
            success=False,
            failure_type="formation_desync",
            metrics={
                "front_step_displacement_m": 1.18,
                "back_step_displacement_m": 0.59,
            },
        ),
        ObservationBundle(
            runtime_state={"checkpoint": {"checkpoint_id": "accepted_step_05"}}
        ),
        None,
    )

    gate = agent.formation_sync_repair_gate
    assert gate["active"]
    assert gate["probe_contract"]["required_distance_m"] == pytest.approx(1.0)
    assert gate["probe_contract"]["semantic_objective"] == "forward"
    assert (tmp_path / "formation_sync_repair_gate.json").exists()

    alignment = PolicyScript(
        script_id="accepted_yaw_alignment",
        attempt=7,
        code=(
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='yaw', delta=2, duration_s=2)\n"
            "    api.stop_all()"
        ),
    )
    agent._prepare_evolution_evidence(
        alignment,
        EvaluationReport(success=True, failure_type=""),
        ObservationBundle(
            runtime_state={"checkpoint": {"checkpoint_id": "accepted_step_06"}}
        ),
        None,
    )
    assert agent.formation_sync_repair_gate["active"]
    assert agent.formation_sync_repair_gate["current_checkpoint_id"] == (
        "accepted_step_06"
    )

    restarted = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        coordination_layer_enabled=True,
    )
    assert restarted.formation_sync_repair_gate["active"]

    probe_contract = {
        "kind": "formation_sync_repair_probe",
        "primitive": "coordinated_linear_transport",
        "required_distance_m": 1.0,
    }
    probe = _formation_sync_linear_policy(
        attempt=8,
        distance_m=1.0,
        verification_contract=probe_contract,
    )
    restarted._prepare_evolution_evidence(
        probe,
        EvaluationReport(
            success=True,
            failure_type="",
            evidence={
                "formation_sync_repair_probe": {
                    "passed": True,
                    "normalized_displacement_mismatch": 0.12,
                }
            },
        ),
        ObservationBundle(
            runtime_state={"checkpoint": {"checkpoint_id": "accepted_step_07"}}
        ),
        ExecutionTrace(
            script_id=probe.script_id,
            attempt=probe.attempt,
            status="success",
            verification_contract=probe_contract,
        ),
    )

    assert not restarted.formation_sync_repair_gate["active"]
    assert restarted.formation_sync_repair_gate["status"] == "verified"
    persisted = json.loads(
        (tmp_path / "formation_sync_repair_gate.json").read_text(encoding="utf-8")
    )
    assert not persisted["active"]


