def test_final_approach_exhaustion_requires_policy_and_rejected_transactions():
    plan = {
        "current_phase_id": "phase_05_final_straight",
        "global_plan": [
            {
                "phase_id": "phase_05_final_straight",
                "abstract_goal": "approach the final target",
            }
        ],
    }
    runtime = {
        "payload": {"active": True, "x": -1.28, "y": 6.98},
        "target": {
            "available": True,
            "center_x_m": -1.5,
            "center_y_m": 7.6,
        },
    }
    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport(direction='left', "
        "distance_m=0.5, speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    policy = PolicyScript(
        script_id="final_left",
        attempt=14,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id,
                f"{robot_id}_final_left",
                code,
                "final_left",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )
    short_code = code.replace("distance_m=0.5", "distance_m=0.25")
    short_policy = PolicyScript(
        script_id="final_left_short",
        attempt=15,
        code=short_code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id,
                f"{robot_id}_final_left_short",
                short_code,
                "final_left_short",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
    )
    rejected = {
        _policy_transaction_signature(policy),
        _policy_transaction_signature(short_policy),
    }

    envelope = _final_approach_transport_envelope(
        runtime,
        task_plan=plan,
        policy=policy,
        forbidden_transaction_signatures=rejected,
    )

    assert envelope["active"]
    assert envelope["exhausted"]


