def test_wall_obstruction_supersedes_same_direction_sync_probe(tmp_path):
    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        coordination_layer_enabled=True,
    )
    rejected = _formation_sync_linear_policy(attempt=8, distance_m=2.0)
    report = EvaluationReport(
        success=False,
        failure_type="formation_desync",
        metrics={"wall_contact_count": 1.0},
        evidence={
            "payload": {
                "contacts": {
                    "support_robots": ["front"],
                    "walls": ["wall_04"],
                    "floor": False,
                }
            },
            "visual_verifier": {"evidence": {"wall_collision_or_stuck": True}},
        },
    )

    agent._prepare_evolution_evidence(
        rejected,
        report,
        ObservationBundle(
            runtime_state={"checkpoint": {"checkpoint_id": "accepted_step_05"}}
        ),
        None,
    )

    gate = agent.formation_sync_repair_gate
    assert not gate["active"]
    assert gate["status"] == "superseded_by_route_obstruction"
    assert gate["route_obstruction"]["wall_contacts"] == ["wall_04"]

    analysis = _apply_physics_authoritative_failure_analysis_override(
        _failure_analysis_from_report(report),
        policy=rejected,
        report=report,
        trace=None,
    )
    assert analysis["source"] == ("physics_authoritative_route_obstruction_override")
    assert analysis["strategy_defect"]
    assert not analysis["magnitude_defect"]

    _validate_manager_mutation_level(
        {"mutation_level": "strategy_mutation"},
        report=report,
        failure_analysis=analysis,
        policy=rejected,
        formation_sync_repair_gate={},
    )
    with pytest.raises(ModelRoleError, match="requires strategy_mutation"):
        _validate_manager_mutation_level(
            {"mutation_level": "parameter_tuning"},
            report=report,
            failure_analysis=analysis,
            policy=rejected,
            formation_sync_repair_gate={},
        )


