def test_formal_manager_context_contains_evidence_not_host_repair_contracts(
    tmp_path,
):
    class CapturingRolePipeline:
        current_task_plan = {}

        def __init__(self):
            self.context = {}
            self.output_dir = tmp_path / "model_roles"
            self.output_dir.mkdir(parents=True, exist_ok=True)

        def decide_mutation(
            self,
            context,
            *,
            artifact_id,
            image_path,
            validator,
        ):
            del artifact_id, image_path
            self.context = context
            candidate = {
                "mutation_level": "parameter_tuning",
                "failure_hypothesis": "the bounded motion was too large",
                "evidence": ["physics rollout was rejected"],
                "preserve": ["route intent and team relation"],
                "mutate": ["distance_m"],
                "forbidden": ["exact rejected AST replay"],
                "success_test": "the next rollout passes physics verification",
                "inheritance": ["accepted checkpoint"],
                "confidence": 0.8,
            }
            validator(candidate)
            return candidate

    pipeline = CapturingRolePipeline()
    controller = EvolutionController(
        max_physical_iterations=80,
        output_dir=tmp_path,
        resume_history=False,
    )
    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        evolution_controller=controller,
        role_pipeline=pipeline,
        formal_eval=True,
        route_discovery=True,
    )
    policy = _formation_sync_linear_policy(attempt=26, distance_m=1.5)
    report = EvaluationReport(
        success=False,
        failure_type="route_regression",
        diagnosis="the rejected endpoint entered blocked route space",
        metrics={"payload_step_displacement_m": 0.8},
        evidence={
            "visual_verifier": {
                "evidence": {
                    "failure_analysis": {
                        "outcome": "rejected",
                        "primary_failure": "visible route mismatch",
                        "strategy_defect": True,
                        "coordination_defect": False,
                        "magnitude_defect": False,
                        "source": "vlm_failure_analyzer",
                    }
                }
            },
            "payload": {
                "supporting_robots": ["front", "back"],
                "contacts": {
                    "support_robots": ["front", "back"],
                    "walls": ["wall_test"],
                },
            },
        },
    )

    decision = agent.decide_next_step(
        policy,
        report,
        ObservationBundle(
            runtime_state={"checkpoint": {"checkpoint_id": "accepted_step_02"}}
        ),
        physically_dispatched=True,
    )

    assert decision.repair_level == "execution"
    assert pipeline.context["rejected_endpoint_failure_analysis"]["source"] == (
        "vlm_failure_analyzer"
    )
    guard = pipeline.context["host_controller_guard"]
    assert "repair_level" not in guard
    assert "required_change" not in guard
    route_recovery = pipeline.context["route_recovery_contract"]
    assert route_recovery["active"]
    assert route_recovery["rejected_motion"] == {
        "primitive": "coordinated_linear_transport",
        "semantic_objective": "forward",
    }
    assert "open_body_frame_translations" not in route_recovery
    assert "locally_nonblocked_body_frame_translations" not in route_recovery
    assert "candidate_measurements" not in route_recovery
    assert "alignment_sign_repair_contract" not in pipeline.context
    assert "formation_sync_repair_gate" not in pipeline.context


