def test_checkpoint_route_exclusion_blocks_only_exact_motion_objective():
    def task_plan(direction: str) -> dict:
        return {
            "current_subtask": {
                "strategy": {
                    "primitive": "coordinated_linear_transport",
                    "semantic_objective": direction,
                    "coordination_mode": "sync",
                },
                "team_assignment": {
                    "front": {"role": "synchronized_mover"},
                    "back": {"role": "synchronized_mover"},
                },
            }
        }

    exclusions = ("coordinated_linear_transport:right",)
    with pytest.raises(
        ModelRoleError,
        match="coordinated_linear_transport:right",
    ):
        _validate_orchestrator_plan_strategy(
            task_plan("right"),
            allowed_sdk_methods={"coordinated_linear_transport"},
            formation_gate={},
            nonrelaxable_motion_objectives=exclusions,
        )
    _validate_orchestrator_plan_strategy(
        task_plan("right"),
        allowed_sdk_methods={"coordinated_linear_transport"},
        formation_gate={},
        nonrelaxable_motion_objectives=exclusions,
        model_owns_route=True,
    )
    _validate_orchestrator_plan_strategy(
        task_plan("left"),
        allowed_sdk_methods={"coordinated_linear_transport"},
        formation_gate={},
        nonrelaxable_motion_objectives=exclusions,
    )

    parent = {
        "primitive": "coordinated_linear_transport",
        "semantic_objective": "forward",
        "formation_strategy": "loaded synchronous transport",
        "coordination_mode": "sync",
        "synchronization_intent": "identical bounded motion",
        "team_assignment": {
            "front": {"role": "synchronized_mover"},
            "back": {"role": "synchronized_mover"},
        },
    }

    def mutation(direction: str) -> dict:
        return {
            "mutation_level": "strategy_mutation",
            "parent_strategy": parent,
            "child_strategy": {
                **parent,
                "semantic_objective": direction,
            },
            "changed_dimensions": ["semantic_objective"],
            "inheritance": ["accepted checkpoint"],
        }

    with pytest.raises(
        ModelRoleError,
        match="coordinated_linear_transport:right",
    ):
        _validate_plan_guided_mutation(
            mutation("right"),
            manager_decision={"mutation_level": "strategy_mutation"},
            parent_strategy=parent,
            allowed_sdk_methods={"coordinated_linear_transport"},
            formation_gate={},
            nonrelaxable_motion_objectives=exclusions,
        )
    _validate_plan_guided_mutation(
        mutation("right"),
        manager_decision={"mutation_level": "strategy_mutation"},
        parent_strategy=parent,
        allowed_sdk_methods={"coordinated_linear_transport"},
        formation_gate={},
        nonrelaxable_motion_objectives=exclusions,
        model_owns_route=True,
    )
    _validate_plan_guided_mutation(
        mutation("left"),
        manager_decision={"mutation_level": "strategy_mutation"},
        parent_strategy=parent,
        allowed_sdk_methods={"coordinated_linear_transport"},
        formation_gate={},
        nonrelaxable_motion_objectives=exclusions,
    )


