    pivot_plan = {
        "current_subtask": {
            "strategy": {
                "primitive": "coordinated_pivot",
                "semantic_objective": "counterclockwise",
                "coordination_mode": "async",
            },
            "team_assignment": {
                "front": {"role": "inner"},
                "back": {"role": "outer"},
            },
        }
    }
    _validate_orchestrator_plan_strategy(
        pivot_plan,
        allowed_sdk_methods={
            "coordinated_linear_transport",
            "coordinated_pivot",
        },
        formation_gate={},
        host_wall_clearance=clearance,
        accepted_straight_saturation_contract=contract,
    )


