def _v29_route_clearance_dead_end_fixture(
    *,
    rotation_deg: float = 0.0,
    translation_xy: tuple[float, float] = (0.0, 0.0),
) -> tuple[dict, dict, dict, dict]:
    """Reproduce V29 accepted_step_09 in any rigidly transformed world frame."""

    angle = math.radians(rotation_deg)
    cosine = math.cos(angle)
    sine = math.sin(angle)

    def rotate_vector(vector: tuple[float, float]) -> list[float]:
        x, y = vector
        return [cosine * x - sine * y, sine * x + cosine * y]

    def transform_point(point: tuple[float, float]) -> list[float]:
        x, y = rotate_vector(point)
        return [x + translation_xy[0], y + translation_xy[1]]

    clearance = {
        "available": True,
        "current_wall_contact": False,
        "translation_candidates": {
            "forward": {
                "world_direction_xy": rotate_vector((0.3943, 0.9190)),
                "clearance_m": 0.014,
                "relation": "blocked",
            },
            "backward": {
                "world_direction_xy": rotate_vector((-0.3943, -0.9190)),
                "clearance_m": 1.723,
                "relation": "open",
            },
            "left": {
                "world_direction_xy": rotate_vector((-0.9190, 0.3943)),
                "clearance_m": 0.034,
                "relation": "blocked",
            },
            "right": {
                "world_direction_xy": rotate_vector((0.9190, -0.3943)),
                "clearance_m": 1.770,
                "relation": "open",
            },
        },
        "turn_candidates": {
            "clockwise": {
                "relation": "blocked",
                "max_safe_angle_deg": 0.0,
            },
            "counterclockwise": {
                "relation": "open",
                "max_safe_angle_deg": 30.0,
            },
        },
    }
    guidance = {
        "active": True,
        "segment_id": "generic_connected_passage",
        "world_direction_xy": rotate_vector((0.0, 1.0)),
        "corridor": {"center_xy_m": transform_point((1.35, 5.1))},
        "measured": {"payload_xy_m": transform_point((1.34803, 3.16262))},
    }
    state = _supported_navigation_state(heading_deg=66.99 + rotation_deg)
    state["checkpoint"] = {"checkpoint_id": "accepted_step_09"}
    return {"steps": []}, clearance, guidance, state


def test_v29_route_clearance_dead_end_activates_without_saturation_history():
    history, clearance, guidance, state = _v29_route_clearance_dead_end_fixture()

    contract = _route_clearance_conflict_contract(
        history,
        host_wall_clearance=clearance,
        active_route_guidance=guidance,
        runtime_state=state,
    )

    assert contract["active"] is True
    assert contract["activation_reason"] == (
        "route_aligned_translation_has_no_supported_distance_tier"
    )
    assert contract["route_aligned_translation_directions"] == ["forward"]
    forward = contract["route_aligned_translation_clearance"]["forward"]
    assert forward["route_alignment"] == pytest.approx(0.919, abs=1.0e-3)
    assert forward["clearance_m"] == 0.014
    assert forward["has_supported_distance_tier"] is False
    assert contract["safe_heading_correction_turn_directions"] == [
        "counterclockwise"
    ]
    assert contract["safe_turn_angle_envelopes"]["counterclockwise"][
        "calibrated_angle_choices_deg"
    ] == [10.0, 15.0, 20.0, 30.0]
    assert contract["route_reentry_translation_directions"] == []
    assert contract["clearance_setup_translation_directions"] == [
        "backward",
        "right",
    ]
    assert contract["setup_only"] is True
    assert contract["phase_completion_authorized"] is False

    local = build_local_navigation_contract(
        _visible_passage_navigation_plan((0.0, 1.0)),
        state,
    )
    assert local["heading_aligned"] is True
    validate_strategy_against_local_navigation(
        method="coordinated_pivot",
        objective="counterclockwise",
        contract=local,
        route_clearance_conflict_contract=contract,
    )
    roles = pivot_role_assignment(state, "counterclockwise")
    _validate_orchestrator_plan_strategy(
        {
            "current_subtask": {
                "strategy": {
                    "primitive": "coordinated_pivot",
                    "semantic_objective": "counterclockwise",
                    "coordination_mode": "async",
                },
                "team_assignment": {
                    robot_id: {"role": role}
                    for robot_id, role in roles.items()
                },
            }
        },
        allowed_sdk_methods={
            "coordinated_linear_transport",
            "coordinated_pivot",
        },
        runtime_state=state,
        formation_gate={},
        host_wall_clearance=clearance,
        route_clearance_conflict_contract=contract,
    )
    envelope = _host_wall_turn_angle_envelope(
        "coordinated_pivot",
        "counterclockwise",
        clearance,
        route_clearance_conflict_contract=contract,
    )
    assert envelope["preferred_model_angle_choices_deg"] == [
        10.0,
        15.0,
        20.0,
        30.0,
    ]
    for direction in ("backward", "right"):
        validate_strategy_against_local_navigation(
            method="coordinated_linear_transport",
            objective=direction,
            contract=local,
            route_clearance_conflict_contract=contract,
        )


def test_route_clearance_dead_end_is_rigid_transform_invariant():
    base_fixture = _v29_route_clearance_dead_end_fixture()
    base = _route_clearance_conflict_contract(
        base_fixture[0],
        host_wall_clearance=base_fixture[1],
        active_route_guidance=base_fixture[2],
        runtime_state=base_fixture[3],
    )
    transformed_fixture = _v29_route_clearance_dead_end_fixture(
        rotation_deg=73.0,
        translation_xy=(8.2, -4.7),
    )
    transformed = _route_clearance_conflict_contract(
        transformed_fixture[0],
        host_wall_clearance=transformed_fixture[1],
        active_route_guidance=transformed_fixture[2],
        runtime_state=transformed_fixture[3],
    )

    for key in (
        "activation_reason",
        "route_aligned_translation_directions",
        "safe_heading_correction_turn_directions",
        "route_reentry_translation_directions",
        "clearance_setup_translation_directions",
    ):
        assert transformed[key] == base[key]
    assert transformed["signed_heading_error_to_active_segment_deg"] == pytest.approx(
        base["signed_heading_error_to_active_segment_deg"],
        abs=1.0e-5,
    )


def test_local_navigation_turn_clearance_replan_is_narrow_and_checkpoint_scoped():
    state = _supported_navigation_state(
        heading_deg=109.0,
        turn_episode={
            "active": True,
            "status": "turning",
            "purpose": "local_navigation_turn",
            "reference": "final_target",
            "direction": "counterclockwise",
            "switch_allowed": False,
        },
    )
    state["checkpoint"] = {"checkpoint_id": "accepted_step_18"}
    state["target"] = {
        "available": True,
        "center_x_m": -0.866025,
        "center_y_m": -0.5,
    }
    clearance = {
        "available": True,
        "translation_candidates": {
            "forward": {"relation": "blocked"},
            "backward": {"relation": "open"},
            "left": {"relation": "open"},
            "right": {"relation": "blocked"},
        },
        "turn_candidates": {
            "clockwise": {"relation": "constrained", "max_safe_angle_deg": 24.0},
            "counterclockwise": {"relation": "blocked", "max_safe_angle_deg": 0.0},
        },
        "open_translation_directions": ["backward", "left"],
    }
    contract = _host_wall_turn_clearance_replan_contract(
        runtime_state=state,
        host_wall_clearance=clearance,
    )

    assert contract["active"] is True
    assert contract["scope_checkpoint_id"] == "accepted_step_18"
    assert contract["preserve_turn_direction"] == "counterclockwise"
    assert contract["allowed_translation_directions"] == ["backward", "left"]
    assert contract["setup_only"] is True
    assert (
        _host_wall_turn_episode_replan_kind(
            method="coordinated_linear_transport",
            objective="backward",
            runtime_state=state,
            host_wall_clearance=clearance,
        )
        == "translation"
    )
    assert (
        _host_wall_turn_episode_replan_kind(
            method="coordinated_linear_transport",
            objective="right",
            runtime_state=state,
            host_wall_clearance=clearance,
        )
        == ""
    )

    local = build_local_navigation_contract(
        {
            "current_subtask": {
                "navigation": {
                    "reference": "final_target",
                }
            }
        },
        state,
    )
    assert local["heading_alignment_required"] is True
    with pytest.raises(ValueError, match="No body-frame linear translation"):
        validate_strategy_against_local_navigation(
            method="coordinated_linear_transport",
            objective="backward",
            contract=local,
        )
    validate_strategy_against_local_navigation(
        method="coordinated_linear_transport",
        objective="backward",
        contract=local,
        allow_turn_clearance_replan=True,
    )

    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport(direction='backward', distance_m=0.5, "
        "speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()"
    )
    policy = PolicyScript(
        script_id="turn_clearance_setup",
        attempt=20,
        code=code,
        robot_scripts=tuple(
            RobotPolicyScript(
                robot_id=robot_id,
                script_id=f"turn_clearance_setup_{robot_id}",
                code=code,
                synchronization_group="turn_clearance_setup",
                coordination_mode="sync",
            )
            for robot_id in ("front", "back")
        ),
        verification_contract={
            "local_navigation": local,
            "turn_clearance_replan": contract,
        },
    )
    _validate_policy_turn_preflight(
        policy,
        runtime_state=state,
        turn_episode=state["turn_episode"],
    )

    stale_state = json.loads(json.dumps(state))
    stale_state["checkpoint"]["checkpoint_id"] = "accepted_step_19"
    with pytest.raises(TurnEpisodeError, match="turn-clearance replan contract is stale"):
        _validate_policy_turn_preflight(
            policy,
            runtime_state=stale_state,
            turn_episode=stale_state["turn_episode"],
        )

    wrong_code = code.replace("direction='backward'", "direction='right'")
    wrong_policy = replace(
        policy,
        code=wrong_code,
        robot_scripts=tuple(
            replace(script, code=wrong_code) for script in policy.robot_scripts
        ),
    )
    with pytest.raises(TurnEpisodeError, match="permits exactly one sync"):
        _validate_policy_turn_preflight(
            wrong_policy,
            runtime_state=state,
            turn_episode=state["turn_episode"],
        )

    updated = update_turn_episode(
        state["turn_episode"],
        policy=policy,
        report=EvaluationReport(success=True, failure_type="none"),
        visual_report=None,
        checkpoint_id="accepted_step_19",
    )
    assert updated["active"] is True
    assert updated["status"] == "turning"
    assert updated["direction"] == "counterclockwise"
    assert updated["last_clearance_setup_checkpoint_id"] == "accepted_step_19"

    rejected = update_turn_episode(
        state["turn_episode"],
        policy=policy,
        report=EvaluationReport(
            success=False,
            failure_type="formation_desync",
        ),
        visual_report=None,
        checkpoint_id="accepted_step_18",
    )
    assert rejected["active"] is True
    assert rejected["status"] == "turning"
    assert rejected["direction"] == "counterclockwise"
    assert rejected["switch_allowed"] is False
    assert rejected["clearance_setup_failure_count"] == 1


