def test_turn_preflight_honors_checkpoint_scoped_target_reposition_recovery():
    code = (
        "def policy(api):\n"
        "    api.coordinated_linear_transport(direction='forward', "
        "distance_m=0.5, speed_mps=0.5, ramp_s=1.5)\n"
        "    api.stop_all()\n"
    )
    policy = PolicyScript(
        script_id="target_reposition",
        attempt=37,
        code=code,
        verification_contract={
            "local_navigation": {
                "active": True,
                "reference": "final_target",
                "heading_alignment_required": True,
                "allowed_turn_directions": ["counterclockwise"],
                "translation_directions_within_tolerance": [],
                "declared_direction_matches_locked": True,
            },
            "route_recovery": {
                "active": True,
                "source": "target_bearing_coupled_turn_recovery",
                "scope_checkpoint_id": "accepted_step_30",
            },
        },
    )
    runtime = {
        "checkpoint": {"checkpoint_id": "accepted_step_30"},
        "robots": {
            "front": {"x": 0.0, "y": 0.5, "yaw_rad": 0.0},
            "back": {"x": 0.0, "y": -0.5, "yaw_rad": 0.0},
        },
    }

    _validate_policy_turn_preflight(
        policy,
        runtime_state=runtime,
        turn_episode=empty_turn_episode(),
    )

    stale_runtime = {
        **runtime,
        "checkpoint": {"checkpoint_id": "accepted_step_31"},
    }
    with pytest.raises(TurnEpisodeError, match="route-recovery contract is stale"):
        _validate_policy_turn_preflight(
            policy,
            runtime_state=stale_runtime,
            turn_episode=empty_turn_episode(),
        )


def test_turn_preflight_route_clearance_override_is_narrow_and_checkpoint_scoped():
    history, clearance, guidance, state = _route_clearance_conflict_fixture()
    clearance["turn_candidates"]["counterclockwise"]["max_safe_angle_deg"] = 20.0
    conflict = _route_clearance_conflict_contract(
        history,
        host_wall_clearance=clearance,
        active_route_guidance=guidance,
        runtime_state=state,
    )
    local = build_local_navigation_contract(
        _visible_passage_navigation_plan((0.0, 1.0)),
        state,
    )
    completed_episode = {
        "active": False,
        "status": "completed_with_translation",
        "purpose": "route_turn",
        "direction": "counterclockwise",
        "roles": {"front": "outer", "back": "inner"},
        "translation_pending": True,
    }
    correct = _turn_episode_pivot_policy(
        direction="counterclockwise",
        inner_robot="back",
        angle_deg=15.0,
    )

    with pytest.raises(TurnEpisodeError, match="stop turning"):
        _validate_policy_turn_preflight(
            replace(
                correct,
                verification_contract={"local_navigation": local},
            ),
            runtime_state=state,
            turn_episode=completed_episode,
        )

    wrong_sign = _turn_episode_pivot_policy(
        direction="clockwise",
        inner_robot="front",
        angle_deg=15.0,
    )
    with pytest.raises(TurnEpisodeError, match="stop turning"):
        _validate_policy_turn_preflight(
            replace(
                wrong_sign,
                verification_contract={
                    "local_navigation": local,
                    "route_clearance_conflict": conflict,
                },
            ),
            runtime_state=state,
            turn_episode=completed_episode,
        )

    stale_state = json.loads(json.dumps(state))
    stale_state["checkpoint"]["checkpoint_id"] = "accepted_step_13"
    with pytest.raises(TurnEpisodeError, match="contract is stale"):
        _validate_policy_turn_preflight(
            replace(
                correct,
                verification_contract={
                    "local_navigation": local,
                    "route_clearance_conflict": conflict,
                },
            ),
            runtime_state=stale_state,
            turn_episode=completed_episode,
        )


