def test_generated_pivot_preserves_direction_but_obeys_finite_sweep_angle_cap():
    def pivot_policy(angle_deg: float) -> PolicyScript:
        scripts = []
        for robot_id, role in (("front", "outer"), ("back", "inner")):
            code = (
                "def policy(api):\n"
                "    api.coordinated_pivot("
                "turn_direction='counterclockwise', "
                f"angle_deg={angle_deg!r}, travel_direction='forward', "
                f"duration_s=8.0, role={role!r}, swing_radius_m=0.8)\n"
                "    api.stop_all()"
            )
            scripts.append(
                RobotPolicyScript(
                    robot_id=robot_id,
                    script_id=f"pivot_{robot_id}",
                    code=code,
                    synchronization_group="atomic_pivot",
                    coordination_mode="async",
                )
            )
        return PolicyScript(
            script_id="bounded_counterclockwise_pivot",
            attempt=9,
            code=scripts[0].code,
            robot_scripts=tuple(scripts),
        )

    clearance = {
        "turn_candidates": {
            "counterclockwise": {
                "relation": "constrained",
                "max_safe_angle_deg": 13.0,
            }
        }
    }

    with pytest.raises(ModelAgentError, match="max_safe_angle_deg=13"):
        _validate_policy_within_host_wall_clearance(
            pivot_policy(30.0),
            clearance=clearance,
        )
    _validate_policy_within_host_wall_clearance(
        pivot_policy(13.0),
        clearance=clearance,
    )


