def test_formation_sync_repair_gate_preempts_static_formation_gate():
    report = EvaluationReport(
        success=False,
        failure_type="formation_desync",
    )
    policy = _formation_sync_linear_policy(attempt=8, distance_m=2.0)
    static_formation_gate = {
        "required": True,
        "primitive": "coordinated_alignment",
        "semantic_objective": "longitudinal",
        "coordination_mode": "async",
        "team_roles": {
            "front": "reference",
            "back": "corrector",
        },
    }
    sync_gate = {
        "active": True,
        "failure_count": 1,
        "probe_contract": {"required_distance_m": 1.0},
    }

    _validate_manager_mutation_level(
        {"mutation_level": "parameter_tuning"},
        report=report,
        failure_analysis={"coordination_defect": True},
        policy=policy,
        formation_gate=static_formation_gate,
        formation_sync_repair_gate=sync_gate,
    )

    with pytest.raises(
        ModelRoleError,
        match="requires parameter_tuning",
    ):
        _validate_manager_mutation_level(
            {"mutation_level": "strategy_mutation"},
            report=report,
            failure_analysis={"coordination_defect": True},
            policy=policy,
            formation_gate=static_formation_gate,
            formation_sync_repair_gate=sync_gate,
        )


