def _back_facing_target_navigation_state(
    *,
    rotation_deg: float = 0.0,
    translation_xy: tuple[float, float] = (0.0, 0.0),
) -> dict:
    """Reproduce V17 accepted_step_16 in any translated/rotated world frame."""

    payload_xy = (0.6303562549231021, 7.769384449186844)
    target_xy = (-1.5, 7.6)
    robots = {
        "front": (0.390760207866787, 7.250483826365288, -11.7706),
        "back": (0.5900008451466768, 8.349486054931441, -10.9781),
    }
    angle = math.radians(rotation_deg)

    def transform(x: float, y: float) -> tuple[float, float]:
        return (
            math.cos(angle) * x - math.sin(angle) * y + translation_xy[0],
            math.sin(angle) * x + math.cos(angle) * y + translation_xy[1],
        )

    payload_x, payload_y = transform(*payload_xy)
    target_x, target_y = transform(*target_xy)
    return {
        "checkpoint": {"checkpoint_id": "accepted_step_16"},
        "payload": {
            "active": True,
            "x": payload_x,
            "y": payload_y,
            "z": 1.088,
            "contacts": {
                "robots": ["front", "back"],
                "support_robots": ["front", "back"],
                "walls": [],
                "floor": False,
            },
        },
        "target": {
            "available": True,
            "center_x_m": target_x,
            "center_y_m": target_y,
        },
        "robots": {
            robot_id: {
                "x": transform(x, y)[0],
                "y": transform(x, y)[1],
                "yaw_deg": yaw_deg + rotation_deg,
            }
            for robot_id, (x, y, yaw_deg) in robots.items()
        },
    }


def _final_target_navigation_plan() -> dict:
    return {
        "global_plan": [
            {
                "phase_id": "approach_destination",
                "abstract_goal": "approach the final target",
                "completion_evidence": "payload reaches the placement region",
                "status": "active",
            },
            {
                "phase_id": "deposit_payload",
                "abstract_goal": "place and release the payload",
                "completion_evidence": "payload is physically target-supported",
                "status": "pending",
            },
        ],
        "current_phase_id": "approach_destination",
        "current_subtask": {
            "navigation": {
                "reference": "final_target",
                "arrival_condition": "reach the target with a compatible heading",
            }
        },
    }


def _visible_passage_navigation_plan(
    world_direction_xy: tuple[float, float],
) -> dict:
    return {
        "global_plan": [
            {
                "phase_id": "discover_next_passage",
                "abstract_goal": "follow connected free space",
                "completion_evidence": "the current passage is traversed",
                "status": "active",
            }
        ],
        "current_phase_id": "discover_next_passage",
        "current_subtask": {
            "navigation": {
                "reference": "visible_connected_free_space",
                "arrival_condition": "reach the next connected-space frontier",
                "world_direction_xy": list(world_direction_xy),
            }
        },
    }


def _supported_navigation_state(
    *,
    heading_deg: float,
    turn_episode: dict | None = None,
) -> dict:
    state = _supported_alignment_state()
    state["checkpoint"] = {"checkpoint_id": "accepted_step_08"}
    for robot in state["robots"].values():
        robot.pop("yaw_rad", None)
        robot["yaw_deg"] = heading_deg
    if turn_episode is not None:
        state["turn_episode"] = turn_episode
    return state


def _rotate_team_heading(state: dict, delta_deg: float) -> dict:
    updated = json.loads(json.dumps(state))
    for robot in updated["robots"].values():
        robot["yaw_deg"] += delta_deg
    return updated


def test_visible_passage_world_direction_computes_signed_turn_and_stops_when_aligned():
    plan = _visible_passage_navigation_plan((0.0, 1.0))
    unaligned = build_local_navigation_contract(
        plan,
        _supported_navigation_state(heading_deg=10.0),
    )

    assert unaligned["reference_geometry"] == "world_direction"
    assert unaligned["goal_world_direction_xy"] == [0.0, 1.0]
    assert unaligned["signed_heading_error_deg"] == pytest.approx(80.0)
    assert unaligned["required_turn_direction"] == "counterclockwise"
    validate_strategy_against_local_navigation(
        method="coordinated_pivot",
        objective="counterclockwise",
        contract=unaligned,
    )
    with pytest.raises(ValueError, match="increases the shortest local heading error"):
        validate_strategy_against_local_navigation(
            method="coordinated_pivot",
            objective="clockwise",
            contract=unaligned,
        )

    aligned = build_local_navigation_contract(
        plan,
        _supported_navigation_state(heading_deg=104.0),
    )
    assert aligned["absolute_heading_error_deg"] == pytest.approx(14.0)
    assert aligned["heading_aligned"]
    with pytest.raises(ValueError, match="stop turning"):
        validate_strategy_against_local_navigation(
            method="coordinated_pivot",
            objective="clockwise",
            contract=aligned,
        )
    with pytest.raises(ValueError, match="stop turning"):
        validate_strategy_against_local_navigation(
            method="turn_counterclockwise",
            objective="counterclockwise",
            contract=aligned,
        )
    validate_strategy_against_local_navigation(
        method="coordinated_linear_transport",
        objective="forward",
        contract=aligned,
    )


