def test_visible_passage_turn_locks_direction_until_first_accepted_translation():
    before = _supported_navigation_state(heading_deg=40.0)
    contract = build_local_navigation_contract(
        _visible_passage_navigation_plan((0.0, 1.0)),
        before,
    )
    after = _supported_navigation_state(heading_deg=70.0)
    transition = evaluate_local_navigation_transition(
        contract,
        before,
        after,
        requested_turn_direction="counterclockwise",
    )
    policy = replace(
        _turn_episode_pivot_policy(
            direction="counterclockwise",
            inner_robot="back",
            angle_deg=30.0,
        ),
        verification_contract={"local_navigation": contract},
    )
    episode = update_turn_episode(
        empty_turn_episode(),
        policy=policy,
        report=EvaluationReport(
            success=True,
            failure_type="none",
            evidence={"local_navigation_transition": transition},
        ),
        visual_report=None,
        checkpoint_id="accepted_step_09",
    )

    assert episode["status"] == "local_heading_aligned"
    assert episode["translation_pending"]
    assert episode["world_direction_xy"] == [0.0, 1.0]
    locked_state = _supported_navigation_state(
        heading_deg=70.0,
        turn_episode=episode,
    )
    contradicted = build_local_navigation_contract(
        _visible_passage_navigation_plan((1.0, 0.0)),
        locked_state,
    )
    assert contradicted["goal_world_direction_xy"] == [0.0, 1.0]
    assert not contradicted["declared_direction_matches_locked"]
    with pytest.raises(ValueError, match="locked world_direction_xy"):
        validate_strategy_against_local_navigation(
            method="coordinated_linear_transport",
            objective="forward",
            contract=contradicted,
        )

    completed = update_turn_episode(
        episode,
        policy=_turn_episode_linear_policy(0.5),
        report=EvaluationReport(success=True, failure_type="none"),
        visual_report=None,
        checkpoint_id="accepted_step_10",
    )
    assert completed["status"] == "completed_with_translation"
    assert not completed["translation_pending"]
    unlocked_state = _supported_navigation_state(
        heading_deg=70.0,
        turn_episode=completed,
    )
    new_contract = build_local_navigation_contract(
        _visible_passage_navigation_plan((1.0, 0.0)),
        unlocked_state,
    )
    assert new_contract["goal_world_direction_xy"] == [1.0, 0.0]
    assert new_contract["declared_direction_matches_locked"]


def test_local_turn_route_failure_releases_direction_but_support_failure_preserves_it():
    episode = {
        "schema_version": 3,
        "active": True,
        "status": "turning",
        "purpose": "local_navigation_turn",
        "reference": "visible_connected_free_space",
        "reference_geometry": "world_direction",
        "world_direction_xy": [0.0, 1.0],
        "direction": "counterclockwise",
        "roles": {"front": "outer", "back": "inner"},
        "primitive": "coordinated_pivot",
        "accepted_turn_steps": 1,
        "switch_allowed": False,
        "translation_pending": False,
    }
    policy = _turn_episode_pivot_policy(
        direction="counterclockwise",
        inner_robot="back",
        angle_deg=30.0,
    )

    route_rejected = update_turn_episode(
        episode,
        policy=policy,
        report=EvaluationReport(success=False, failure_type="route_regression"),
        visual_report=None,
        checkpoint_id="accepted_step_08",
    )
    assert not route_rejected["active"]
    assert route_rejected["status"] == "local_direction_replan_required"
    assert route_rejected["switch_allowed"]
    replan_state = _supported_navigation_state(
        heading_deg=40.0,
        turn_episode=route_rejected,
    )
    replanned = build_local_navigation_contract(
        _visible_passage_navigation_plan((1.0, 0.0)),
        replan_state,
    )
    assert replanned["goal_world_direction_xy"] == [1.0, 0.0]

    support_rejected = update_turn_episode(
        episode,
        policy=policy,
        report=EvaluationReport(
            success=False,
            failure_type="payload_not_supported",
        ),
        visual_report=None,
        checkpoint_id="accepted_step_08",
    )
    assert support_rejected["active"]
    assert support_rejected["status"] == "local_execution_repair_required"
    assert not support_rejected["switch_allowed"]
    validate_policy_for_turn_episode(policy, support_rejected)
    validate_policy_for_turn_episode(
        _turn_episode_static_policy(direction="counterclockwise"),
        support_rejected,
    )
    with pytest.raises(TurnEpisodeError, match="turn_direction='counterclockwise'"):
        validate_policy_for_turn_episode(
            _turn_episode_pivot_policy(
                direction="clockwise",
                inner_robot="front",
                angle_deg=15.0,
            ),
            support_rejected,
        )
    with pytest.raises(TurnEpisodeError, match="turn_direction='counterclockwise'"):
        validate_policy_for_turn_episode(
            _turn_episode_static_policy(direction="clockwise"),
            support_rejected,
        )


def test_local_turn_support_failure_preserves_direction_but_opens_executable_repairs():
    parent = {
        "primitive": "coordinated_pivot",
        "semantic_objective": "counterclockwise",
        "formation_strategy": "stationary inner and moving outer",
        "coordination_mode": "async",
        "synchronization_intent": "one loaded turn transaction",
        "team_assignment": {
            "front": {"role": "outer", "objective": "swing forward"},
            "back": {"role": "inner", "objective": "hold pivot"},
        },
    }
    contract = build_mutation_contract(parent)
    local = build_local_navigation_contract(
        _visible_passage_navigation_plan((0.0, 1.0)),
        _supported_navigation_state(heading_deg=10.0),
    )

    _reconcile_mutation_contract_with_local_navigation(
        contract,
        parent_strategy=parent,
        local_navigation_contract=local,
        report=EvaluationReport(
            success=False,
            failure_type="payload_not_supported",
        ),
    )

    assert contract["available_levels"] == [
        "strategy_mutation",
        "coordination_mutation",
        "parameter_tuning",
    ]
    assert contract["local_navigation_reconciliation"]["required_semantic_objective"] == (
        "counterclockwise"
    )
    assert contract["local_navigation_reconciliation"][
        "allowed_shared_heading_implementations"
    ] == ["coordinated_pivot", "turn_counterclockwise"]
    _validate_manager_mutation_level(
        {
            "mutation_level": "strategy_mutation",
            "preserve": ["declared route direction", "payload support"],
            "mutate": ["shared-heading implementation"],
            "inheritance": ["accepted checkpoint"],
        },
        report=EvaluationReport(
            success=False,
            failure_type="payload_not_supported",
        ),
        failure_analysis={
            "strategy_defect": False,
            "coordination_defect": True,
            "magnitude_defect": False,
        },
        policy=replace(
            _turn_episode_pivot_policy(
                direction="counterclockwise",
                inner_robot="back",
                angle_deg=30.0,
            ),
            verification_contract={"local_navigation": local},
        ),
        model_owns_mutation_level=True,
        minimum_structural_mutation=True,
        mutation_contract=contract,
    )

    exhausted_contract = build_mutation_contract(parent)
    _reconcile_mutation_contract_with_local_navigation(
        exhausted_contract,
        parent_strategy=parent,
        local_navigation_contract=local,
        report=EvaluationReport(
            success=False,
            failure_type="payload_not_supported",
        ),
        parameter_envelope_exhausted={
            "primitive": "coordinated_pivot",
            "parameter": "angle_deg",
        },
    )
    assert "strategy_mutation" in exhausted_contract["available_levels"]
    assert "parameter_tuning" not in exhausted_contract["available_levels"]
    assert exhausted_contract["local_navigation_reconciliation"][
        "required_semantic_objective"
    ] == "counterclockwise"


