def test_visible_passage_navigation_is_equivariant_to_scene_rotation():
    original = build_local_navigation_contract(
        _visible_passage_navigation_plan((0.0, 1.0)),
        _supported_navigation_state(heading_deg=10.0),
    )
    angle = math.radians(73.0)
    direction = (-math.sin(angle), math.cos(angle))
    transformed_state = _supported_navigation_state(heading_deg=83.0)
    transformed = build_local_navigation_contract(
        _visible_passage_navigation_plan(direction),
        transformed_state,
    )

    for key in (
        "signed_heading_error_deg",
        "absolute_heading_error_deg",
        "required_turn_direction",
        "preferred_translation_direction",
        "forward_translation_allowed",
    ):
        if isinstance(original[key], float):
            assert transformed[key] == pytest.approx(original[key], abs=1.0e-5)
        else:
            assert transformed[key] == original[key]


def test_accepted_step_16_requires_heading_turn_before_forward_translation():
    state = _back_facing_target_navigation_state()
    contract = build_local_navigation_contract(
        _final_target_navigation_plan(),
        state,
    )

    assert contract["reference"] == "final_target"
    assert contract["absolute_heading_error_deg"] == pytest.approx(164.1, abs=0.5)
    assert contract["required_turn_direction"] == "clockwise"
    assert not contract["forward_translation_allowed"]
    assert contract["translation_directions_within_tolerance"] == []
    with pytest.raises(ValueError, match="bounded coordinated_pivot") as exc_info:
        validate_strategy_against_local_navigation(
            method="coordinated_linear_transport",
            objective="forward",
            contract=contract,
        )
    message = str(exc_info.value)
    assert "semantic_objective in ['clockwise']" in message
    assert "Select one of ['backward']" not in message


def test_accepted_step_16_clockwise_turn_can_repeat_until_target_heading_aligned():
    state = _back_facing_target_navigation_state()
    contract = build_local_navigation_contract(
        _final_target_navigation_plan(),
        state,
    )
    episode = empty_turn_episode()

    for index, yaw_delta in enumerate((-30.0, -30.0, -30.0, -30.0, -20.0), 1):
        validate_strategy_against_local_navigation(
            method="coordinated_pivot",
            objective="clockwise",
            contract=contract,
        )
        after = _rotate_team_heading(state, yaw_delta)
        transition = evaluate_local_navigation_transition(
            contract,
            state,
            after,
            requested_turn_direction="clockwise",
        )
        assert transition["semantic_heading_improved"]
        policy = replace(
            _turn_episode_pivot_policy(
                direction="clockwise",
                inner_robot="front",
                angle_deg=abs(yaw_delta),
                attempt=index,
            ),
            verification_contract={"local_navigation": contract},
        )
        episode = update_turn_episode(
            episode,
            policy=policy,
            report=EvaluationReport(
                success=True,
                failure_type="none",
                evidence={"local_navigation_transition": transition},
            ),
            visual_report=None,
            checkpoint_id=f"accepted_step_{16 + index:02d}",
        )
        state = after
        if index < 5:
            assert episode["active"]
            validate_policy_for_turn_episode(policy, episode)

    assert not episode["active"]
    assert episode["status"] == "local_heading_aligned"
    assert episode["accepted_turn_steps"] == 5


def test_accepted_step_16_rejects_wrong_turn_and_backward_is_not_heading_proof():
    state = _back_facing_target_navigation_state()
    contract = build_local_navigation_contract(
        _final_target_navigation_plan(),
        state,
    )
    with pytest.raises(ValueError, match="increases the shortest local heading error"):
        validate_strategy_against_local_navigation(
            method="coordinated_pivot",
            objective="counterclockwise",
            contract=contract,
        )
    with pytest.raises(ValueError, match="including backward") as exc_info:
        validate_strategy_against_local_navigation(
            method="coordinated_linear_transport",
            objective="backward",
            contract=contract,
        )
    message = str(exc_info.value)
    assert "bounded coordinated_pivot" in message
    assert "semantic_objective in ['clockwise']" in message
    assert "Select one of ['backward']" not in message

    moved = json.loads(json.dumps(state))
    moved["payload"]["x"] -= 0.5
    for robot in moved["robots"].values():
        robot["x"] -= 0.5
    transition = evaluate_local_navigation_transition(contract, state, moved)
    assert not transition["semantic_heading_improved"]
    assert transition["absolute_heading_error_after_deg"] > 150.0


def test_local_navigation_is_equivariant_to_scene_translation_and_rotation():
    original = build_local_navigation_contract(
        _final_target_navigation_plan(),
        _back_facing_target_navigation_state(),
    )
    transformed = build_local_navigation_contract(
        _final_target_navigation_plan(),
        _back_facing_target_navigation_state(
            rotation_deg=73.0,
            translation_xy=(12.5, -4.25),
        ),
    )

    for key in (
        "signed_heading_error_deg",
        "absolute_heading_error_deg",
        "required_turn_direction",
        "preferred_translation_direction",
        "forward_translation_allowed",
    ):
        if isinstance(original[key], float):
            assert transformed[key] == pytest.approx(original[key])
        else:
            assert transformed[key] == original[key]


def test_visual_route_label_cannot_veto_physics_improving_declared_turn(tmp_path):
    runtime_state = tmp_path / "runtime_state.json"
    before = _supported_alignment_state()
    target_bearing_deg = -170.0
    before["target"] = {
        "available": True,
        "center_x_m": 2.0 * math.cos(math.radians(target_bearing_deg)),
        "center_y_m": 2.0 * math.sin(math.radians(target_bearing_deg)),
    }
    after = json.loads(json.dumps(before))
    after["payload"]["x"] = 0.08
    after["payload"]["yaw_deg"] = -15.0
    after["payload"]["live_support_target"]["x"] = 0.08
    for robot in after["robots"].values():
        robot["x"] += 0.08
        robot["yaw_rad"] = math.radians(-15.0)
    runtime_state.write_text(json.dumps(after), encoding="utf-8")
    contract = build_local_navigation_contract(
        _final_target_navigation_plan(),
        before,
    )
    trace = replace(
        _pivot_execution_trace("clockwise", angle_deg=15.0),
        verification_contract={"local_navigation": contract},
    )
    visual = VisualVerifierReport(
        status="ok",
        frame_path=str(tmp_path / "global.png"),
        model_name="test-vlm",
        summary="The team appears to face away from the target.",
        evidence={
            "scene_visible": True,
            "team_heading_relative_to_target": "away",
            "team_heading_relative_to_visible_free_space": (
                "toward_wall_or_blocked_space"
            ),
            "immediate_route_direction_risk": True,
            "route_direction_risk_confirmed": True,
            "route_direction_risk_basis": "executed_motion_into_blocked_space",
            "route_direction_evidence": "visual heading label only",
        },
    )

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="generic_local_turn",
            target="approach a declared target",
            route_discovery=True,
            target_center_x_m=before["target"]["center_x_m"],
            target_center_y_m=before["target"]["center_y_m"],
            require_payload_on_target=False,
        ),
        trace=trace,
        visual_report=visual,
        before_state=before,
        stepwise=True,
    )

    assert report.success
    local = report.evidence["local_navigation_transition"]
    assert local["semantic_heading_improved"]
    assert local["heading_error_improvement_deg"] > 10.0
    assert "route_direction_verification" not in report.evidence


def test_improving_local_turn_is_setup_despite_small_corridor_position_regression():
    task = BoxCarryTask(
        task_id="second_corner_turn",
        target="follow the connected route while carrying",
        route_discovery=True,
        require_payload_on_target=False,
    )
    before = _supported_navigation_state(heading_deg=70.0)
    before["payload"].update({"x": 2.3275, "y": 7.6600})
    after = _rotate_team_heading(before, 11.1)
    after["payload"].update({"x": 2.3375, "y": 7.6755})
    local_contract = build_local_navigation_contract(
        _visible_passage_navigation_plan((-1.0, 0.0)),
        before,
    )
    local_transition = evaluate_local_navigation_transition(
        local_contract,
        before,
        after,
        requested_turn_direction="counterclockwise",
    )
    trace = replace(
        _pivot_execution_trace("counterclockwise", angle_deg=15.0),
        verification_contract={"local_navigation": local_contract},
    )
    report = EvaluationReport(
        success=True,
        failure_type="none",
        metrics={
            "payload_step_displacement_xy_m": 0.0184,
            "team_step_signed_yaw_change_deg": 11.1,
        },
        evidence={"local_navigation_transition": local_transition},
    )
    accepted_steps = [
        {
            "transition_outcome": "ACCEPT_PROGRESS",
            "positive_route_memory_eligible": True,
            "measured_outcome": {"payload_x_m": 1.3, "payload_y_m": 2.4},
        },
        {
            "transition_outcome": "ACCEPT_PROGRESS",
            "positive_route_memory_eligible": True,
            "measured_outcome": {"payload_x_m": 2.6, "payload_y_m": 4.2},
        },
        {
            "transition_outcome": "ACCEPT_PROGRESS",
            "positive_route_memory_eligible": True,
            "measured_outcome": {"payload_x_m": 2.1, "payload_y_m": 7.5},
        },
    ]

    decision = verify_transition(
        task=task,
        report=report,
        trace=trace,
        before_state=before,
        after_state=after,
        accepted_manifest={"steps": accepted_steps},
    )

    assert local_transition["semantic_heading_improved"]
    assert decision.outcome is TransitionOutcome.ACCEPT_SETUP
    assert not decision.positive_route_memory_allowed
    assert decision.evidence[
        "corridor_position_gate_deferred_to_improving_local_correction"
    ]
    assert decision.evidence["route_segment_after"][
        "corridor_envelope_violation_m"
    ] > decision.evidence["route_segment_before"][
        "corridor_envelope_violation_m"
    ]


def test_formal_strategy_mutation_may_reopen_completed_route_turn():
    parent = {
        "primitive": "coordinated_linear_transport",
        "semantic_objective": "forward",
        "formation_strategy": "sync transport",
        "coordination_mode": "sync",
        "synchronization_intent": "move together",
        "team_assignment": {
            "front": {"role": "carrier", "objective": "advance"},
            "back": {"role": "carrier", "objective": "advance"},
        },
    }
    child = {
        "primitive": "coordinated_pivot",
        "semantic_objective": "clockwise",
        "formation_strategy": "stationary inner and moving outer",
        "coordination_mode": "async",
        "synchronization_intent": "continuous loaded turn",
        "team_assignment": {
            "front": {"role": "inner", "objective": "hold pivot"},
            "back": {"role": "outer", "objective": "follow outer arc"},
        },
    }
    mutation = {
        "mutation_level": "strategy_mutation",
        "reason": "replace translation with a shared heading turn",
        "parent_strategy": parent,
        "child_strategy": child,
        "changed_dimensions": [
            "primitive",
            "semantic_objective",
            "coordination_mode",
        ],
        "inheritance": ["preserve bilateral support"],
    }
    runtime_state = {
        "robots": {
            "front": {"x": 0.0, "y": -0.5, "yaw_deg": 0.0},
            "back": {"x": 0.0, "y": 0.5, "yaw_deg": 0.0},
        },
        "turn_episode": {
            "active": False,
            "status": "passage_aligned",
            "purpose": "route_turn",
            "direction": "clockwise",
            "roles": {"front": "inner", "back": "outer"},
            "translation_pending": True,
        },
    }

    _validate_plan_guided_mutation(
        mutation,
        manager_decision={"mutation_level": "strategy_mutation"},
        parent_strategy=parent,
        allowed_sdk_methods={
            "coordinated_linear_transport",
            "coordinated_pivot",
        },
        runtime_state=runtime_state,
        formation_gate={},
        model_owns_route=True,
    )

    with pytest.raises(ModelRoleError, match="live turn episode"):
        _validate_plan_guided_mutation(
            mutation,
            manager_decision={"mutation_level": "strategy_mutation"},
            parent_strategy=parent,
            allowed_sdk_methods={
                "coordinated_linear_transport",
                "coordinated_pivot",
            },
            runtime_state=runtime_state,
            formation_gate={},
            model_owns_route=False,
        )


