def test_unavailable_sync_probe_persists_until_geometry_repair_is_accepted(
    tmp_path,
):
    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        coordination_layer_enabled=True,
    )
    agent._formation_sync_repair_gate = {
        "schema_version": 1,
        "kind": "formation_sync_repair",
        "active": True,
        "status": "probe_required",
        "current_checkpoint_id": "accepted_step_34",
        "failure_count": 0,
        "probe_contract": {
            "primitive": "coordinated_linear_transport",
            "semantic_objective": "forward",
            "required_distance_m": 0.25,
        },
    }
    reconciled = _reconcile_formation_sync_gate_with_final_approach(
        agent.formation_sync_repair_gate,
        final_approach_transport_envelope={"active": True, "exhausted": True},
        runtime_state={"turn_episode": {"active": False, "status": "passage_aligned"}},
    )
    agent._persist_reconciled_formation_sync_gate(reconciled)
    assert agent.formation_sync_repair_gate["probe_unavailable"] is True

    rejected = PolicyScript(
        script_id="rejected_yaw_alignment",
        attempt=111,
        code=(
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='yaw', delta=5.0, duration_s=2.0)\n"
            "    api.stop_all()"
        ),
    )
    agent._update_formation_sync_repair_gate(
        rejected,
        EvaluationReport(success=False, failure_type="no_payload_progress"),
        None,
        checkpoint_id="accepted_step_34",
    )
    assert agent.formation_sync_repair_gate["probe_unavailable"] is True
    assert agent.formation_sync_repair_gate["status"] == "geometry_repair_required"

    accepted = replace(
        rejected,
        script_id="accepted_longitudinal_alignment",
        attempt=112,
        code=(
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='longitudinal', delta=0.1, "
            "duration_s=2.0)\n"
            "    api.stop_all()"
        ),
    )
    agent._update_formation_sync_repair_gate(
        accepted,
        EvaluationReport(success=True, failure_type=""),
        None,
        checkpoint_id="accepted_step_35",
        runtime_state={
            "payload": {"active": True, "x": -1.1, "y": 7.6},
            "target": {
                "available": True,
                "center_x_m": -1.5,
                "center_y_m": 7.6,
            },
            "robots": {
                "front": {"x": -0.8, "y": 8.1, "yaw_deg": 180.0},
                "back": {"x": -1.0, "y": 7.1, "yaw_deg": 180.0},
            },
        },
    )
    assert "probe_unavailable" not in agent.formation_sync_repair_gate


def test_checkpoint_roundtrip_failure_overrides_contradictory_vlm_analysis(
    tmp_path,
):
    report = EvaluationReport(
        success=False,
        failure_type="no_payload_progress",
        diagnosis="alignment transaction produced no durable correction",
        allowed_repairs=(
            "rewrite_alignment_axis_or_moving_reference_relationship",
            "select_a_different_coordination_primitive",
        ),
        forbidden_repairs=(
            "change_alignment_delta_only",
            "repeat_same_alignment_structure",
        ),
        evidence={
            "visual_verifier": {
                "evidence": {
                    "failure_analysis": {
                        "outcome": "accepted",
                        "strategy_defect": False,
                        "coordination_defect": False,
                        "magnitude_defect": True,
                    }
                }
            }
        },
    )
    assert _checkpoint_roundtrip_geometry_repair_failed(report)
    assert _checkpoint_roundtrip_geometry_repair_failed(
        replace(report, failure_type="goal_regression")
    )
    corrected = replace(
        report,
        failure_type="goal_regression",
        allowed_repairs=("change_motion_objective_or_direction",),
        forbidden_repairs=("magnitude_only_retry",),
        evidence={
            "checkpoint_roundtrip_semantic_evaluation": {
                "failure_type": "no_payload_progress",
                "allowed_repairs": [
                    "rewrite_alignment_axis_or_moving_reference_relationship"
                ],
                "forbidden_repairs": ["change_alignment_delta_only"],
            }
        },
    )
    assert _checkpoint_roundtrip_geometry_repair_failed(corrected)
    analysis = _failure_analysis_from_report(report)
    assert analysis["outcome"] == "rejected"
    assert analysis["strategy_defect"] is True
    assert analysis["magnitude_defect"] is False
    assert analysis["source"] == (
        "physics_authoritative_checkpoint_roundtrip_semantic_override"
    )

    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        coordination_layer_enabled=True,
    )
    agent._formation_sync_repair_gate = {
        "schema_version": 1,
        "kind": "formation_sync_repair",
        "active": True,
        "status": "probe_required",
        "current_checkpoint_id": "accepted_step_34",
        "failure_count": 0,
        "probe_contract": {
            "primitive": "coordinated_linear_transport",
            "semantic_objective": "forward",
            "required_distance_m": 0.25,
        },
    }
    policy = PolicyScript(
        script_id="failed_roundtrip_yaw_alignment",
        attempt=111,
        code=(
            "def policy(api):\n"
            "    api.coordinated_alignment(axis='yaw', delta=5.0, duration_s=2.5)\n"
            "    api.stop_all()"
        ),
    )
    agent._update_formation_sync_repair_gate(
        policy,
        report,
        None,
        checkpoint_id="accepted_step_34",
    )
    gate = agent.formation_sync_repair_gate
    assert gate["probe_unavailable"] is True
    assert gate["required_repair"] == "coordinated_alignment"
    assert gate["status"] == "geometry_repair_required"

    with pytest.raises(ModelRoleError, match="requires strategy_mutation"):
        _validate_manager_mutation_level(
            {"mutation_level": "parameter_tuning", "mutate": ["delta"]},
            report=report,
            failure_analysis=analysis,
            policy=policy,
            formation_sync_repair_gate=gate,
        )


