def test_formation_sync_probe_distance_overrides_generic_linear_tier():
    previous = _formation_sync_linear_policy(attempt=8, distance_m=1.0)
    probe = _formation_sync_linear_policy(attempt=9, distance_m=0.5)

    with pytest.raises(ModelAgentError, match="next unblocked tier 0.75"):
        _validate_failure_level_repair(
            previous,
            probe,
            failure_level="execution",
            failure_type="formation_desync",
            blocked_strategy_signatures=set(),
        )

    _validate_failure_level_repair(
        previous,
        probe,
        failure_level="execution",
        failure_type="formation_desync",
        blocked_strategy_signatures=set(),
        formation_sync_probe_distance_m=0.5,
    )


def test_safe_no_progress_sync_probe_advances_one_final_approach_tier(tmp_path):
    agent = ModelCollaborativeEvolutionAgent(
        tmp_path,
        client=FakeModelClient([]),
        coordination_layer_enabled=True,
    )
    agent._formation_sync_repair_gate = {
        "active": True,
        "status": "probe_required",
        "failure_count": 3,
        "current_checkpoint_id": "accepted_step_16",
        "probe_contract": {
            "primitive": "coordinated_linear_transport",
            "semantic_objective": "left",
            "required_distance_m": 0.25,
        },
    }
    policy = _formation_sync_linear_policy(attempt=27, distance_m=0.25)
    report = EvaluationReport(
        success=False,
        failure_type="no_payload_progress",
        evidence={
            "formation_sync_repair_probe": {
                "active": True,
                "passed": False,
                "distance_contract_satisfied": True,
                "no_wall_contact": True,
                "meaningful_actual_progress": False,
            }
        },
    )
    trace = ExecutionTrace(
        script_id=policy.script_id,
        attempt=policy.attempt,
        status="success",
        verification_contract={"kind": "formation_sync_repair_probe"},
    )

    agent._update_formation_sync_repair_gate(
        policy,
        report,
        trace,
        checkpoint_id="accepted_step_16",
    )

    gate = agent.formation_sync_repair_gate
    assert gate["status"] == "probe_magnitude_escalated"
    assert gate["failure_count"] == 0
    assert gate["probe_contract"]["required_distance_m"] == pytest.approx(0.5)
    assert gate["probe_contract"]["magnitude_escalation_pending"]


