def test_formation_sync_physical_probe_accepts_bounded_response_mismatch(tmp_path):
    before = _formation_sync_probe_state()
    after = json.loads(json.dumps(before))
    after["robots"]["front"]["x"] = 0.50
    after["robots"]["back"]["x"] = 0.45
    after["payload"]["x"] = 0.475
    after["payload"]["live_support_target"]["x"] = 0.475
    runtime_state = tmp_path / "runtime_state.json"
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="formation_sync_probe",
            target="verify loaded synchronization",
            route_discovery=True,
        ),
        trace=_formation_sync_probe_trace(),
        before_state=before,
        stepwise=True,
    )

    assert report.success
    probe = report.evidence["formation_sync_repair_probe"]
    assert probe["passed"]
    assert probe["normalized_displacement_mismatch"] == pytest.approx(0.10)


def test_formation_sync_physical_probe_rejects_unbounded_response_mismatch(tmp_path):
    before = _formation_sync_probe_state()
    after = json.loads(json.dumps(before))
    after["robots"]["front"]["x"] = 0.50
    after["robots"]["back"]["x"] = 0.25
    after["payload"]["x"] = 0.375
    after["payload"]["live_support_target"]["x"] = 0.375
    runtime_state = tmp_path / "runtime_state.json"
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="formation_sync_probe",
            target="verify loaded synchronization",
            route_discovery=True,
        ),
        trace=_formation_sync_probe_trace(),
        before_state=before,
        stepwise=True,
    )

    assert not report.success
    assert report.failure_type == "formation_desync"
    probe = report.evidence["formation_sync_repair_probe"]
    assert not probe["passed"]
    assert probe["normalized_displacement_mismatch"] == pytest.approx(0.50)


def test_final_approach_accepts_supported_arrival_despite_probe_mismatch(tmp_path):
    before = _formation_sync_probe_state()
    after = json.loads(json.dumps(before))
    after["robots"]["front"]["x"] = 0.50
    after["robots"]["back"]["x"] = 0.25
    after["payload"]["x"] = 0.375
    after["payload"]["live_support_target"]["x"] = 0.375
    runtime_state = tmp_path / "runtime_state.json"
    runtime_state.write_text(json.dumps(after), encoding="utf-8")

    report = BoxCarryEvaluator(runtime_state).evaluate(
        task=BoxCarryTask(
            task_id="formation_sync_probe",
            target="reach the final placement approach",
            route_discovery=True,
            target_center_x_m=0.375,
            target_center_y_m=0.0,
        ),
        trace=_formation_sync_probe_trace(),
        before_state=before,
        stepwise=True,
        route_phase_id="phase_05_final_straight",
    )

    assert report.success
    probe = report.evidence["formation_sync_repair_probe"]
    assert probe["passed"]
    assert not probe["mismatch_bounded"]
    assert probe["target_placement_override"]
